KB.add({"board":"15","title":"法律、国防与生活科技常识","note":"交大考过：四个军种、四个兵种（2026名解，题目要求按最新军改口径作答）；可撤销婚姻（2026选择）；新中国宪法贡献者与“什么法的第二次修订人”（2023选择，后者题干不全）；铅笔硬度（2023选择）、电饭煲温控（2024选择）、中国第一枚奥运金牌许海峰（2022选择）、“小球带动大球”（2010选择）。这类题分值小、范围散，交大近几年每年至少有一题，按“一句话结论+一个原理”记，不必展开。2026年新增的生态环境法典是今年最可能进选择题的法律热点。","clusters":[{"cid":"15a","name":"宪法、国家制度与国家机构","line":"1949年《共同纲领》起临时宪法作用，1954年制定新中国第一部宪法（b13-020移入此簇），现行宪法1982年通过，经1988、1993、1999、2004、2018年五次修正；宪法确立人民代表大会制度为根本政治制度，规定全国人大、国家主席、国务院、中央军委、国家监察委员会、法院、检察院等国家机构的职权。"},{"cid":"15b","name":"民法典与日常民事规则","line":"2020年通过、2021年1月1日施行的《民法典》是新中国第一部以“法典”命名的法律，共七编；婚姻家庭编规定法定婚龄、无效婚姻与可撤销婚姻（2026选择），总则编规定民事行为能力、法人与诉讼时效；著作权等知识产权与翻译工作直接相关。"},{"cid":"15c","name":"2026年新法与专项立法","line":"2026年3月十四届全国人大四次会议通过生态环境法典（第二部法典，8月15日施行）、民族团结进步促进法（7月1日施行）和国家发展规划法；修订的国家通用语言文字法1月1日施行；网络安全法、数据安全法、个人信息保护法构成数据与网络领域的三部基础法律。"},{"cid":"15d","name":"法学基础：法系、刑法与诉讼","line":"世界两大法系是大陆法系（成文法，以罗马法和《拿破仑法典》为源）和英美法系（判例法）；中华法系以《唐律疏议》为代表；刑法讲罪刑法定等三大原则、五种主刑和刑事责任年龄；诉讼分民事、刑事、行政三大类，实行两审终审。"},{"cid":"15e","name":"国防与军事：军种兵种、战役与兵书","line":"按2024年4月调整后的体制，解放军由陆军、海军、空军、火箭军四个军种和军事航天部队、网络空间部队、信息支援部队、联勤保障部队四个兵种构成，实行“军委管总、战区主战、军种主建”，设五大战区；军衔分将、校、尉三等十级；战史从古代以少胜多的战役到三大战役，兵书以“武经七书”为代表。"},{"cid":"15f","name":"体育常识：奥运与中国第一","line":"现代奥运会由顾拜旦倡议，1896年雅典举办第一届；中国1932年刘长春首次参赛，1984年许海峰夺得首枚奥运金牌；乒乓球从1959年容国团夺得新中国第一个世界冠军到1971年“小球转动大球”的乒乓外交；北京2008年夏奥、2022年冬奥成为“双奥之城”。"},{"cid":"15g","name":"生活中的科学原理","line":"考题都是“一个现象对一个原理”：电饭煲靠磁钢居里点控温，高压锅靠升压提高沸点，微波炉靠水分子振动生热，冰箱靠制冷剂汽化吸热，天空蓝是瑞利散射，彩虹是折射与色散，先见闪电后闻雷声是光速远大于声速；再加上牛顿、爱因斯坦、门捷列夫、达尔文等科学史“之父”与环境常识。"},{"cid":"15h","name":"天文、历法与时间","line":"地球自转产生昼夜和经度时差（每15度差1小时，国际日期变更线大致沿180度经线），公转与地轴倾斜产生四季与南北回归线；公历以回归年为基础定闰年，农历是阴阳合历，以闰月协调；北京时间采用东八区标准时。"},{"cid":"15i","name":"中国地理之最","line":"地势西高东低呈三级阶梯；三大平原（东北最大）、四大高原、四大盆地（塔里木最大）是骨架；长江、黄河与鄱阳湖、青海湖等是“之最”题来源；秦岭淮河一线和胡焕庸线是两条最重要的地理分界线。"}],"entries":[{"id":"b13-020","t":"新中国第一部宪法","cid":"15a","p":1,"kind":"事件","exam":["2023选择"],"alias":["五四宪法","1954年宪法","54宪法"],"one":"1954年9月20日一届全国人大一次会议通过，称“五四宪法”。","ans":"新中国第一部宪法是**1954年9月20日由第一届全国人民代表大会第一次会议通过的《中华人民共和国宪法》**，称“五四宪法”。起草时**毛泽东任宪法起草委员会主席，刘少奇作宪法草案报告**。它取代起临时宪法作用的《共同纲领》，**确立人民代表大会制度**，设国家主席和国防委员会，规定国家过渡时期的总任务，毛泽东当选国家主席。这部宪法奠定了新中国国家制度的基本框架，其基本原则和精神为后来宪法所继承。此后又有1975年、1978年宪法，现行宪法是1982年宪法。","pts":["1954年9月20日一届全国人大一次会议通过","毛泽东主持起草，刘少奇作报告","确立人民代表大会制度，取代《共同纲领》"],"mem":"“五四”两个字拆开：54 年、第一部。人物对应：起草看毛泽东（主席），报告看刘少奇；1982 年那部由叶剑英任修改委员会主任、彭真作报告，两次不要串。年份链：1949《共同纲领》→1954 第一部→1975、1978→1982 现行。","mix":"“新中国宪法贡献者”类题的干扰项常放彭真、叶剑英、胡乔木，他们属于1982年宪法的制定；《共同纲领》是1949年的临时宪法，不是第一部正式宪法；五四宪法与“五四运动”（1919年）没有关系。","mcq":[{"q":"1954年宪法草案的报告人是","o":["周恩来","彭真","叶剑英","刘少奇"],"a":3,"w":"刘少奇作《关于中华人民共和国宪法草案的报告》；1982年宪法修改草案的报告人是彭真。"},{"q":"在新中国成立后，起临时宪法作用的文件是","o":["《共同纲领》","五四宪法","八二宪法","《中华苏维埃共和国宪法大纲》"],"a":0,"w":"1949年《中国人民政治协商会议共同纲领》在1954年宪法颁布前起临时宪法作用。"}],"rel":[{"t":"《中国人民政治协商会议共同纲领》","n":"被五四宪法取代"},{"t":"现行宪法","n":"1982年宪法"},{"t":"人民代表大会制度","n":"由该宪法确立"},{"t":"1787年美国宪法","n":"成文宪法的对照"}],"more":"1954年9月15日至28日一届全国人大一次会议召开，选举毛泽东为国家主席、朱德为副主席。"},{"id":"b15-001","t":"四个军种","cid":"15e","p":1,"kind":"合称","exam":["2026名解"],"alias":["四大军种","陆海空火箭军","解放军四个军种"],"one":"陆军、海军、空军、火箭军，2024年起与四个兵种组成“4+4”结构。","ans":"军种是**军队内按主要作战领域、使命和装备划分的基本类别**。中国人民解放军现有**陆军、海军、空军、火箭军四个军种**。**海军成立于1949年4月23日，空军成立于1949年11月11日**；**火箭军前身是1966年组建的第二炮兵，2015年12月31日更名为火箭军**，是战略威慑的核心力量，陆军领导机构同日成立。2015年底启动的改革形成**“军委管总、战区主战、军种主建”**格局；**2024年4月后形成“4个军种+4个兵种”的新型军兵种结构布局**。","pts":["军种含义与四个名称","海军1949.4.23，空军1949.11.11，第二炮兵更名火箭军","军委管总、战区主战、军种主建；4+4"],"members":[["陆军","陆地作战主体，领导机构2015年底成立"],["海军","1949年4月23日成立"],["空军","1949年11月11日成立"],["火箭军","前身第二炮兵，2015年12月31日更名"]],"mem":"口诀“陆海空箭”：陆、海、空、火箭军。时间对照：海军四月（4.23），空军十一月（11.11，双十一），火箭军 12.31 年末更名。“4+4”：四军种加四兵种，军种看领域，兵种看新兴战略领域。","mix":"战略支援部队已于2024年4月撤销，不再是军种或兵种；火箭军原名第二炮兵，不是“火箭兵”；传统意义的步兵、炮兵、装甲兵是军种内的兵种，与这里四个战略性兵种含义不同。","mcq":[{"q":"中国人民解放军火箭军的前身是","o":["战略支援部队","第二炮兵","陆军炮兵","防空军"],"a":1,"w":"火箭军前身是1966年组建的第二炮兵，2015年12月31日更名。"},{"q":"下列不属于解放军四个军种的是","o":["陆军","火箭军","联勤保障部队","空军"],"a":2,"w":"联勤保障部队是兵种，军种为陆军、海军、空军、火箭军。"}],"rel":[{"t":"四个兵种","n":"“4+4”的另一半"},{"t":"火箭军","n":"军种之一"},{"t":"军种成立纪念日","n":"海空军成立日"},{"t":"军委管总、战区主战、军种主建","n":"体制改革"},{"t":"军队编制序列","n":"编制层级"}],"more":"国防部表述：2024年4月19日起，解放军形成陆军、海军、空军、火箭军等军种，军事航天部队、网络空间部队、信息支援部队、联勤保障部队等兵种的新型结构。"},{"id":"b15-002","t":"四个兵种","cid":"15e","p":1,"kind":"合称","exam":["2026名解"],"alias":["四大兵种","军事航天部队","网络空间部队","信息支援部队","联勤保障部队"],"one":"军事航天、网络空间、信息支援、联勤保障四支战略性兵种。","ans":"按2024年4月改革后的口径，解放军的四个兵种是**军事航天部队、网络空间部队、信息支援部队和联勤保障部队**，属于**在战略新兴领域和重要作战领域相对独立执行任务、也能与其他军兵种联合作战的战略性兵种**。**2015年12月成立的战略支援部队于2024年4月19日撤销，新组建由中央军委直接领导指挥的信息支援部队**，原属战略支援部队的军事航天部队和网络空间部队调整为独立兵种；**联勤保障部队成立于2016年9月**。2025年四支兵种军旗发布，并在九三阅兵中首次集中亮相。","pts":["四个兵种名称，战略性兵种","战略支援部队撤销，信息支援部队新建","联勤保障部队2016年成立；2025年军旗发布"],"members":[["军事航天部队","原战略支援部队的航天力量，独立兵种"],["网络空间部队","原战略支援部队的网络力量，独立兵种"],["信息支援部队","2024年4月19日新组建，军委直接领导"],["联勤保障部队","2016年9月成立，一体化联合保障"]],"mem":"口诀“天、网、信、勤”：航天、网络、信息、联勤。故事线：2015 年战略支援部队成立，2024 年 4 月撤销，拆成三块（航天、网络独立，信息支援新建），加上 2016 年就有的联勤保障部队，共四个。","mix":"这里的“兵种”是独立于四个军种之外的战略性兵种，不同于军种内部的步兵、炮兵、装甲兵；战略支援部队已不存在；火箭军是军种，不是兵种。","mcq":[{"q":"2024年4月组建、由中央军委直接领导指挥的是","o":["军事航天部队","联勤保障部队","网络空间部队","信息支援部队"],"a":3,"w":"信息支援部队于2024年4月19日新组建，战略支援部队同时撤销。"},{"q":"下列属于解放军四个兵种之一的是","o":["火箭军","联勤保障部队","海军陆战队","武警部队"],"a":1,"w":"联勤保障部队是2016年9月成立的兵种。"}],"rel":[{"t":"四个军种","n":"“4+4”的另一半"},{"t":"军队编制序列","n":"编制层级"},{"t":"中央军事委员会","n":"直接领导信息支援部队"},{"t":"建军100周年","n":"2027年建军百年奋斗目标"}],"more":"2025年八一前夕四支兵种军旗发布，九三阅兵中首次集中亮相。"},{"id":"b15-003","t":"民法典","cid":"15b","p":1,"kind":"制度","alias":["《民法典》","中华人民共和国民法典","社会生活的百科全书"],"one":"2021年1月1日施行，新中国第一部以“法典”命名的法律，共7编1260条。","ans":"《中华人民共和国民法典》**2020年5月28日由十三届全国人大三次会议通过，2021年1月1日起施行**，是**新中国第一部以“法典”命名的法律**，被称为**“社会生活的百科全书”**。它共**7编（总则、物权、合同、人格权、婚姻家庭、继承、侵权责任）加附则，1260条**，其中**人格权独立成编**是一大特色。民法典系统整合了婚姻法、继承法、民法总则、物权法、合同法、侵权责任法等民事单行法，原有法律同时废止。它对保护民事权利、推进国家治理体系和治理能力现代化具有基础性作用。","pts":["2020年通过，2021年1月1日施行，首部法典","7编1260条，人格权独立成编","整合并废止单行法"],"mem":"数字：20（2020 通过）、21（2021 施行）、7 编、1260 条。七编顺序用“总物合，人婚继侵”：总则、物权、合同，人格权、婚姻家庭、继承、侵权责任。画面：先立规则（总则），再分财产（物权、合同），再写人（人格、婚姻、继承），最后兜底追责（侵权）。","mix":"民法典没有“知识产权编”和“债权编”，债权规则分散在总则、合同和侵权责任编；第二部法典是2026年的生态环境法典，不要说成第一部；《民法通则》《婚姻法》等已被废止。","mcq":[{"q":"《民法典》的施行日期是","o":["2020年5月28日","2021年1月1日","2020年1月1日","2021年7月1日"],"a":1,"w":"2020年5月28日通过，2021年1月1日起施行。"},{"q":"下列各项中，不属于《民法典》七编之一的是","o":["人格权编","侵权责任编","知识产权编","婚姻家庭编"],"a":2,"w":"民法典没有知识产权编，知识产权由《著作权法》《专利法》《商标法》等单行法规定。"}],"rel":[{"t":"民法典七编","n":"七编名称与顺序"},{"t":"生态环境法典","n":"第二部法典"},{"t":"罗马法与《民法大全》","n":"民法法典化的渊源"},{"t":"《拿破仑法典》","n":"外国民法典对照"},{"t":"民法基本原则","n":"总则编规定"}],"more":"编别条文：总则1至204条，物权205至462条，合同463至988条（最长），人格权989至1039条，婚姻家庭1040至1118条，继承1119至1163条，侵权责任1164至1258条，附则1259至1260条。","exam":[]},{"id":"b15-004","t":"可撤销婚姻","cid":"15b","p":1,"kind":"制度","exam":["2026选择"],"alias":["婚姻撤销","撤销婚姻"],"one":"因胁迫或一方婚前隐瞒重大疾病，可请求法院撤销的婚姻。","ans":"可撤销婚姻是指**已经成立的婚姻因欠缺真实意思等法定事由，受害一方可以请求人民法院撤销的婚姻**，规定在《民法典》婚姻家庭编。法定事由有两种：一是**因胁迫结婚（第1052条）**，受胁迫一方请求撤销，应自胁迫行为终止之日起一年内提出，被非法限制人身自由的，自恢复人身自由之日起一年内提出；二是**一方患有重大疾病、婚前未如实告知（第1053条）**，另一方请求撤销，应自知道或应当知道撤销事由之日起一年内提出。**婚姻被撤销后自始没有法律约束力**。","pts":["受害方请求法院撤销的婚姻","两种事由：胁迫；婚前未告知重大疾病","一年内提出；撤销后自始无效"],"mem":"“两因一年一法院”：两种原因（胁迫、瞒病），一年内提出，只能向人民法院请求。记忆对照：无效婚姻“重、亲、龄”三种（重婚、近亲、不到婚龄），可撤销婚姻“胁、病”两种。胁迫看“人被逼”，瞒病看“人被骗”，都是意思表示不真实。","mix":"无效婚姻（第1051条）是重婚、有禁止结婚的亲属关系、未到法定婚龄，当事人之外的利害关系人也可请求宣告；可撤销婚姻只有受害一方可以提出，且有一年期限。民法典把“婚前患有医学上认为不应当结婚的疾病”由无效事由改为“未如实告知”的可撤销事由。","mcq":[{"q":"下列情形中，属于可撤销婚姻的是","o":["重婚","一方因受胁迫而结婚","未到法定婚龄","三代以内旁系血亲结婚"],"a":1,"w":"因胁迫结婚属可撤销婚姻，其余三项是无效婚姻的情形。"},{"q":"请求撤销胁迫婚姻，应当向哪个机关提出","o":["婚姻登记机关","人民调解委员会","人民法院","公安机关"],"a":2,"w":"民法典规定只能向人民法院请求撤销。"}],"rel":[{"t":"无效婚姻","n":"常对举考查"},{"t":"民法典","n":"婚姻家庭编所在"},{"t":"法定婚龄与民事行为能力","n":"未到婚龄导致无效"},{"t":"法定继承顺序","n":"婚姻家庭编之后的继承编"}],"more":"《民法典》第1052条（胁迫）、第1053条（隐瞒重大疾病）、第1054条（无效或被撤销的婚姻自始没有法律约束力）。"},{"id":"b15-005","t":"生态环境法典","cid":"15c","p":1,"kind":"制度","alias":["《生态环境法典》","中华人民共和国生态环境法典"],"one":"2026年8月15日施行，我国第二部法典，世界首部生态环境法典。","ans":"《中华人民共和国生态环境法典》**2026年3月12日由十四届全国人大四次会议通过，2026年8月15日（第四个全国生态日）起施行**，是**继民法典之后我国第二部以“法典”命名的法律，也是世界上第一部以“生态环境”命名的法典**。法典采取**“适度法典化”**模式，**共5编1242条：总则、污染防治、生态保护、绿色低碳发展、法律责任和附则**，整合了环境保护法等30多部法律的规范，确立“用最严格制度最严密法治保护生态环境”。它标志着生态环境保护进入**法典化时代**，为建设美丽中国提供法治保障。","pts":["2026年通过，8月15日施行，第二部法典","适度法典化，5编1242条","世界首部以生态环境命名的法典"],"mem":"数字串：3 月 12 日通过（植树节，生态主题），8 月 15 日施行（全国生态日），5 编 1242 条。顺序用逻辑线：先总则，再治污染（防），再护生态（保），再谈绿色低碳（发展），最后讲责任。“第二”对“第一”：民法典 2021 年，生态环境法典 2026 年，相隔五年。","mix":"第一部法典是民法典，生态环境法典是第二部；它整合的是环境保护法等30多部法律，没有把所有环境类法律都并入，所以叫“适度法典化”；全国生态日是8月15日，与世界环境日（6月5日）、植树节（3月12日）不同。","mcq":[{"q":"我国第二部以“法典”命名的法律是","o":["刑法典","生态环境法典","行政法典","教育法典"],"a":1,"w":"民法典之后，2026年3月通过的《生态环境法典》是第二部法典。"},{"q":"《生态环境法典》的施行日期是","o":["2026年1月1日","2026年3月12日","2026年8月15日","2027年1月1日"],"a":2,"w":"2026年8月15日，即第四个全国生态日起施行。"}],"rel":[{"t":"生态环境法典五编","n":"五编结构"},{"t":"全国生态日","n":"施行日"},{"t":"民法典","n":"第一部法典"},{"t":"《环境保护法》","n":"被整合的法律之一"}],"more":"法典采取“适度法典化”，整合环境保护法等30多部法律；2026年8月15日是第四个全国生态日（首个全国生态日为2023年）。","exam":[]},{"id":"b15-006","t":"民族团结进步促进法","cid":"15c","p":1,"kind":"制度","alias":["《民族团结进步促进法》","民促法"],"one":"2026年3月通过、7月1日施行，7章65条，单设序言。","ans":"《中华人民共和国民族团结进步促进法》**2026年3月12日由十四届全国人大四次会议通过，7月1日起施行**，**共7章65条**，是**30多年来第一部设置序言的法律**（2026年6月24日国新办发布会）。立法目的是**促进民族团结进步，铸牢中华民族共同体意识**，推进中华民族共同体建设。法律围绕**构筑共有精神家园、促进交往交流交融、推动共同繁荣发展**作出规定，要求推进**互嵌式社区环境建设**，重申各民族一律平等、禁止民族歧视并设法律责任专章，规定**每年9月第四周为民族团结进步宣传周**。","pts":["2026年3月通过，7月1日施行，7章65条，单设序言","目的：铸牢中华民族共同体意识","互嵌式社区；民族平等；9月第四周宣传周"],"mem":"数字：7 章 65 条，7 月 1 日施行（与民族团结的“7”呼应）。三大板块用“精神家园、交往交流交融、共同繁荣”三句话记。宣传周对照：推普周是 9 月第三周，民族团结进步宣传周是 9 月第四周，三、四顺序。","mix":"国家通用语言文字推广普及宣传周是9月第三周，民族团结进步宣传周是第四周；该法与《民族区域自治法》（1984年通过）不同，后者规定自治地方的自治权；《民族团结进步促进法》的核心词是“铸牢中华民族共同体意识”。","mcq":[{"q":"《民族团结进步促进法》规定的民族团结进步宣传周为","o":["每年9月第二周","每年9月第三周","每年9月第四周","每年10月第一周"],"a":2,"w":"每年9月第四周为民族团结进步宣传周；9月第三周是推广普及国家通用语言文字宣传周。"},{"q":"《民族团结进步促进法》的施行日期是","o":["2026年1月1日","2026年7月1日","2026年8月15日","2026年10月1日"],"a":1,"w":"2026年3月12日通过，7月1日起施行。"}],"rel":[{"t":"铸牢中华民族共同体意识","n":"立法目的"},{"t":"民族区域自治制度与五个自治区","n":"基本政治制度"},{"t":"国家通用语言文字法","n":"同年修订施行，宣传周相邻"},{"t":"少数民族传统节日","n":"民族文化常识"}],"more":"法律规定“中华民族共同体意识是民族团结之本”（第六条）。","exam":[]},{"id":"b15-007","t":"国家通用语言文字法","cid":"15c","p":1,"kind":"制度","alias":["《国家通用语言文字法》","语言文字法"],"one":"2001年施行，2025年底修订、2026年1月1日起施行。","ans":"《中华人民共和国国家通用语言文字法》**2000年10月31日通过、2001年1月1日施行，是我国第一部语言文字方面的专门法律**，规定**国家通用语言文字是普通话和规范汉字**。**2025年12月27日全国人大常委会完成时隔25年的首次修订，新法共5章32条，2026年1月1日起施行**。修订后立法目的写入铸牢中华民族共同体意识，**加强国家通用语言文字教育**，**增加网络空间用语用字规范**，推动语言文字信息技术创新，**法律责任单设一章**，并明确每年**9月第三周为推广普及宣传周**。","pts":["2001年施行，普通话和规范汉字","2025年修订，2026年1月1日施行，5章32条","网络用语用字规范；9月第三周推普周"],"mem":"年份挂钩：2000 通过、2001 施行（新世纪第一部语言法），2025 修订、2026 施行，相隔 25 年。新法三个新增点：网络、教育、法律责任单设一章。推普周是“九月第三周”，民族团结进步宣传周是“九月第四周”，三、四相邻。","mix":"国家通用语言文字是普通话和规范汉字，不是“汉语和汉字”；该法2001年起施行，2026年1月1日是修订后的施行日；《汉字简化方案》是1956年国务院公布的，不是该法的内容。","mcq":[{"q":"修订后的《国家通用语言文字法》自哪一天起施行","o":["2025年12月27日","2026年1月1日","2026年7月1日","2026年9月1日"],"a":1,"w":"2025年12月27日完成修订，2026年1月1日起施行。"},{"q":"我国推广普及国家通用语言文字宣传周的时间是","o":["每年9月第三周","每年9月第四周","每年10月第一周","每年12月第一周"],"a":0,"w":"法律明确每年9月第三周为推广普及宣传周。"}],"rel":[{"t":"推广普通话","n":"法律的核心任务"},{"t":"《汉字简化方案》与推广普通话","n":"1956年，2026年70周年"},{"t":"网络流行语与语言规范","n":"新增网络空间用语用字"},{"t":"民族团结进步促进法","n":"宣传周相邻，同为2026年新法"}],"more":"1956年国务院公布《汉字简化方案》并发出推广普通话的指示，2026年为70周年。\n2025年全国普通话普及率为87.72%。\n448大作文考过语言规范话题：2011届“我看字母词”、2012届“我看港台腔”。","exam":[]},{"id":"b15-008","t":"现行宪法","cid":"15a","p":1,"kind":"制度","exam":["2023选择"],"alias":["八二宪法","1982年宪法","现行《宪法》","中华人民共和国宪法"],"one":"1982年12月4日通过的现行宪法，国家根本法，已五次修正。","ans":"现行宪法指**1982年12月4日由五届全国人大五次会议通过的《中华人民共和国宪法》**，简称“八二宪法”，是国家的根本法，具有最高法律效力。它是新中国第四部宪法，此前有1954年、1975年、1978年三部。现行宪法先后于**1988、1993、1999、2004、2018年五次修正**，2018年把**习近平新时代中国特色社会主义思想写入宪法，增设国家监察委员会**。**全国人大修改宪法，全国人大常委会解释宪法**，二者共同监督宪法实施。2014年起**12月4日为国家宪法日**，2016年起实行宪法宣誓制度。","pts":["1982年12月4日通过，此前三部","五次修正，2018年写入新思想、增设监委","根本法；人大修宪、常委会释宪；宪法日"],"mem":"四部宪法年份连起来是 54、75、78、82，只有 54 年那部是“新中国第一部”，82 年的是现行。五次修正年份用内容挂钩：88 土地与私营经济，93 市场经济，99 依法治国，04 人权与私产，18 新思想与监委，首字串成“地市法人监”。修宪与释宪的区别：“修”字对应大会（全国人大），“释”字对应常委会。","mix":"修改宪法的是全国人大（须全体代表三分之二以上多数通过），解释宪法的是全国人大常委会，选择题常把二者对调；12月4日是国家宪法日，勿与12月10日世界人权日混淆。","mcq":[{"q":"我国现行宪法通过于","o":["1954年","1975年","1978年","1982年"],"a":3,"w":"现行宪法是1982年12月4日通过的“八二宪法”，1954年宪法是新中国第一部宪法。"},{"q":"根据宪法，有权解释宪法的机关是","o":["全国人民代表大会","全国人大常委会","国务院","最高人民法院"],"a":1,"w":"全国人大修改宪法，全国人大常委会解释宪法，二者都监督宪法实施。"}],"rel":[{"t":"新中国第一部宪法","n":"1954年宪法，现行宪法的前身"},{"t":"现行宪法的五次修正","n":"逐次修正的内容"},{"t":"国家宪法日","n":"12月4日"},{"t":"宪法宣誓制度","n":"2016年起实行"},{"t":"1787年美国宪法","n":"世界第一部成文宪法对照"}],"more":"1982年宪法的制定：1980年设宪法修改委员会，叶剑英任主任委员，宋庆龄、彭真任副主任委员，胡乔木任秘书长；1982年11月26日彭真作宪法修改草案报告，12月4日通过。\n结构：序言加四章（总纲，公民的基本权利和义务，国家机构，国旗国歌国徽首都），共143条。\n2022年12月4日是现行宪法公布施行40周年。"},{"id":"b15-009","t":"铅笔硬度","cid":"15g","p":1,"kind":"常识","exam":["2023选择"],"alias":["铅笔型号","2B铅笔","HB铅笔","H与B"],"one":"H表示硬，B表示黑，黏土越多越硬越淡，石墨越多越软越黑。","ans":"铅笔硬度指**铅笔芯软硬和深浅的等级**，用字母加数字表示。**H代表Hard（硬），B代表Black（黑）**，**HB软硬适中**。铅笔芯由**石墨和黏土**按比例混合烧制而成：**黏土比例越高，笔芯越硬、字迹越淡；石墨比例越高，笔芯越软、字迹越黑**。H前数字越大越硬，B前数字越大越软越黑。**涂答题卡用2B铅笔**，因为2B颜色较深，易被机读识别，又不至于太软涂污；写字画图常用HB和H。","pts":["H硬、B黑，HB适中","黏土多则硬淡，石墨多则软黑","答题卡用2B"],"mem":"字母来历：H = Hard（硬），B = Black（黑）。数字放在字母前，越大越极端：同一系列中，6B 比 2B 软而深，6H 比 2H 硬而淡。画面：黏土像“沙子”让笔变硬变淡，石墨像“墨”让笔变软变黑。","mix":"B前数字越大越黑越软，H前数字越大越硬越淡，二者方向相反；HB在中间，F介于HB和H之间；答题卡用2B是为了机读识别，不是越黑越好。","mcq":[{"q":"铅笔芯中，黏土比例越高，铅笔","o":["越软越黑","越硬越淡","越软越淡","越硬越黑"],"a":1,"w":"黏土比例越高笔芯越硬、字迹越淡；石墨比例越高越软越黑。"},{"q":"填涂机读答题卡通常使用的铅笔是","o":["HB","2H","2B","6H"],"a":2,"w":"2B颜色较深、易识别，是涂答题卡的常用型号。"}],"rel":[{"t":"电饭煲温控","n":"同为生活科学常识"},{"t":"高压锅","n":"同为生活科学常识"},{"t":"微波炉","n":"同为生活科学常识"}]},{"id":"b15-010","t":"电饭煲温控","cid":"15g","p":1,"kind":"常识","exam":["2024选择"],"alias":["居里点","磁钢限温器","电饭锅"],"one":"机械电饭煲靠磁钢在居里点（约103℃）失磁，水干后自动断电保温。","ans":"机械式电饭煲靠**磁钢限温器**控温，核心原理是**居里点**，即**铁磁性材料失去磁性的临界温度**（由皮埃尔·居里发现）。感温软磁体的居里点约为**103℃**：水未烧干时锅底温度保持在约100℃，达不到居里点；**水烧干后温度升至103℃，软磁体失去磁性，与永磁体分离，在弹簧作用下切断加热，转入保温**。电子式电饭煲则用**热敏电阻**测温并由芯片控制。这一设计使煮饭不必看守，水干即停。","pts":["磁钢限温器，感温软磁体居里点约103℃","水干升温，失磁分离，断电保温","电子式用热敏电阻"],"mem":"关键词“居里点”：磁铁在这个温度“失磁”。逻辑线：水沸腾 100℃ 且不再升温，居里点 103℃ 高于沸点，所以水在锅里时不会断电；水干后温度才超过 103℃，磁性消失，开关弹起断电。","mix":"居里点是失去磁性的温度，不是磁性最强的温度；居里夫人是放射性元素的发现者，居里点以皮埃尔·居里命名；控温靠温度，与水的沸点相联系但不等于沸点；电子式电饭煲不用磁钢。","mcq":[{"q":"机械式电饭煲在饭熟后自动断电，依靠的是","o":["磁钢在居里点失去磁性","热敏电阻测温","水蒸气推动开关","定时器"],"a":0,"w":"感温磁钢达到居里点失去磁性，与永磁体分离，断开加热电路。"},{"q":"电饭煲锅内水未烧干时不会跳闸，原因是","o":["水的沸点高于居里点","水沸腾时温度约100℃，低于感温磁钢居里点","水会吸收磁性","锅盖压住开关"],"a":1,"w":"水沸腾时约100℃，低于居里点（约103℃），水干后温度升高才跳闸。"}],"rel":[{"t":"高压锅","n":"同为厨房原理题"},{"t":"微波炉","n":"同为厨房原理题"},{"t":"电磁炉与白炽灯","n":"同类电器题"},{"t":"铅笔硬度","n":"同为生活科学常识"}],"more":"感温软磁体居里点约103℃；保温阶段由保温温控器维持约60至80℃（不同机型有差异）。"},{"id":"b15-011","t":"许海峰","cid":"15f","p":1,"kind":"人物","exam":["2022选择"],"alias":["中国奥运首金","零的突破"],"one":"1984年洛杉矶奥运会射击冠军，中国第一枚奥运金牌获得者。","ans":"许海峰是**中国射击运动员，安徽和县人**。**1984年洛杉矶奥运会上，他夺得男子手枪慢射金牌，这是中国运动员获得的第一枚奥运金牌，实现了中国奥运金牌“零的突破”**。中国此前1932年由刘长春首次参加奥运会，1984年是新中国恢复参赛后的重要一届，中国队在这届奥运会上共获得15枚金牌，居金牌榜第四位。许海峰的夺金鼓舞了国民信心，成为中国体育发展的标志性事件，此后中国在奥运赛场不断取得突破。","pts":["射击运动员，1984年洛杉矶奥运会","男子手枪慢射金牌，中国首枚奥运金牌","“零的突破”，中国队共15金"],"mem":"两个人两个年份：1932 刘长春（第一个参赛），1984 许海峰（第一枚金牌）。“洛杉矶”是两次“第一次”的发生地，只是隔了 52 年。画面：他握着手枪站在靶场，一枪打出中国金牌“零的突破”。","mix":"刘长春是1932年中国首次参加奥运会的运动员，没有夺牌；容国团是1959年新中国第一个世界冠军（乒乓球），不是奥运冠军；中国第一枚冬奥会金牌是2002年杨扬（短道速滑）。","mcq":[{"q":"中国获得的第一枚奥运金牌的项目是","o":["举重","射击","乒乓球","体操"],"a":1,"w":"1984年许海峰在男子手枪慢射项目夺金，是中国首枚奥运金牌。"},{"q":"许海峰夺得中国首枚奥运金牌的赛事是","o":["1980年莫斯科奥运会","1984年洛杉矶奥运会","1988年汉城奥运会","1992年巴塞罗那奥运会"],"a":1,"w":"1984年洛杉矶奥运会，中国“零的突破”。"}],"rel":[{"t":"中国首次参加奥运会","n":"1932年刘长春"},{"t":"容国团","n":"首个世界冠军"},{"t":"第一届现代奥运会","n":"奥运起点"},{"t":"乒乓外交","n":"体育与外交"}],"more":"1984年洛杉矶奥运会，中国15金8银9铜，居金牌榜第四。"},{"id":"b15-012","t":"容国团","cid":"15f","p":2,"kind":"人物","exam":["2010选择"],"alias":["新中国第一个世界冠军"],"one":"1959年夺第25届世乒赛男单冠军，新中国首位世界冠军。","ans":"容国团（1937–1968）是**中国著名乒乓球运动员和教练员**。**1959年**，他在联邦德国多特蒙德**第25届世乒赛**上勇夺**男子单打冠军**，成为**新中国体育史上第一个世界冠军**。1961年第26届北京世乒赛上，他喊出**“人生能有几回搏”**并助中国首夺男团冠军；1965年又率女队首夺女团冠军。他的突破开启了中国乒乓球辉煌，激励了几代国人。","pts":["1959年第25届世乒赛男单冠军，多特蒙德","新中国体育史上第一个世界冠军","名言“人生能有几回搏”，助夺男团女团冠军"],"mem":"中国体育“首个”梯队：**1932刘长春**（首次参加奥运）→ **1959容国团**（新中国首个世界冠军）→ **1984许海峰**（夏奥首金）→ **2002杨扬**（冬奥首金）。容国团绑“1959、25届、人生能有几回搏”。","mix":"容国团是新中国第一个“世界冠军”（1959年世乒赛），不是奥运冠军；1971年“乒乓外交”的中国运动员代表是庄则栋，不是容国团。","mcq":[{"q":"1959年在第25届世界乒乓球锦标赛上夺得男单冠军、成为新中国第一个世界冠军的是","o":["容国团","庄则栋","许海峰","刘长春"],"a":0,"w":"容国团于1959年第25届世乒赛夺得男单冠军，是新中国首位世界冠军；庄则栋参与1971年乒乓外交。"}],"rel":[{"t":"乒乓外交","n":"同属中国乒乓球历史里程碑"},{"t":"许海峰","n":"1984年夏奥首金对照"},{"t":"杨扬","n":"2002年冬奥首金对照"}],"more":"名言：人生能有几回搏！此时不搏，更待何时！｜1961年第26届世乒赛"},{"id":"b15-013","t":"乒乓外交","cid":"15f","p":2,"kind":"事件","exam":["2010选择"],"alias":["小球转动大球","小球推动大球"],"one":"1971年4月美国乒乓球队访华，“小球转动大球”促中美解冻。","ans":"乒乓外交是**1971年中美以乒乓球互访打破外交坚冰**的历史事件。当年日本名古屋**第31届世乒赛**期间，中国选手**庄则栋**与美国选手**科恩**友好交往；毛泽东、周恩来果断邀请**美国乒乓球队于1971年4月访华**。这一民间破冰被誉为**“小球转动大球”**。它打破中美长期隔绝，直接促成1972年尼克松访华，为中美关系解冻铺路。","pts":["1971年4月美国乒乓球队应邀访华","起于第31届名古屋世乒赛庄则栋与科恩交往","被称“小球转动大球”，为中美关系解冻铺路"],"mem":"中美破冰链条：**1971.4 乒乓外交**（名古屋世乒赛，庄则栋+科恩，小球转大球）→ **1972.2 尼克松访华与《上海公报》** → **1979 正式建交**。2026年是乒乓外交55周年。","mix":"乒乓外交发生于1971年4月，中国选手主角是庄则栋，不要误记为1959年夺冠的容国团，也不要与1972年尼克松访华的年份混淆。","mcq":[{"q":"1971年被誉为“小球转动大球”、为中美关系解冻铺路的“乒乓外交”中，与美国运动员科恩友好交往的中国选手是","o":["容国团","徐寅生","李富荣","庄则栋"],"a":3,"w":"1971年第31届名古屋世乒赛期间，庄则栋与美国选手科恩友好交往，促成当年4月美国乒乓球队访华。"}],"rel":[{"t":"容国团","n":"同属中国乒乓球史名篇"},{"t":"尼克松访华","n":"乒乓外交直接促成的突破"},{"t":"《上海公报》","n":"1972年中美关系正常化文件"},{"t":"中美三个联合公报","n":"中美建交的政治基础"}],"more":"关键年份：1971年4月（2026年为55周年）；地点缘起：日本名古屋第31届世界乒乓球锦标赛。"},{"id":"b15-014","t":"全国生态日","cid":"15c","p":2,"kind":"常识","alias":["8·15全国生态日"],"one":"2023年起每年8月15日，源于2005年安吉余村提出“绿水青山就是金山银山”。","ans":"全国生态日是**我国生态文明宣传教育的国家级纪念日**，日期为**每年8月15日**。**2023年6月28日**，十四届全国人大常委会第三次会议决定自2023年起设立。选定该日源于**2005年8月15日**在**浙江安吉余村**首次提出**“绿水青山就是金山银山”**。**2026年8月15日**恰逢《生态环境法典》正式施行，推动生态理念化为全民行动。","pts":["2023年全国人大常委会设立，每年8月15日","源于2005年浙江安吉余村提出“两山”理念","2026年8月15日恰逢《生态环境法典》施行"],"mem":"三条线绑在8月15日：2005年余村首提“两山” → 2023年设全国生态日 → 2026年《生态环境法典》正式施行。一个日期串起二十年生态法治史。","mix":"世界环境日是每年6月5日（联合国设立），全国生态日是每年8月15日（中国全国人大常委会设立），注意不要把国际日与国内日混为一谈。","mcq":[{"q":"我国将每年8月15日设立为“全国生态日”，这一日期纪念的历史节点是","o":["2005年在浙江安吉余村首次提出“绿水青山就是金山银山”","1972年联合国人类环境会议在斯德哥尔摩召开","2015年《巴黎协定》正式达成","2020年我国宣布“双碳”目标"],"a":0,"w":"2005年8月15日习近平在浙江安吉余村首次提出“绿水青山就是金山银山”科学论断，2023年据此设立全国生态日。"}],"rel":[{"t":"“绿水青山就是金山银山”","n":"全国生态日设立缘起"},{"t":"生态环境法典","n":"2026年8月15日正式施行"},{"t":"生态环境法典五编","n":"生态法治化体系结构"},{"t":"碳达峰碳中和","n":"生态文明建设核心目标"}],"exam":[]},{"id":"b15-015","t":"铸牢中华民族共同体意识","cid":"15c","p":1,"kind":"概念","alias":["中华民族共同体意识","铸牢共同体意识","五个认同"],"one":"新时代党的民族工作主线，核心是增进“五个认同”。","ans":"铸牢中华民族共同体意识是**新时代党的民族工作的主线**，目标是使各族人民形成对中华民族的整体认同。其核心是增进**“五个认同”：对伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义的认同**。这一提法**2017年党的十九大写入党章，2021年中央民族工作会议确立为民族工作主线**，2026年施行的**《民族团结进步促进法》第六条规定“中华民族共同体意识是民族团结之本”**。理论依据之一是费孝通概括的**“中华民族多元一体格局”**。","pts":["新时代民族工作主线","五个认同：祖国、民族、文化、党、社会主义","2017年入党章；2026年入法"],"mem":"五个认同按“国、族、文、党、道”记：祖国、中华民族、中华文化、中国共产党、中国特色社会主义（道路）。时间线：2017 十九大入党章，2021 民族工作会议定主线，2026《民族团结进步促进法》入法。","mix":"“中华民族多元一体格局”是费孝通1988年提出的理论概括，“铸牢中华民族共同体意识”是政策主线，二者是理论与政策的关系；五个认同里是“中国特色社会主义”，不是“社会主义制度”之类的变体。","mcq":[{"q":"下列不属于“五个认同”的是","o":["对伟大祖国的认同","对中华文化的认同","对各民族传统习俗的认同","对中国共产党的认同"],"a":2,"w":"五个认同是伟大祖国、中华民族、中华文化、中国共产党、中国特色社会主义。"},{"q":"“中华民族多元一体格局”理论的提出者是","o":["梁启超","费孝通","钱穆","孙中山"],"a":1,"w":"费孝通1988年概括提出“中华民族多元一体格局”。"}],"rel":[{"t":"民族团结进步促进法","n":"2026年入法"},{"t":"民族区域自治制度与五个自治区","n":"民族工作的制度基础"},{"t":"习近平新时代中国特色社会主义思想","n":"理论来源"}],"exam":[]},{"id":"b15-016","t":"国家发展规划法","cid":"15c","p":2,"kind":"制度","alias":["《中华人民共和国国家发展规划法》","发展规划法"],"one":"2026年3月12日通过施行，共6章38条，规范五年规划与“三级四类”体系。","ans":"《国家发展规划法》是**规范国家发展规划制定、实施与监督的基础性法律**，**2026年3月12日**经十四届全国人大四次会议通过并施行，共**6章38条**。它规范**五年规划纲要**的编制、审批、实施与监督，确立**“三级四类”体系**：国家发展规划为统领，国土空间规划为基础，专项与区域规划为支撑。规划由**国务院编制、全国人大批准**，保障蓝图落地。","pts":["2026年3月12日全国人大通过并公布施行","共6章38条，规范五年规划编制审批与监督","明确“三级四类”体系，国务院编、全国人大批"],"mem":"记数字与分工：“2026年3月12日（植树节）当场施行，6章38条，三级四类”。体系记“一统领（国家发展规划）、一基础（国土空间规划）、两支撑（专项、区域规划）”。","mix":"十四届全国人大四次会议2026年3月12日同时通过三部大法：《国家发展规划法》自公布之日起即施行，《民族团结进步促进法》7月1日施行，《生态环境法典》8月15日施行，施行日期各不相同。","mcq":[{"q":"根据2026年施行的《国家发展规划法》，在国家规划体系中居于“统领”地位的是","o":["国土空间规划","国家发展规划","区域规划","专项规划"],"a":1,"w":"该法明确以国家发展规划为统领，以国土空间规划为基础，以专项规划和区域规划为支撑。"}],"rel":[{"t":"五年规划","n":"本法规范的核心对象"},{"t":"“十五五”规划","n":"2026年同期审查批准的规划"},{"t":"生态环境法典","n":"2026年全国两会同期通过"},{"t":"民族团结进步促进法","n":"2026年全国两会同期通过"}],"more":"六章结构：总则、国家发展规划的编制、审查和批准、实施、实施的监督、附则，共38条；2026年3月12日主席令第72号公布。","exam":[]},{"id":"b15-017","t":"法定婚龄与民事行为能力","cid":"15b","p":2,"kind":"制度","alias":["法定婚龄","民事行为能力","民事权利能力"],"one":"婚龄男22女20；行为能力18完全、16自食其力视为完全、8岁为限。","ans":"法定婚龄与民事行为能力是**《民法典》规定的自然人基础年龄规则**。婚姻家庭编规定，婚龄**男不得早于22周岁，女不得早于20周岁**。总则编规定，**18周岁以上**为完全民事行为能力人，**16周岁以上**以劳动收入为主要生活来源者视为完全民事行为能力人；**8周岁以上**未成年人为限制、不满8周岁为无民事行为能力人。**民事权利能力始于出生、终于死亡**。","pts":["法定婚龄：男22周岁、女20周岁","行为能力：18完全，16打工视为完全，8岁分界","民事权利能力从出生时起到死亡时止"],"mem":"记一串数字阶梯：“0生权利，8分无与限，16打工算完全，18成年全行为，20女婚22男婚”。8岁节点要记清：2017年民法总则已把旧法10岁下调为8岁。","mix":"民事权利能力（出生即有，人人平等）与民事行为能力（依年龄和精神状态分级）极易混淆；原《民法通则》的限制行为能力下限是10周岁，《民法典》已改为8周岁。","mcq":[{"q":"根据《民法典》，自然人具备限制民事行为能力的最低年龄标准是","o":["8周岁","10周岁","14周岁","16周岁"],"a":0,"w":"《民法典》第19条规定，八周岁以上的未成年人为限制民事行为能力人，不满八周岁的为无民事行为能力人。"}],"rel":[{"t":"民法典","n":"总则编与婚姻家庭编规定"},{"t":"无效婚姻","n":"未达法定婚龄致婚姻无效"},{"t":"刑事责任年龄","n":"民法与刑法年龄线对照"},{"t":"法人","n":"自然人之外的民事主体"}],"exam":[]},{"id":"b15-018","t":"无效婚姻","cid":"15b","p":1,"kind":"制度","alias":["婚姻无效"],"one":"重婚、近亲、未到法定婚龄三种情形的婚姻，自始无效。","ans":"无效婚姻是指**因违反法律强制性规定而自始不发生婚姻效力的婚姻**。依《民法典》第1051条，有三种情形：**重婚；有禁止结婚的亲属关系（直系血亲或三代以内旁系血亲）；未到法定婚龄**（男不得早于22周岁，女不得早于20周岁）。无效婚姻**自始没有法律约束力**，当事人不具有夫妻的权利和义务，同居期间所得财产由当事人协议处理，无过错方有权请求损害赔偿。它与可撤销婚姻不同，后者只有受害一方可在一年内请求法院撤销。","pts":["三种情形：重婚、近亲、未到婚龄","自始没有法律约束力","区别于可撤销婚姻"],"mem":"三字口诀“重、亲、龄”：重婚、亲属、年龄。对照可撤销的“胁、病”两字。顺口连起来：无效重亲龄，可撤胁与病。","mix":"患重大疾病不告知属于可撤销，不属于无效；胁迫结婚属于可撤销，不属于无效；没有办理结婚登记属于“未登记”问题，不在第1051条的三种情形之内。","mcq":[{"q":"根据《民法典》，下列婚姻无效的是","o":["因受胁迫而结婚","一方婚前隐瞒重大疾病","双方为堂兄妹","年龄相差悬殊"],"a":2,"w":"三代以内旁系血亲（如堂兄妹）禁止结婚，其婚姻无效；胁迫和瞒病属可撤销。"},{"q":"《民法典》规定的法定婚龄是","o":["男20周岁，女18周岁","男22周岁，女20周岁","男22周岁，女22周岁","男21周岁，女19周岁"],"a":1,"w":"法定婚龄为男不得早于22周岁，女不得早于20周岁。"}],"rel":[{"t":"可撤销婚姻","n":"常对举考查"},{"t":"法定婚龄与民事行为能力","n":"未到婚龄导致无效"},{"t":"民法典七编","n":"婚姻家庭编"}],"exam":[]},{"id":"b15-019","t":"联合国海洋法公约的海域划分","cid":"15e","p":2,"kind":"制度","alias":["联合国海洋法公约","UNCLOS","专属经济区","领海","毗连区"],"one":"1982年通过的国际海洋法典，自基线起划定12、24、200海里海域。","ans":"《联合国海洋法公约》于**1982年通过、1994年生效，1996年中国批准**，是海洋法基本法典。海域均**从领海基线量起**：**领海不超过12海里**，享主权；**毗连区不超过24海里**，管制海关、财政、移民、卫生；**专属经济区不超过200海里**，享资源主权权利，他国享航行飞越自由；以外为**公海**，各国不得主张主权。公约确立了现代海洋秩序。","pts":["1982年通过、1994年生效、1996年中国批准","均从基线量起：领海12、毗连24、专属经济区200","领海享主权，专属经济区享资源主权权利，外为公海"],"mem":"数字口诀：**“12领、24毗、200专属，全从基线量”**。毗连区四项管制记谐音“海财移卫”（海关、财政、移民、卫生）。年份梯队：82通过→94生效→96中国批准（2026年为中国批准30周年）。","mix":"常见陷阱是把24海里或200海里说成“从领海外缘量起”，实际12、24、200海里全部从领海基线量起；沿海国对专属经济区享有的是“资源主权权利”而非领土“主权”。","mcq":[{"q":"根据《联合国海洋法公约》，关于海域宽度和法律地位的说法正确的是","o":["毗连区从领海外缘量起不超过24海里","沿海国对200海里专属经济区享有完全领土主权","领海宽度从领海基线量起不超过24海里","专属经济区从领海基线量起不超过200海里"],"a":3,"w":"领海12海里、毗连区24海里、专属经济区200海里均从领海基线量起；专属经济区享有的是资源主权权利。"}],"rel":[{"t":"联合国","n":"主导制定公约的国际组织"},{"t":"中国人民武装警察部队","n":"海警担负海上维权执法"},{"t":"世界海洋之最","n":"海洋地理常识对照"}],"more":"关键日期：1982年蒙特哥湾通过，1994年11月16日生效，1996年5月15日中国全国人大常委会批准（2026年为30周年）。","exam":[]},{"id":"b15-020","t":"法人","cid":"15b","p":3,"kind":"概念","alias":["法定代表人"],"one":"具有民事权利与行为能力，依法独立享有权利承担义务的组织。","ans":"法人是《民法典》总则编确立的民事主体，指具有**民事权利能力和民事行为能力**，依法独立享有民事权利、承担民事义务的**组织**。我国分为**营利、非营利、特别法人**三类，代表其履职的负责人称**法定代表人**，确立了独立担责机制。","pts":["依法独立享有民事权利、承担民事义务的组织","分营利法人、非营利法人、特别法人三类","法定代表人是代表法人从事民事活动的负责人"],"mem":"望文易错纠正：“法人是组织，法定代表人才是人”。三大分类记“营、非、特”：公司属营利，学校医院多属非营利，机关村委属特别法人。","mix":"日常生活中常把公司老板或董事长误称“法人”，实则公司本身才是法人，老板或董事长担任的是“法定代表人”；法人的权利能力与行为能力同时产生、同时消灭。","mcq":[{"q":"某有限责任公司董事长张三对外签署购销合同，下列法律称谓正确的是","o":["张三是该公司的法人","该公司是自然人主体","该公司是法人，张三是法定代表人","该公司属于特别法人"],"a":2,"w":"法人是组织而非自然人，公司本身为营利法人，代表公司履职的负责人是法定代表人。"}],"rel":[{"t":"民法典","n":"总则编核心主体概念"},{"t":"民法典七编","n":"归属第一编总则编"},{"t":"法定婚龄与民事行为能力","n":"自然人与法人对照"},{"t":"诉讼时效","n":"同属民法典总则编"}],"exam":[]},{"id":"b15-022","t":"《立法法》","cid":"15a","p":2,"kind":"制度","alias":["中华人民共和国立法法","立法法"],"one":"规范立法活动与法律位阶的基本法律，2023年第二次修正。","ans":"《中华人民共和国立法法》是**规范国家立法权限、程序与法律位阶**的基本法律，属宪法相关法。该法**2000年制定**，2015年首次修正，**2023年3月**十四届全国人大一次会议第二次修正。它规定法律保留、备案审查与效力层级，2023年将**基层立法联系点**和**区域协同立法**入法，并扩大设区的市基层治理立法权。作为“管法的法”，它维护法制统一。","pts":["规范立法权限、程序与位阶的“管法的法”","2000年制定，2015、2023年两次修正","2023年写入基层立法联系点与区域协同立法"],"mem":"年份串联记“2000、2015、2023”：千禧年诞生，十五年一修，二十三年二修。核心功能记三件事：谁能立法（权限）、怎么立法（程序）、谁大谁小（位阶）。","mix":"《立法法》由全国人大制定和修改，属于基本法律，效力低于《宪法》；2015年修法赋予所有设区的市地方立法权，2023年才新增“基层治理”事项。","mcq":[{"q":"关于《中华人民共和国立法法》，下列说法正确的是","o":["与《宪法》具有同等最高法律效力","2023年第二次修正写入了基层立法联系点和区域协同立法","自2000年制定以来尚未进行过修改","由国务院制定并负责在全国范围解释"],"a":1,"w":"《立法法》2000年制定，经2015年、2023年两次修正，2023年修法将基层立法联系点和区域协同立法写入法律。"}],"rel":[{"t":"法律效力位阶","n":"《立法法》核心规范内容"},{"t":"全国人民代表大会","n":"制定和修改基本法律"},{"t":"现行宪法","n":"《立法法》的立法依据"},{"t":"全过程人民民主","n":"基层立法联系点的体现"}],"more":"关键时间：2000年3月15日通过；2015年3月15日第一次修正；2023年3月13日第二次修正，3月15日起施行。","exam":[]},{"id":"b15-023","t":"《个人信息保护法》","cid":"15c","p":2,"kind":"制度","alias":["个保法","中华人民共和国个人信息保护法"],"one":"我国首部个人信息保护专门法，2021年11月1日施行，规制大数据杀熟。","ans":"《个人信息保护法》简称“个保法”，是**我国首部个人信息保护专门法律**。该法2021年8月由全国人大常委会通过，自**2021年11月1日**起施行。它确立以**“告知同意”**为核心的处理规则，严禁过度收集与**“大数据杀熟”**，重点保护生物识别、医疗金融及**不满14周岁未成年人**等敏感信息并规范跨境提供，与网安法、数安法构成数字治理三支柱。","pts":["首部个人信息保护专门法，2021年11月1日施行","确立“告知同意”规则，规制大数据杀熟","与网安法、数安法构成数字治理三支柱"],"mem":"数字法治“三驾马车”按施行先后记：2017年6月1日《网络安全法》（管网络）→ 2021年9月1日《数据安全法》（管数据）→ 2021年11月1日《个人信息保护法》（管个人，11·1三个1像“一个人”）。","mix":"三部法律侧重不同：《网络安全法》管网络运行与关键设施，《数据安全法》管国家数据分类分级与安全，《个人信息保护法》直接保护自然人隐私与个人信息权益。","mcq":[{"q":"我国首部个人信息保护专门法律《个人信息保护法》正式施行于","o":["2017年6月1日","2021年9月1日","2021年11月1日","2025年5月20日"],"a":2,"w":"《个人信息保护法》2021年11月1日施行；2017年6月1日为《网络安全法》，2021年9月1日为《数据安全法》。"}],"rel":[{"t":"《数据安全法》","n":"数字治理三法之一"},{"t":"《网络安全法》","n":"数字治理三法之一"},{"t":"跨境数据流动","n":"本法重点规范领域"},{"t":"隐私计算","n":"合规保护个人数据的技术"}],"exam":[]},{"id":"b15-024","t":"《数据安全法》","cid":"15c","p":2,"kind":"制度","alias":["数安法","中华人民共和国数据安全法"],"one":"我国首部数据领域基础性法律，2021年9月1日施行，确立分类分级保护。","ans":"《数据安全法》是**我国数据领域首部基础性法律**，旨在保障数据安全与开发利用。该法2021年6月由全国人大常委会通过，自**2021年9月1日**起施行。它确立**数据分类分级保护制度**，对关系国家安全与经济命脉的**国家核心数据**实行严格管理，并建立风险评估、预警与安全审查机制，坚持**发展与安全并重**，为数字中国与数据要素市场提供法治底座。","pts":["我国首部数据领域基础法，2021年9月1日施行","确立数据分类分级保护，严管国家核心数据","坚持安全与发展并重，护航数据要素市场"],"mem":"记住施行日期：2021年9月1日（开学日学“数”据），比《个人信息保护法》（2021年11月1日）早整整两个月。核心关键词认准“分类分级保护”与“国家核心数据”。","mix":"《数据安全法》保护的“数据”既包括电子形式也包括非电子形式的各类信息记录，涵盖公共数据、企业数据与核心数据，保护范围远大于个人隐私。","mcq":[{"q":"明确确立国家“数据分类分级保护制度”和“国家核心数据”严格管理制度的法律是","o":["《民法典》","《网络安全法》","《个人信息保护法》","《数据安全法》"],"a":3,"w":"2021年9月1日施行的《数据安全法》确立了数据分类分级保护制度与国家核心数据管理制度。"}],"rel":[{"t":"《个人信息保护法》","n":"同年11月施行的姊妹法"},{"t":"《网络安全法》","n":"网络与数据法治三支柱"},{"t":"数据要素","n":"本法护航的新型生产要素"},{"t":"数字中国","n":"国家信息化顶层战略"}],"exam":[]},{"id":"b15-025","t":"《网络安全法》","cid":"15c","p":2,"kind":"制度","alias":["网安法","中华人民共和国网络安全法"],"one":"我国网络空间治理首部基础法，2017年施行，2025年修改、2026年施行。","ans":"《网络安全法》是**我国网络空间治理首部基础性法律**，维护网络空间主权。该法2016年通过，**2017年6月1日**起施行，建立**网络安全等级保护**、**关键信息基础设施**保护与实名制等制度。**2025年10月**完成首次修改，自**2026年1月1日**施行，写入总体国家安全观，增设**人工智能安全与发展**条款并加大处罚，与数安法、个保法并称数字三支柱。","pts":["我国首部网络安全基础法，2017年6月1日施行","确立等级保护与关键信息基础设施保护制度","2025年修改、2026年施行，增设AI安全条款"],"mem":"时间锚点：“17年六一首施行，26年元旦新修版上路”。三支柱里它出生最早（2017），管的是底层的“网”和“关键设施”，2025年修法顺应AI时代补上人工智能条款。","mix":"选择题问三部法中施行最早的，选2017年6月1日的《网络安全法》；2025年10月28日通过的修改决定已于2026年1月1日生效，别把它当成从未修改过的旧法。","mcq":[{"q":"2025年10月首次修改、自2026年1月1日起施行并增设人工智能安全与发展条款的法律是","o":["《数据安全法》","《个人信息保护法》","《民法典》","《网络安全法》"],"a":3,"w":"《网络安全法》2017年6月1日首施，2025年10月28日首次修改并自2026年1月1日起施行，新增人工智能安全与发展条款。"}],"rel":[{"t":"《数据安全法》","n":"数字治理三法之一"},{"t":"《个人信息保护法》","n":"数字治理三法之一"},{"t":"网络强国","n":"本法服务的国家战略"},{"t":"总体国家安全观","n":"2025年修法写入总则"},{"t":"人工智能治理","n":"2025年修法增设AI条款"}],"more":"关键时间：2016年11月7日通过，2017年6月1日起施行；2025年10月28日十四届全国人大常委会第十八次会议首次修改（主席令第61号），2026年1月1日起施行。","exam":[]},{"id":"b15-026","t":"《国家安全法》","cid":"15c","p":3,"kind":"制度","alias":["国家安全法","全民国家安全教育日"],"one":"2015年7月1日施行，确定每年4月15日为全民国家安全教育日。","ans":"《国家安全法》是我国维护国家安全的**综合性、基础性法律**，居国安法治体系统领地位。**2015年7月1日**施行，以**总体国家安全观**为指导，覆盖政治、国土、网络等领域，并将每年**4月15日**定为**全民国家安全教育日**，筑牢安全屏障。","pts":["2015年7月1日施行，国家安全基础性法律","以总体国家安全观为指导，涵盖多领域安全","确定每年4月15日为全民国家安全教育日"],"mem":"双日子挂钩：“7月1日建党节施行国安法，4月15日记‘是一五’（2015年）全民国安日”。2014年4月15日首次提出总体国家安全观，故将4月15日定为教育日。","mix":"4月15日是全民国家安全教育日，9月第三个星期六是全民国防教育日，12月4日是国家宪法日，三者日期常作为选择题互相干扰。","mcq":[{"q":"根据2015年施行的《国家安全法》，我国“全民国家安全教育日”是每年的","o":["7月1日","9月第三个星期六","12月4日","4月15日"],"a":3,"w":"《国家安全法》第十四条规定每年4月15日为全民国家安全教育日。"}],"rel":[{"t":"总体国家安全观","n":"立法核心指导思想"},{"t":"《网络安全法》","n":"网络领域配套国安立法"},{"t":"《数据安全法》","n":"数据领域配套国安立法"},{"t":"全民国防教育日","n":"国家专题教育日对照"}],"exam":[]},{"id":"b15-027","t":"《监察法》","cid":"15a","p":2,"kind":"制度","alias":["中华人民共和国监察法","监察法"],"one":"2018年通过的反腐败国家立法，设国家监委，2024年修正。","ans":"《中华人民共和国监察法》是**规范国家监察工作**的基本法律，属宪法相关法。该法**2018年3月**由全国人大通过并施行，设立**国家监察委员会**及地方各级监委，实现公职人员**监察全覆盖**。**2024年12月**首次修正，自**2025年6月1日**起施行，完善监察权限、程序与再派出制度，将国家监察体制改革成果定型为法治制度。","pts":["2018年3月通过，设立国家监察委员会","实现对行使公权力的公职人员监察全覆盖","2024年12月首次修正，2025年6月1日施行"],"mem":"时间线配事件：2018年修宪同时通过《监察法》，挂牌国家监委；2024年底首次修法，2025年儿童节（6月1日）施行。把“18建委，24修法，25施行”连成一线。","mix":"监察委员会行使监察权，独立于行政、审判和检察机关，形成“一府一委两院”格局；留置是监察措施，不属于刑事强制措施。","mcq":[{"q":"2024年12月全国人大常委会修正后的《监察法》正式施行于","o":["2024年12月25日","2025年1月1日","2025年3月15日","2025年6月1日"],"a":3,"w":"十四届全国人大常委会第十三次会议于2024年12月25日通过修改决定，自2025年6月1日起施行。"}],"rel":[{"t":"国家监察委员会","n":"依本法设立的最高监察机关"},{"t":"现行宪法的五次修正","n":"2018年修宪增设监察委"},{"t":"宪法规定的国家机构","n":"“一府一委两院”格局"},{"t":"全面从严治党","n":"国家监察体制改革背景"}],"more":"关键时间：2018年3月20日通过并施行；2024年12月25日首次修正，2025年6月1日起施行。","exam":[]},{"id":"b15-028","t":"国家勋章和国家荣誉称号","cid":"15a","p":2,"kind":"制度","alias":["共和国勋章","友谊勋章","国家最高荣誉"],"one":"我国国家最高荣誉，含共和国勋章、友谊勋章及“人民”称号。","ans":"国家勋章和国家荣誉称号是**中华人民共和国国家最高荣誉**，由2015年通过、2016年施行的同名法律确立。国家勋章分**“共和国勋章”**（授国家建设保卫杰出人士）和**“友谊勋章”**（授杰出外国人）；国家荣誉称号一般冠以**“人民”**，如“人民科学家”“人民艺术家”。**全国人大常委会决定授予**，**国家主席颁授**。该制度完善了国家功勋荣誉表彰体系。","pts":["国家最高荣誉：共和国、友谊勋章与荣誉称号","友谊勋章授外国人，称号常冠以“人民”","全国人大常委会决定，国家主席颁授"],"mem":"区分两枚国家勋章：“共和国”对内奖国人，“友谊”对外奖友人。职权口诀：“常委会决定，主席颁授”，且国家主席在国事活动中可直接授予外国政要友谊勋章。","mix":"“七一勋章”是党内最高荣誉，“八一勋章”是军队最高荣誉，与国家层面的共和国勋章、友谊勋章分属不同表彰序列。","mcq":[{"q":"根据宪法和法律，我国国家勋章和国家荣誉称号的决定授予机关是","o":["全国人民代表大会常务委员会","国务院","最高人民法院","全国政协常委会"],"a":0,"w":"由全国人大常委会决定授予，国家主席根据决定签发证书并颁授。"}],"rel":[{"t":"国家主席","n":"签发证书并颁授国家勋章"},{"t":"全国人大常委会","n":"依法决定授予的机关"},{"t":"国家最高科学技术奖","n":"科技领域最高奖项对照"},{"t":"宪法规定的国家机构","n":"授予权分工考点"}],"more":"《国家勋章和国家荣誉称号法》2015年12月27日通过，2016年1月1日施行；国家设立“国家功勋簿”记载获得者功绩。","exam":[]},{"id":"b15-029","t":"八一建军节","cid":"15e","p":2,"kind":"常识","alias":["建军节","中国人民解放军建军节"],"one":"每年8月1日，纪念1927年南昌起义和人民军队诞生。","ans":"八一建军节是**中国人民解放军建军纪念日**，定于每年**8月1日**。它源于**1927年8月1日**中国共产党发动的**南昌起义**，**打响了武装反抗国民党反动派的第一枪**，标志党独立领导革命战争和创建人民军队的开端。**1933年7月**，中华苏维埃共和国临时中央政府正式定8月1日为红军成立纪念日，新中国成立后沿称建军节。2027年将迎来建军100周年。","pts":["源于1927年8月1日南昌起义","打响武装反抗国民党反动派第一枪，创建人民军队","1933年正式定为纪念日，2027年迎建军百年"],"mem":"时间两步记：1927年8月1日打响第一枪（南昌起义），6年后的1933年在瑞金正式定节并首次庆祝。2027年正好建军100周年，对应“建军一百年奋斗目标”。","mix":"1927年8月1日是起义日期，“八一”被正式定为红军成立纪念日是在1933年（不是1927年当年）；秋收起义虽同在1927年，但建军节纪念的是南昌起义。","mcq":[{"q":"八一建军节源于1927年8月1日打响武装反抗国民党反动派第一枪的","o":["秋收起义","南昌起义","广州起义","武昌起义"],"a":1,"w":"1927年8月1日南昌起义是八一建军节的由来，1933年正式确定为人民军队纪念日。"}],"rel":[{"t":"建军100周年","n":"2027年百年奋斗目标"},{"t":"军种成立纪念日","n":"各军种建军日对照"},{"t":"古田会议","n":"确立思想建党政治建军"},{"t":"法定节假日","n":"部分公民放假的节日"}],"more":"1933年7月11日，中华苏维埃共和国临时中央政府批准8月1日为中国工农红军成立纪念日，同年8月1日在江西瑞金首次隆重庆祝。","exam":[]},{"id":"b15-031","t":"中国首次参加奥运会","cid":"15f","p":2,"kind":"事件","alias":["刘长春单刀赴会","刘长春"],"one":"1932年洛杉矶奥运会，短跑选手刘长春代表中国首次参赛。","ans":"中国首次参加奥运会发生于**1932年美国洛杉矶第10届夏季奥运会**，东北大学短跑运动员**刘长春**是**中国唯一参赛选手**。面对日伪胁迫其代表“伪满洲国”参赛的图谋，刘长春严正拒绝；经**宋君复**等奔走和**张学良**资助8000银圆，他“单刀赴会”出战**100米和200米**预赛。虽未晋级，此行粉碎了分裂阴谋，正式开启中国参加现代奥运的历史。","pts":["1932年美国洛杉矶第10届夏季奥运会","短跑运动员刘长春为中国唯一参赛选手","拒代表伪满洲国，张学良资助，开启中国奥运史"],"mem":"记住“一个人的奥运”画面：**1932年洛杉矶**，**张学良**出钱（8000银圆）、**宋君复**陪行，短跑选手**刘长春**独擎国旗参加100米和200米预赛，称“单刀赴会”。","mix":"1932年洛杉矶奥运会是中国首次参赛（刘长春），1984年洛杉矶奥运会则是中国夺得首枚奥运金牌（许海峰），两次里程碑恰好都在美国洛杉矶，注意区分年份与人物。","mcq":[{"q":"1932年代表中国首次参加奥运会、在洛杉矶出战短跑项目的唯一中国运动员是","o":["许海峰","容国团","刘长春","李宁"],"a":2,"w":"1932年洛杉矶第10届奥运会上，短跑运动员刘长春作为唯一选手代表中国首次参赛。"}],"rel":[{"t":"许海峰","n":"52年后同在洛杉矶夺首金"},{"t":"“双奥之城”","n":"从单人参赛到主办双奥"},{"t":"第一届现代奥运会","n":"现代奥运历史起点"}],"more":"关键日期：1932年7月30日开幕，刘长春任旗手，官方报告称其为“中国四亿人的唯一代表”。","exam":[]},{"id":"b15-032","t":"“双奥之城”","cid":"15f","p":2,"kind":"常识","alias":["双奥之城","北京双奥之城"],"one":"北京先后举办2008年夏奥会与2022年冬奥会，世界首座。","ans":"“双奥之城”指**既举办过夏季奥运会又举办过冬季奥运会的城市**，**北京**是**世界首个“双奥之城”**。**2008年8月**，北京举办**第29届夏季奥运会**，是中国首次主办夏奥会。**2022年2月**，北京联合张家口举办**第24届冬季奥运会**，复用多座夏奥场馆，展现绿色办奥理念。北京成为全球首座“双奥之城”，见证了中国综合国力与对奥林匹克运动的贡献。","pts":["北京为世界首个既办夏奥又办冬奥的城市","2008年第29届夏奥会、2022年第24届冬奥会","场馆复用体现绿色办奥，见证中国奥运贡献"],"mem":"成对届次与年份记：**2008（第29届夏奥）+ 2022（第24届冬奥）**，间隔14年。场馆变身画面：“水立方”变“冰立方”，直观记住夏冬双奥。","mix":"2022年冬奥会由北京和张家口联合举办，但拥有“双奥之城”称号的是既办夏奥又办冬奥的北京；2026年米兰—科尔蒂纳丹佩佐冬奥会主办城米兰未办过夏奥，并非双奥之城。","mcq":[{"q":"北京成为世界首座“双奥之城”，先后举办的两届奥运会分别是","o":["2008年第29届夏奥会、2022年第24届冬奥会","2008年第28届夏奥会、2022年第23届冬奥会","2008年第30届夏奥会、2022年第24届冬奥会","2008年第29届夏奥会、2022年第25届冬奥会"],"a":0,"w":"北京举办的是2008年第29届夏季奥运会和2022年第24届冬季奥运会。"}],"rel":[{"t":"中国首次参加奥运会","n":"1932年单人赴会到双奥之城"},{"t":"2026年米兰—科尔蒂纳丹佩佐冬奥会","n":"北京之后的下一届冬奥会"},{"t":"杨扬","n":"中国冬奥金牌零的突破"},{"t":"奥林匹克运动会","n":"现代奥运体系组成部分"}],"more":"举办日期：2008年8月8日至24日（第29届夏奥会）；2022年2月4日至20日（第24届冬奥会）。","exam":[]},{"id":"b15-034","t":"公历闰年","cid":"15h","p":2,"kind":"常识","alias":["格里高利历闰年","闰年规则"],"one":"四年一闰，百年不闰，四百年再闰：2000年是闰年，1900年不是。","ans":"公历闰年是**现行公历（格里高利历）为协调历年与太阳回归年差值而设的置闰制度**，属历法基础常识。回归年约**365.2422天**，闰年在**2月增设29日**共366天。1582年确立的规则为**“四年一闰，百年不闰，四百年再闰”**：普通年能被4整除为闰年，整百年须能被400整除，故**2000年是闰年，1900年不是**。该制使历法与四季长期同步。","pts":["回归年约365.2422天，闰年2月29天","规则：四年一闰，百年不闰，四百年再闰","例证：2000年是闰年，1900年不是"],"mem":"通行口诀：“四年一闰，百年不闰，四百年再闰”。整百年直接砍掉末尾两个零再除以4：1900→19除不尽（平年），2000→20除得尽（闰年）。","mix":"公历闰年多出“一天”（2月29日），属阳历；农历置闰多出“一个月”（闰月，如十九年七闰），属阴阳合历。整百年1900、2100年虽能被4整除，但并非闰年。","mcq":[{"q":"按照现行公历置闰规则，下列年份中属于平年（非闰年）的是","o":["2000年","2024年","1900年","1600年"],"a":2,"w":"“百年不闰，四百年再闰”，1900年不能被400整除，故为平年；2000年和1600年为闰年。"}],"rel":[{"t":"农历","n":"阳历与阴阳合历对照"},{"t":"闰月与十九年七闰","n":"农历置闰规则对比"},{"t":"四季成因","n":"回归年与公转周期关联"}],"more":"现行公历即1582年教皇格里高利十三世颁行的格里高利历，平均年长365.2425天，修正了儒略历每400年多算约3天的误差。","exam":[]},{"id":"b15-035","t":"经度与纬度","cid":"15h","p":3,"kind":"常识","alias":["经纬度","地理坐标系统","经线与纬线"],"one":"地理坐标中以赤道测南北（纬度）、以本初子午线测东西（经度）的体系。","ans":"经度与纬度是确定地球表面空间位置的坐标体系。**纬度以赤道为0°**向南北各划**90°**，纬线指示东西方向；**经度以格林尼治本初子午线为0°**向东西各划**180°**，经线指示南北方向。经纬交叉构成全球定位与时区划分的基础。","pts":["纬度以赤道为0°，向南北两极各划90°","经度以本初子午线为0°，向东西各划180°","纬线指示东西，经线连接两极指示南北"],"mem":"口诀：“赤道零度纬线平，格林尼治子午立”。经度定东西与时差，纬度定南北与气候。","mix":"经线长度均相等（为半圆），指示南北方向；纬线长度从赤道向两极递减（为圆圈），指示东西方向。","mcq":[{"q":"在地球经纬网系统中，关于经度与纬度的起算基准，下列说法正确的是","o":["纬度以北回归线为0°，向南北各分90°","纬度以赤道为0°，经度以本初子午线为0°","经度以国际日期变更线为0°，向东西各分180°","经度以东经120°为0°，向南北各分180°"],"a":1,"w":"纬度起算线为赤道（0°纬线），经度起算线为穿过格林尼治天文台旧址的本初子午线（0°经线）。"}],"rel":[{"t":"本初子午线","n":"经度起算基准线"},{"t":"国际日期变更线","n":"经度与日历基准"},{"t":"北京时间","n":"东经120°与东八区区时"}],"exam":[]},{"id":"b15-036","t":"国际日期变更线","cid":"15h","p":3,"kind":"常识","alias":["日界线","日变更线","International Date Line"],"one":"太平洋上大致沿180°经线确立的自西向东减一日、东向西加一日的折线。","ans":"国际日期变更线是为消除环球时间混乱设立的日期界线。它在太平洋上**大致沿180°经线**穿行，避开陆地呈折线。日历变更规则为：**由西向东跨过日界线日期减一天**，**由东向西跨过日界线日期加一天**，钟点则保持不变。","pts":["大致沿180°经线穿过太平洋，呈曲折线","自东向西越过日期加一天","自西向东越过日期减一天，钟点不变"],"mem":"口诀：“向东跨过减一天，向西跨过加一天”（东减西加）。迎着太阳往东走会重复昨天，故减一天。","mix":"国际日期变更线并非一条笔直的180°经线，为了不使同一国家或岛屿分属两个日期，它在白令海峡、阿留申群岛等地有多处弯曲折绕。","mcq":[{"q":"关于国际日期变更线（日界线）的规定，下列说法正确的是","o":["日界线完全与本初子午线重合且呈直线","向西越过日界线日期应当减去一天","大致沿180°经线，向东越过日期减一天、向西越过加一天","向东越过日界线日期加一天且时针拨慢一小时"],"a":2,"w":"日界线大致沿180°经线曲折延伸，自西向东跨过减一天，自东向西跨过加一天，钟点保持不变。"}],"rel":[{"t":"经度与纬度","n":"经纬网与时区划分基础"},{"t":"北京时间","n":"全球区时与标准时间"},{"t":"本初子午线","n":"经度起点与对跖经线"}],"exam":[]},{"id":"b15-037","t":"北京时间","cid":"15h","p":3,"kind":"常识","alias":["中国标准时间","CST","China Standard Time"],"one":"中国采用的以东经120°地方时为准、比协调世界时快8小时的标准时。","ans":"北京时间是中国统一采用的国家标准时间。它并非北京市的地方时，而是**东八区区时**，以**东经120°经线的地方时**为基准，比协调世界时快8小时（**UTC+8**）。该标准时间由设在陕西西安临潼的**国家授时中心**测定并发出。","pts":["采用东八区区时（UTC+8）","以东经120°经线的地方时为统一基准","由陕西临潼国家授时中心发出，非北京地方时"],"mem":"口诀：“北京时间东八区，东经一百二十度，发自陕西临潼处”。北京本地位于东经116°，非120°。","mix":"北京时间不是北京市的地方时（北京位于东经约116°20′，地方时比北京时间慢约14分半）；同时，发布北京时间的国家授时中心位于陕西临潼而非北京。","mcq":[{"q":"关于“北京时间”的地理与天文含义，下列说法正确的是","o":["指北京市天安门所在经线的当地地方平太阳时","以东经116°的地方时为基准，属于东七区区时","由中国科学院紫金山天文台测定并向全国授时","采用东八区区时，以东经120°经线的地方时为准"],"a":3,"w":"北京时间是东八区区时，以东经120°地方时为基准，由陕西临潼的国家授时中心产生和发播。"}],"rel":[{"t":"经度与纬度","n":"经度时差与地方时计算"},{"t":"国际日期变更线","n":"全球时间与日期系统"},{"t":"法定节假日","n":"全国统一时间与节庆管理"}],"exam":[]},{"id":"b15-038","t":"微波炉","cid":"15g","p":3,"kind":"常识","alias":["微波加热","微波加热原理"],"one":"利用微波激发食物中极性水分子振动摩擦生热的厨房烹调电器。","ans":"微波炉是现代常见的厨房加热电器。其核心原理是利用**磁控管产生微波**，激发食物中的**水分子高速振动**、相互摩擦而生热。具有穿透性强、由内而外加热迅速的特点。使用时**严禁使用金属器皿**及加热密闭带壳食物以防危险。","pts":["磁控管产生高频电磁波（微波）","水分子高速振动摩擦产生内热","严禁放入金属器皿与密闭食物"],"mem":"口诀：“微波振水分子，金属绝不能入”。水分子极性强，振动摩擦即产生热量。","mix":"电磁炉利用电磁感应在铁锅底产生涡流生热；微波炉利用电磁波直接使食物中的水分子振动摩擦生热。","mcq":[{"q":"微波炉加热食物的核心物理原理是","o":["利用微波激发水分子振动摩擦生热","利用电磁感应在锅底产生涡流生热","利用电阻丝通电发热传导热量","利用红外线辐射直接加热食物表面"],"a":0,"w":"微波炉通过微波促使水分子等极性分子剧烈振动摩擦生热；电磁感应产生涡流是电磁炉的原理。"}],"rel":[{"t":"电磁炉与白炽灯","n":"厨房电器加热原理对照"},{"t":"电饭煲温控","n":"厨房家电温控常识"},{"t":"高压锅","n":"生活热学原理"}],"exam":[]},{"id":"b15-039","t":"高压锅","cid":"15g","p":3,"kind":"常识","alias":["压力锅","压力煲"],"one":"利用密闭使锅内气压增大、水沸点升高从而加快烹饪的器具。","ans":"高压锅又称压力锅，是常见的密闭烹饪器具。其工作原理是通过密闭结构**升高锅内气压**，使**水的沸点升至100℃以上**（通常达110至120℃），从而提高烹调温度，**显著缩短加热时间**。它能有效节约能源，特别适合在低气压的高原地区使用。","pts":["密闭容器使锅内气压显著升高","气压升高使液体沸点升至100℃以上","提高烹饪温度并缩短加热时间"],"mem":"口诀：“压强增大沸点高，高原做饭少不了”。气压与沸点成正比，高原气压低水沸点不足100℃需用高压锅。","mix":"高原地区气压低，水的沸点低于100℃，普通锅不易煮熟食物；高压锅则是通过人为增压提高沸点。","mcq":[{"q":"高压锅能够快速煮熟食物的主要物理原理是","o":["降低锅内气压使水分蒸发加快","升高锅内气压使水的沸点升高","利用高频微波穿透食物分子","利用涡流效应在锅底产生强热"],"a":1,"w":"液体沸点随气压升高而升高，高压锅通过提高锅内气压使水沸点达到100℃以上，从而加快烹调。"}],"rel":[{"t":"微波炉","n":"生活加热器具原理对照"},{"t":"保温瓶","n":"热学生活常识"},{"t":"青藏铁路","n":"高原低压环境常识"}],"exam":[]},{"id":"b15-040","t":"保温瓶","cid":"15g","p":3,"kind":"常识","alias":["暖水瓶","热水瓶","杜瓦瓶"],"one":"利用真空层阻断传导对流、镀银层反射辐射的保温暖水容器。","ans":"保温瓶是日常保持液体温度的容器，由物理学家杜瓦发明。其内胆采用双层玻璃结构，**夹层抽成真空**以有效阻断**热传导与热对流**；内壁**镀银**以**反射热辐射**减少能量散失。软木塞等不良导热体瓶塞则进一步减少瓶口散热。","pts":["双层玻璃夹层抽真空阻断传导与对流","内壁镀银反射减少热辐射散失","不良导体瓶塞减少瓶口热量散逸"],"mem":"口诀：“真空断传导对流，镀银反射热辐射”。三种传热途径（传导、对流、辐射）被保温瓶全方位阻断。","mix":"镀银的作用是反射热辐射，而不是防止热对流；抽真空阻断的是热传导和热对流，热辐射在真空中依然可以传播。","mcq":[{"q":"传统保温瓶胆内壁通常镀有一层薄银，其主要物理作用是","o":["阻断热传导","防止气体发生热对流","反射热辐射减少散热","增强瓶胆抗压机械强度"],"a":2,"w":"保温瓶双层真空阻断热传导与热对流，内壁镀银则是为了反射热辐射，全面减少热量散失。"}],"rel":[{"t":"高压锅","n":"生活热学常识"},{"t":"冰箱制冷","n":"生活热力学原理"},{"t":"微波炉","n":"日常家电原理"}],"exam":[]},{"id":"b15-041","t":"冰箱制冷","cid":"15g","p":3,"kind":"常识","alias":["压缩式制冷","电冰箱制冷原理"],"one":"利用制冷剂蒸发汽化吸热、冷凝液化放热实现降温的热力学过程。","ans":"冰箱制冷是利用物态变化转移热量的常见技术。其核心循环是由压缩机驱动制冷剂流动：低压制冷剂在箱内蒸发器中**汽化吸热**实现降温，高压制冷剂在箱外冷凝器中**液化放热**散失热量。该循环遵循**热力学定律**，实现热量向外排出。","pts":["压缩机驱动制冷剂封闭循环流动","冷冻室蒸发器内制冷剂汽化吸热","箱外冷凝器中制冷剂液化放热"],"mem":"口诀：“内部汽化吸热变凉，外部液化放热烫手”。冰箱背面或侧面发热正是因为冷凝器液化放热。","mix":"冰箱不是“制造冷气”，而是将内部热量转移到外部；打开冰箱门不仅不能给房间降温，反而会因电机做功产热使室温升高。","mcq":[{"q":"普通压缩式电冰箱实现冷冻室降温的关键物理过程是","o":["制冷剂在箱外冷凝器中汽化吸热","制冷剂在箱外冷凝器中凝固吸热","制冷剂在箱内蒸发器中液化放热","制冷剂在箱内蒸发器中汽化吸热"],"a":3,"w":"制冷剂在箱内蒸发器由液态变为气态（汽化）吸收热量降温，在箱外冷凝器液化放出热量。"}],"rel":[{"t":"臭氧层与《蒙特利尔议定书》","n":"早期氟利昂制冷剂与环保"},{"t":"干冰与人工降雨","n":"相变与吸热原理对照"},{"t":"保温瓶","n":"热学生活常识"}],"exam":[]},{"id":"b15-042","t":"天空为什么是蓝色","cid":"15g","p":3,"kind":"常识","alias":["天空呈现蓝色的原因","瑞利散射"],"one":"太阳光中短波长蓝紫光被大气微粒强烈散射使天空呈蔚蓝的光学现象。","ans":"天空呈现蓝色是经典的大气光学现象。阳光穿过大气层时，空气微粒对**短波长光线的散射作用更强**，称为**瑞利散射**。可见光中**蓝紫光波长较短**且人眼对蓝光更敏感，被强烈散射到各个方向充盈天空，使晴朗白天呈现蔚蓝色。","pts":["大气分子对短波长光散射远强于长波长","瑞利散射效应使蓝紫光弥漫天空","人眼对蓝光较紫光更敏感而见蓝天"],"mem":"口诀：“波长越短散射越强，蓝紫散射晴空亮”。瑞利散射强度与波长的四次方成反比。","mix":"早晚日出日落时太阳光穿过大气层路径长，短波蓝光被散射殆尽，只有穿透力强的长波红橙光到达人眼，故朝阳夕阳呈红色。","mcq":[{"q":"晴朗天气下白天天空呈现蓝色的主要原因是","o":["大气分子对短波长的蓝紫光产生更强烈的瑞利散射","海洋反射蓝色光线到大气层表面","臭氧层只吸收红色光并透射蓝色光","大气层中的微小尘埃对阳光产生全反射"],"a":0,"w":"空气分子对光线的散射强度与波长四次方成反比，短波长的蓝紫光散射最强，人眼对蓝光敏感故呈蓝色。"}],"rel":[{"t":"彩虹","n":"同属日光大气光学现象"},{"t":"PM2.5","n":"气溶胶与米氏散射"},{"t":"日食与月食","n":"光学与天文现象"}],"exam":[]},{"id":"b15-043","t":"彩虹","cid":"15g","p":3,"kind":"常识","alias":["虹霓","彩霓"],"one":"阳光穿透空气中的水滴经折射、反射和色散形成的彩色拱桥天象。","ans":"彩虹是雨后常见的大气光学现象。阳光穿透空气中的水滴时，经过**折射、反射与色散**形成光谱。不同波长的光**折射率不同**，分散为**红橙黄绿蓝靛紫**的同心光弧。观察者必须**背对太阳面向水滴区**；主虹外圈为红、内圈为紫。","pts":["阳光穿过水滴发生折射、反射和色散","不同颜色光折射率不同分散为七色光谱","主虹外红内紫，观察时须背向太阳"],"mem":"口诀：“一反二折出色散，外红内紫背阳看”。彩虹（主虹）在水滴内经历两次折射、一次反射。","mix":"主虹（虹）光线在水滴中经一次反射、两次折射，外红内紫；副虹（霓）经两次反射、两次折射，外紫内红且光芒较弱。","mcq":[{"q":"关于彩虹形成机制与光学特征，下列说法正确的是","o":["彩虹是由阳光在大气中发生衍射形成的单色光","彩虹是阳光在水滴中经折射、反射与色散形成的","观察彩虹时人应面向太阳且主虹内圈为红色","副虹（霓）的色彩排列与主虹相同且亮度更高"],"a":1,"w":"彩虹成因是阳光在水滴中发生折射、反射与色散；主虹外红内紫，观测者需背对太阳。"}],"rel":[{"t":"天空为什么是蓝色","n":"日光大气光学现象"},{"t":"牛顿与经典力学","n":"牛顿三棱镜色散实验"},{"t":"干冰与人工降雨","n":"大气与水循环常识"}],"exam":[]},{"id":"b15-044","t":"先见闪电后闻雷声","cid":"15g","p":3,"kind":"常识","alias":["雷电传播现象","闪电与雷鸣"],"one":"雷电发生时光速远大于声速导致视觉先于听觉感知的常见物理现象。","ans":"先见闪电后闻雷声是雷雨中常见物理现象。闪电与雷声同时产生，但**光速约为30万千米/秒**，而常温下**声速仅约340米/秒**。因**光速远大于声速**，光信号瞬间抵达人眼，声波则明显滞后到达。根据两者到达的时间差可估算雷电源距离。","pts":["闪电与雷声源于同一放电过程同时产生","真空及空气中光速远大于空气中的声速","时间差源于声光传播速度的数量级差距"],"mem":"口诀：“闪电雷鸣同时发，光速三十万秒秒杀三百四”。见闪电后数秒数除以3即可估算雷电距离（千米）。","mix":"闪电和雷鸣是同时同地产生的放电过程，感知的时间差是由介质传播速度差距引起的，并非雷声生成时间晚于闪电。","mcq":[{"q":"雷雨天通常“先见闪电、后闻雷声”，其根本原因是","o":["雷声是在闪电放电结束之后才产生振动","大气层对声波的吸收比对光线的吸收严重","空气中光速（约30万千米/秒）远大于声速（约340米/秒）","人眼视觉神经的传导速度显著快于听觉神经"],"a":2,"w":"两者同时产生，但光速约为30万千米/秒，声速仅约340米/秒，巨大速度差导致视觉先接收到信号。"}],"rel":[{"t":"避雷针与富兰克林","n":"雷电本质与防雷设施"},{"t":"天空为什么是蓝色","n":"生活物理与自然现象"},{"t":"爱因斯坦与相对论","n":"光速极值与现代物理"}],"exam":[]},{"id":"b15-045","t":"不粘锅","cid":"15g","p":3,"kind":"常识","alias":["特氟龙涂层锅","聚四氟乙烯不粘锅"],"one":"内壁涂覆聚四氟乙烯等低表面能涂层、防止食材附着的炊具。","ans":"不粘锅是现代常见厨房炊具。其内壁通常涂覆**聚四氟乙烯（商品名特氟龙）**。该材料摩擦系数极小且**表面能极低**，具有优良的疏水疏油性，使食材**不易粘附**。日常使用应**避免干烧与金属硬铲刮擦**，防止高温下涂层受损分解。","pts":["内壁涂层主要化学成分为聚四氟乙烯","极低表面能和摩擦系数产生防粘特性","避免高温干烧与金属硬质锅铲刮损"],"mem":"口诀：“特氟龙聚四氟乙烯，表面能低油水离”。特氟龙有“塑料王”之称，最忌铁铲刮擦与干烧。","mix":"特氟龙学名聚四氟乙烯，耐酸耐碱耐腐蚀；但超过260℃以上高温或干烧时容易热解产生有害气体，故不可长时间空锅干烧。","mcq":[{"q":"传统不粘锅内壁能够实现“不粘”效果，主要是因为涂覆了","o":["聚乙烯材料","纳米二氧化硅涂料","陶瓷微晶耐磨玻璃","聚四氟乙烯（特氟龙）"],"a":3,"w":"不粘锅涂层主流材料是聚四氟乙烯（商品名特氟龙），具有极低的摩擦系数和极低表面能。"}],"rel":[{"t":"微波炉","n":"日常厨房用具常识"},{"t":"电磁炉与白炽灯","n":"现代厨房烹饪工具"},{"t":"灭火原理","n":"家庭生活安全防范"}],"exam":[]},{"id":"b15-046","t":"指南针","cid":"15g","p":2,"kind":"常识","alias":["罗盘","司南","磁偏角"],"one":"中国四大发明之一，靠地磁场指向，北宋沈括最早记载磁偏角。","ans":"指南针是**中国古代四大发明之一**，利用**磁针受地磁场作用指示南北**。其前身为战国至汉代的天然磁石**司南**，后经人工磁化发展为航海罗盘。北宋**沈括**在**《梦溪笔谈》**中记述了指南针制法，并**最早记载磁偏角现象**，成因在于**地磁两极与地理两极不完全重合**（地磁南极在地理北极附近）。指南针经外传推动了远洋航海与世界地理大发现。","pts":["四大发明之一，利用地磁场指向，前身为司南","地磁两极与地理两极不重合，形成磁偏角","北宋沈括《梦溪笔谈》最早记载磁偏角现象"],"mem":"物理原理顺口溜：**“异性相吸，地磁反着长”**，磁针北极（N）指地理北极，说明地理北极附近其实是**地磁南极（S）**；二者错开的角度就是北宋**沈括**最早记下的**磁偏角**。","mix":"常见物理陷阱是误以为地磁北极在地理北极附近（实际地磁南极在地理北极附近）；最早记载磁偏角的是北宋沈括《梦溪笔谈》，不要误选明代宋应星《天工开物》。","mcq":[{"q":"关于指南针与地磁场，下列说法正确的是","o":["地磁北极位于地理北极附近","地磁两极与地理两极完全重合","明代宋应星在《天工开物》中最早记载磁偏角","北宋沈括在《梦溪笔谈》中最早记载磁偏角现象"],"a":3,"w":"北宋沈括《梦溪笔谈》最早记载磁偏角；地磁南极在地理北极附近，二者不完全重合。"}],"rel":[{"t":"四大发明","n":"造纸印刷火药指南针之一"},{"t":"《梦溪笔谈》","n":"最早记载磁偏角现象"},{"t":"郑和下西洋","n":"指南针航海的古代高峰"}],"more":"关键人物：北宋沈括《梦溪笔谈》记录人工磁化法与磁偏角现象。","exam":[]},{"id":"b15-047","t":"长江","cid":"15i","p":2,"kind":"地理","alias":["扬子江"],"one":"中国第一长河、世界第三长河，全长约6300千米，发源唐古拉山、入东海。","ans":"长江是**中国第一长河、亚洲第一长河、世界第三长河**，全长**约6300千米**，仅次于尼罗河与亚马孙河。它发源于青藏高原**唐古拉山脉**主峰各拉丹冬峰西南侧，自西向东流经青海、四川、湖北、江苏、上海等**11个省级行政区**，注入**东海**。长江水能与航运发达，素称**“黄金水道”**，是南方稻作文明摇篮与长江经济带核心动脉。","pts":["中国第一、世界第三长河，全长约6300千米","发源青藏高原唐古拉山脉，注入东海","流经11个省级行政区，素称“黄金水道”"],"mem":"对比黄河背：“长六三、黄五四（6300 vs 5464）；长唐古拉入东海，黄巴颜喀拉入渤海；长11省，黄9省”。","mix":"常见干扰项：把长江发源地与黄河的“巴颜喀拉山脉”互换，或把入海口误作“黄海”；“扬子江”本指长江江苏镇江以下河段，外语中常泛指整条长江。","mcq":[{"q":"长江发源于青藏高原的唐古拉山脉，干流最终注入的海域是","o":["东海","黄海","渤海","南海"],"a":0,"w":"长江干流在上海附近注入东海；黄河注入渤海。"}],"rel":[{"t":"黄河","n":"中国两大母亲河并举"},{"t":"鄱阳湖与青海湖","n":"鄱阳湖属长江水系"},{"t":"世界地理之最","n":"世界第三长河位置"},{"t":"秦岭淮河一线","n":"长江与黄河流域分水参考"}],"exam":[]},{"id":"b15-048","t":"珠穆朗玛峰","cid":"15i","p":2,"kind":"地理","alias":["珠峰","埃佛勒斯峰","Mount Everest"],"one":"世界最高峰，位于中尼边境喜马拉雅山脉，2020年中尼公布高程8848.86米。","ans":"珠穆朗玛峰简称**珠峰**，是**喜马拉雅山脉主峰、世界最高峰**，坐落于**中国西藏与尼泊尔边境**。藏语意为“大地之母”，英文称Mount Everest。**2020年12月8日**，**中尼两国共同公布**珠峰最新雪面高程为**8848.86米**，由含中国北斗在内的现代测绘技术测定。它是板块碰撞隆升的标志，也是人类登山与国际测绘合作的象征。","pts":["世界最高峰，位于中尼边境喜马拉雅山脉","2020年中尼联合公布最新雪面高程8848.86米","藏语意为“大地之母”，综合北斗测绘测定"],"mem":"数字记忆：“8848.86”，先记经典的8848，小数点后加“86”（谐音“爬溜”，2020年中尼联手“爬溜”定最新身高）。","mix":"易混历史数据：1975年中国测得雪面高程8848.13米，2005年测得岩面高程8844.43米，2020年中尼共同公布的最新雪面高程为8848.86米。世界第二高峰是喀喇昆仑山脉的乔戈里峰（K2）。","mcq":[{"q":"2020年12月，中国与尼泊尔共同向世界公布的珠穆朗玛峰最新雪面高程为","o":["8844.43米","8848.86米","8848.13米","8850.00米"],"a":1,"w":"2020年12月8日中尼共同公布珠峰最新雪面高程为8848.86米；8844.43米为2005年岩面高程。"}],"rel":[{"t":"世界地理之最","n":"世界最高峰条目"},{"t":"地势三级阶梯","n":"地处第一级阶梯边缘"},{"t":"青藏铁路","n":"同属青藏高原地标"}],"exam":[]},{"id":"b15-049","t":"鄱阳湖与青海湖","cid":"15i","p":2,"kind":"地理","alias":["鄱阳湖","青海湖"],"one":"鄱阳湖是中国最大淡水湖（江西），青海湖是中国最大咸水湖兼最大湖泊（青海）。","ans":"鄱阳湖与青海湖分别是**中国面积最大的淡水湖与最大的咸水湖**，属中国地理“之最”高频考点。**鄱阳湖**位于**江西省北部**、长江南岸，是长江重要调蓄湖泊与**中国第一大淡水湖**。**青海湖**位于**青海省东北部**，属内陆封闭咸水湖，面积超4500平方千米，是**中国最大咸水湖兼总面积最大湖泊**。二者分别代表外流淡水湖与内流咸水湖的典型形态。","pts":["鄱阳湖位于江西，中国第一大淡水湖","青海湖位于青海，中国最大咸水湖兼最大湖泊","分属长江外流湖与高原内流湖典型"],"mem":"一字定性：鄱阳湖在“赣（江西）”通长江→外流淡；青海湖名字带“海”→海水咸→内流咸，且面积比鄱阳湖还大，稳坐中国第一大湖。","mix":"常见设坑问“中国面积最大的湖泊是”，答案是青海湖而非鄱阳湖；只有加上“淡水湖”限定时才选鄱阳湖。另注意洞庭湖是第二大淡水湖，位于湖南。","mcq":[{"q":"关于中国湖泊之最，下列表述正确的是","o":["洞庭湖是中国面积最大的淡水湖","鄱阳湖是中国总面积最大的湖泊","青海湖是中国最大的咸水湖，也是中国面积最大的湖泊","太湖属于中国最大的内陆咸水湖"],"a":2,"w":"青海湖是中国最大咸水湖兼最大湖泊；鄱阳湖是中国最大淡水湖，洞庭湖居淡水湖第二。"}],"rel":[{"t":"中国五大淡水湖","n":"鄱阳湖居五大淡水湖之首"},{"t":"长江","n":"鄱阳湖为长江重要调蓄湖"},{"t":"中国地理之最","n":"同属中国地理之最"}],"exam":[]},{"id":"b15-050","t":"吐鲁番盆地","cid":"15i","p":3,"kind":"地理","alias":["吐鲁番","火洲"],"one":"新疆天山山脉东端南麓的断陷盆地，其艾丁湖为中国陆地最低处。","ans":"吐鲁番盆地是新疆天山东段南侧的断陷盆地。盆地底部的**艾丁湖湖面低于海平面约154米**，是**中国陆地最低点**。盆地气候干燥炎热，素有“**火洲**”之称，夏季气温极高。当地依靠古代水利**坎儿井**引天山雪水灌溉，盛产优质葡萄与瓜果。","pts":["底部的艾丁湖海拔约-154米，为中国陆地最低处","气候极干热，有“火洲”之称","发明利用坎儿井引天山雪水灌溉农业"],"mem":"口诀：“吐鲁番火洲艾丁湖，负百五十四陆底浮”。中国最低在艾丁湖，灌溉全靠坎儿井。","mix":"中国陆地最高点是珠穆朗玛峰（8848.86米），最低点是吐鲁番盆地的艾丁湖（约-154米），两者垂直高差达9000米。","mcq":[{"q":"中国陆地表面海拔最低的地方位于吐鲁番盆地的","o":["艾丁湖（海拔约-154米）","罗布泊","博斯腾湖","喀纳斯湖"],"a":0,"w":"吐鲁番盆地南部的艾丁湖水面低于海平面约154米，是中国陆地最低处。"}],"rel":[{"t":"三大平原、四大高原、四大盆地","n":"中国主要地形单元构成"},{"t":"塔里木盆地","n":"新疆南部大型盆地对照"},{"t":"地势三级阶梯","n":"中国宏观地势阶梯格局"}],"exam":[]},{"id":"b15-051","t":"东北平原","cid":"15i","p":3,"kind":"地理","alias":["松辽平原","关东平原"],"one":"位于中国东北部、大小兴安岭与长白山环抱，中国面积最大的平原。","ans":"东北平原位于大兴安岭、小兴安岭与长白山之间，是**中国面积最大的平原**。由**三江平原、松嫩平原、辽河平原**三部分组成。平原分布着肥沃深厚的**黑土层**，农业机械化水平极高，是我国最重要的**商品粮基地（北大仓）**。","pts":["中国面积最大的平原（约35万平方千米）","由松嫩平原、辽河平原、三江平原组成","土壤以肥沃黑土为主，为国家商品粮基地"],"mem":"口诀：“东北平原面积首，三江松嫩辽河走，黑土飘香粮满仓”。中国三大平原面积第一。","mix":"中国三大平原面积排名：东北平原（最大，约35万平方千米）> 华北平原（第二，约30万平方千米）> 长江中下游平原（约16万平方千米）。","mcq":[{"q":"在中国三大平原中，面积最大且拥有肥沃黑土分布的平原是","o":["华北平原","东北平原","长江中下游平原","成都平原"],"a":1,"w":"东北平原面积约35万平方公里，由松嫩、辽河、三江平原组成，为我国面积最大的平原。"}],"rel":[{"t":"三大平原、四大高原、四大盆地","n":"中国主要地形单元构成"},{"t":"地势三级阶梯","n":"位于第三级阶梯主要地形"},{"t":"塔里木盆地","n":"最大平原与最大盆地对照"}],"exam":[]},{"id":"b15-052","t":"塔里木盆地","cid":"15i","p":3,"kind":"地理","exam":["2010选择"],"alias":["Tarim Basin"],"one":"天山与昆仑山之间，中国面积最大且内含塔克拉玛干沙漠的内陆盆地。","ans":"塔里木盆地位于新疆南部，介于天山与昆仑山之间，是**中国面积最大的盆地**。盆地内部拥有**中国最大的沙漠塔克拉玛干沙漠**，中国最长内流河**塔里木河**滋润边缘绿洲。该盆地油气储量丰富，是我国**“西气东输”的主力气源地**。","pts":["中国面积最大的内陆盆地（天山与昆仑山之间）","内部有中国最大沙漠塔克拉玛干沙漠","中国最长内流河塔里木河流经北部"],"mem":"口诀：“塔里木盆地大无边，塔克拉玛干居其间”。交大2010选择考过，中国最大盆地与最大沙漠在此。","mix":"四大盆地之最：面积最大是塔里木盆地，海拔最高是柴达木盆地（“聚宝盆”），纬度最高是准噶尔盆地，农业最发达是四川盆地（“天府之国”）。","mcq":[{"q":"中国面积最大的内陆盆地，且内部孕育了中国最大沙漠塔克拉玛干沙漠的是","o":["准噶尔盆地","四川盆地","塔里木盆地","柴达木盆地"],"a":2,"w":"塔里木盆地面积约40多万平方公里，是我国面积最大的盆地；交大2010届考过相关选择题。"}],"rel":[{"t":"塔克拉玛干沙漠","n":"盆地腹地中国最大沙漠"},{"t":"吐鲁番盆地","n":"新疆盆地地形对照"},{"t":"三大平原、四大高原、四大盆地","n":"中国四大盆地格局"}]},{"id":"c-072","t":"民法典七编","cid":"15b","p":1,"kind":"合称","alias":["民法典的七编","民法典编"],"one":"总则、物权、合同、人格权、婚姻家庭、继承、侵权责任七编。","ans":"民法典七编指**《民法典》正文的七个编**，依次为**总则编、物权编、合同编、人格权编、婚姻家庭编、继承编、侵权责任编**，另有附则，共1260条。总则编规定基本原则、民事主体、民事权利和民事法律行为；物权编和合同编构成财产法的主体；**人格权独立成编**是民法典的创新，婚姻家庭编和继承编规定身份关系；侵权责任编规定侵害民事权益的责任。七编的体例体现了“总分结构”，在整合婚姻法、继承法、物权法、合同法等单行法的基础上形成。","pts":["总则、物权、合同、人格权、婚姻家庭、继承、侵权责任","人格权独立成编","共7编1260条"],"members":[["总则编","基本原则、民事主体、民事法律行为、诉讼时效等（1至204条）"],["物权编","所有权、用益物权、担保物权（205至462条）"],["合同编","合同订立、履行、违约责任及典型合同（463至988条）"],["人格权编","生命权、肖像权、名誉权、隐私权等（989至1039条）"],["婚姻家庭编","结婚、家庭关系、离婚、收养（1040至1118条）"],["继承编","法定继承、遗嘱继承、遗产处理（1119至1163条）"],["侵权责任编","侵权责任一般规定及特殊侵权（1164至1258条）"]],"mem":"口诀“总物合，人婚继侵”：总、物、合三字一组（规则与财产），人、婚、继三字（人和家庭），最后一个“侵”（侵权责任）。画面：从总则立规矩，到买卖合同，到人格尊严，到结婚继承，出了事找侵权责任兜底。","mix":"民法典没有“债权编”“知识产权编”，也没有“亲属编”；“人格权编”是新中国民事立法首次独立成编；继承编位于婚姻家庭编之后，侵权责任编是最后一编。","mcq":[{"q":"《民法典》中条文最多的一编是","o":["总则编","物权编","合同编","婚姻家庭编"],"a":2,"w":"合同编共463至988条，是条文最多的一编。"},{"q":"下列关于民法典编排顺序的表述，正确的是","o":["物权编在合同编之后","人格权编在物权编之前","侵权责任编是最后一编","继承编在婚姻家庭编之前"],"a":2,"w":"七编顺序为总则、物权、合同、人格权、婚姻家庭、继承、侵权责任，侵权责任编居末。"}],"rel":[{"t":"民法典","n":"七编所在法典"},{"t":"民法基本原则","n":"总则编内容"},{"t":"诉讼时效","n":"总则编内容"},{"t":"《汉谟拉比法典》","n":"古代法典对照"}],"exam":[]},{"id":"c-073","t":"生态环境法典五编","cid":"15c","p":2,"kind":"合称","alias":["生态环境法典结构","生态环境法典分编"],"one":"总则、污染防治、生态保护、绿色低碳发展、法律责任和附则，共1242条。","ans":"生态环境法典五编是**《生态环境法典》的体例结构**。该法典**2026年3月12日**由全国人大通过，**2026年8月15日**施行，共**5编1242条**。五编依次为：**总则、污染防治、生态保护、绿色低碳发展、法律责任和附则**。它是继《民法典》后我国**第二部法典**，也是世界首部生态环境法典，施行后《环境保护法》等10部单行法同时废止。","pts":["总则、污染防治、生态保护、绿色低碳、责任附则","2026年3月通过、8月15日施行，共1242条","中国第二部法典，世界首部生态环境法典"],"mem":"口诀记五编顺序：“总、污、生、绿、责”（总则打头，先治污、再护生、促绿碳，最后落责任与附则）。数字对比：《民法典》7编1260条，《生态环境法典》5编1242条。","mix":"《生态环境法典》施行后废止《环境保护法》《大气污染防治法》《水污染防治法》等10部单行法，但并未把《民法典》中的绿色原则删去；注意它是中国第二部“法典”，而非第一部。","members":[["第一编 总则","规定基本原则、监督管理、分区管控、环评、生态补偿与公众参与"],["第二编 污染防治","整合大气、水、海洋、土壤、固废、噪声、放射性及光污染等防治规则"],["第三编 生态保护","规范生态系统保护、自然保护地、生物多样性与生态修复"],["第四编 绿色低碳发展","聚焦碳达峰碳中和、循环经济、清洁生产与绿色转型"],["第五编 法律责任和附则","统一规定生态环境违法责任、民事公益诉讼衔接与施行附则"]],"mcq":[{"q":"下列哪一项不属于2026年通过的《生态环境法典》的五编之一","o":["污染防治编","生态保护编","自然资源产权编","绿色低碳发展编"],"a":2,"w":"《生态环境法典》五编依次为总则、污染防治、生态保护、绿色低碳发展、法律责任和附则，不含“自然资源产权编”。"}],"rel":[{"t":"生态环境法典","n":"本合称对应的法典母词条"},{"t":"全国生态日","n":"2026年8月15日同步施行"},{"t":"民法典七编","n":"中国第一部法典体例对照"},{"t":"《环境保护法》","n":"法典施行后整合废止的单行法"}],"more":"2026年3月12日主席令第70号公布，共5编1242条，2026年8月15日起施行。","exam":[]},{"id":"a15-001","t":"《中国人民政治协商会议共同纲领》","cid":"15a","p":2,"kind":"制度","alias":["共同纲领","《共同纲领》"],"one":"1949年9月一届全国政协通过，1954年宪法前起临时宪法作用。","ans":"《中国人民政治协商会议共同纲领》简称《共同纲领》，是**新中国成立初期的建国纲领**。它于**1949年9月29日**由**第一届全国政协全体会议**通过，当时由政协代行全国人大职权。纲领规定了新中国的国体、政体和经济文化政策，并确定北京为首都、五星红旗为国旗。在**1954年第一部宪法颁布前**，它起到**临时宪法**的作用，奠定了新中国国家制度基础。","pts":["1949年9月第一届全国政协全体会议通过","1954年宪法颁布前起临时宪法作用","规定新中国国体、政体及首都国旗等制度"],"mem":"时间紧贴开国大典：1949年9月29日通过，两天后（10月1日）新中国成立。口诀：“四九共同纲领，临宪管五年，五四首部宪法来接班”。","mix":"《共同纲领》起的是“临时宪法”作用，并非正式宪法；新中国第一部正式宪法是1954年一届全国人大一次会议通过的“五四宪法”。","mcq":[{"q":"1949年至1954年间，在新中国起到临时宪法作用的文件是","o":["《中华民国临时约法》","《中华人民共和国中央人民政府组织法》","《中国人民政治协商会议共同纲领》","《论人民民主专政》"],"a":2,"w":"1949年9月29日通过的《共同纲领》在1954年宪法颁布前发挥临时宪法作用。"}],"rel":[{"t":"新中国第一部宪法","n":"1954年正式接替临宪"},{"t":"现行宪法","n":"1982年宪法发展脉络"},{"t":"中国共产党领导的多党合作和政治协商制度","n":"第一届政协确立的制度"},{"t":"国家象征","n":"一届政协同时确定国旗国歌"}],"more":"1949年9月21日至30日，中国人民政治协商会议第一届全体会议在北平召开，29日通过《共同纲领》。","exam":[]},{"id":"a15-002","t":"现行宪法的五次修正","cid":"15a","p":1,"kind":"合称","alias":["五次修宪","宪法修正案","八二宪法五次修正"],"one":"1988、1993、1999、2004、2018年对现行宪法的五次修正。","ans":"现行宪法的五次修正指全国人大对1982年宪法作出的**1988、1993、1999、2004、2018年**五次修改，采用**宪法修正案**的形式，共52条。1988年规定**私营经济是公有制经济的补充**、土地使用权可依法转让；1993年写入**国家实行社会主义市场经济**；1999年写入**依法治国、建设社会主义法治国家**和邓小平理论；2004年写入**“国家尊重和保障人权”**并保护私有财产；2018年写入**习近平新时代中国特色社会主义思想**，增设国家监察委员会。五次修正使宪法与改革开放和法治建设同步发展。","pts":["88、93、99、04、18年五次","市场经济、依法治国、人权入宪","2018年新思想入宪、增设监委"],"members":[["1988年","私营经济是公有制补充；土地使用权可依法转让"],["1993年","国家实行社会主义市场经济；建设有中国特色社会主义理论"],["1999年","依法治国、建设社会主义法治国家；邓小平理论；非公有制经济是重要组成部分"],["2004年","国家尊重和保障人权；保护私有财产；“三个代表”；紧急状态"],["2018年","习近平新时代中国特色社会主义思想；国家监察委员会；取消国家主席任期届数限制"]],"mem":"首字串联“地市法人监”：88 土地和私营，93 市场，99 法治，04 人权，18 监察委员会。年份可念成“八八、九三、九九、零四、一八”，两位数尾号 88、93、99、04、18。每次修正都紧跟当年的大事：88 年前后改革开放深化，93 年南方谈话后确立市场经济，99 年前后提出依法治国，04 年前后“三个代表”，18 年党的十九大之后。","mix":"“尊重和保障人权”写入的是2004年，不是2018年；“依法治国”写入1999年，十八届四中全会（2014年）专题讨论依法治国，但那一年没有修宪；监察委员会是2018年入宪。","mcq":[{"q":"“国家尊重和保障人权”写入宪法的年份是","o":["1988年","1999年","2018年","2004年"],"a":3,"w":"2004年修正案把“国家尊重和保障人权”写入宪法。"},{"q":"2018年宪法修正案的内容不包括","o":["增设国家监察委员会","习近平新时代中国特色社会主义思想写入宪法","国家实行社会主义市场经济","国家主席任期不再限于两届"],"a":2,"w":"“国家实行社会主义市场经济”是1993年修正案写入的。"}],"rel":[{"t":"现行宪法","n":"五次修正的对象"},{"t":"国家监察委员会","n":"2018年修宪增设"},{"t":"依法治国与十八届四中全会","n":"依法治国入宪在1999年"},{"t":"习近平新时代中国特色社会主义思想","n":"2018年入宪"}],"exam":[]},{"id":"a15-003","t":"国家宪法日","cid":"15a","p":2,"kind":"常识","alias":["宪法日","12·4国家宪法日"],"one":"每年12月4日，2014年设立，纪念1982年现行宪法公布施行。","ans":"国家宪法日是**我国弘扬宪法精神的法定纪念日**，日期为**每年12月4日**。**2014年11月1日**，十二届全国人大常委会第十一次会议表决决定设立，此前该日自2001年起为全国法制宣传日。选定12月4日，是因为**1982年12月4日**五届全国人大五次会议通过并公布施行**现行宪法**。设立国家宪法日使宪法宣传常态化，推动全社会尊崇并维护宪法权威。","pts":["每年12月4日，2014年全国人大常委会设立","源于1982年12月4日现行宪法公布施行","弘扬宪法精神，增强全社会宪法意识"],"mem":"日期联想：“12·4”谐音“要爱法”（124），直接挂钩1982年12月4日“八二宪法”诞生日。2014年是国家纪念日集中立法年，四大纪念日里最后一个定下的就是宪法日。","mix":"12月4日纪念的是1982年现行宪法公布施行日，而非1954年第一部宪法通过日（9月20日）；宪法宣誓制度则由2015年决定设立、2018年写入宪法。","mcq":[{"q":"我国将每年12月4日设立为“国家宪法日”，这一日期源于","o":["1949年《共同纲领》通过之日","1954年第一部宪法通过之日","1982年现行宪法公布施行之日","2018年宪法修正案通过之日"],"a":2,"w":"1982年12月4日现行宪法公布施行，2014年全国人大常委会据此设立国家宪法日。"}],"rel":[{"t":"现行宪法","n":"1982年12月4日公布施行"},{"t":"宪法宣誓制度","n":"同属弘扬宪法权威制度"},{"t":"依法治国与十八届四中全会","n":"2014年全会部署设立"},{"t":"国家纪念日","n":"同年全国人大常委会设立"}],"more":"2014年10月十八届四中全会提出将每年12月4日定为国家宪法日，同年11月1日全国人大常委会通过设立决定。","exam":[]},{"id":"a15-004","t":"宪法宣誓制度","cid":"15a","p":3,"kind":"制度","alias":["宪法宣誓"],"one":"2016年1月1日起实行，国家工作人员就职时公开向宪法宣誓。","ans":"宪法宣誓制度是我国**国家工作人员就职宣誓制度**，属宪法实施重要机制。2015年全国人大常委会通过决定，自**2016年1月1日**起施行；2018年写入**宪法修正案**，誓词定为**75字**。该制度彰显宪法权威，强化公职人员履职责任。","pts":["2016年1月1日起施行，2018年写入宪法","国家工作人员就职公开宣誓，现行誓词75字","彰显宪法权威，强化公职人员履职责任"],"mem":"时间串记：“15定、16行、18入宪”，2015年7月通过决定，2016年元旦实行，2018年写入宪法并将誓词扩至75字（增加“美丽”和“现代化强国”）。","mix":"宣誓主体为国家工作人员，普通公民与社会组织成员不适用；2018年修宪同时将监察委员会组成人员纳入宣誓范围。","mcq":[{"q":"我国宪法宣誓制度正式开始施行的时间是","o":["2014年12月4日","2016年1月1日","2018年3月11日","2015年7月1日"],"a":1,"w":"2015年7月1日全国人大常委会通过决定，自2016年1月1日起正式施行。"}],"rel":[{"t":"现行宪法","n":"制度的根本法依据"},{"t":"现行宪法的五次修正","n":"2018年入宪"},{"t":"国家宪法日","n":"宪法宣传同簇"},{"t":"依法治国与十八届四中全会","n":"全会提出建立该制度"}],"more":"2018年现行75字誓词核心表述为“忠于中华人民共和国宪法，维护宪法权威……为建设富强民主文明和谐美丽的社会主义现代化强国努力奋斗”。","exam":[]},{"id":"a15-005","t":"宪法规定的国家机构","cid":"15a","p":1,"kind":"合称","alias":["国家机构","国家机构八类"],"one":"宪法第三章规定的八类国家机构，从人大到法院检察院。","ans":"宪法规定的国家机构指**现行宪法第三章“国家机构”所列的八类机构**，是人民行使国家权力的组织形式。依次为**全国人民代表大会（含常委会）、中华人民共和国主席、国务院、中央军事委员会、地方各级人民代表大会和人民政府、民族自治地方的自治机关、监察委员会、人民法院和人民检察院**。全国人大是最高国家权力机关，国家主席是国家元首，国务院是最高国家行政机关，国家监察委员会是最高监察机关，其中**监察委员会为2018年修宪新增**。这一结构体现人民代表大会统一行使国家权力、“一府一委两院”由其产生。","pts":["宪法第三章八类机构","人大最高权力机关；国务院最高行政机关","监察委员会2018年新增"],"members":[["全国人民代表大会","最高国家权力机关；常委会是常设机关"],["中华人民共和国主席","国家元首"],["国务院","最高国家行政机关，中央人民政府"],["中央军事委员会","领导全国武装力量，主席负责制"],["地方各级人民代表大会和人民政府","地方国家权力机关和行政机关"],["民族自治地方的自治机关","自治区、自治州、自治县的人大和政府"],["监察委员会","2018年增设，最高为国家监察委员会"],["人民法院和人民检察院","审判机关；法律监督机关"]],"mem":"顺序记“人、主、国、军、地、民、监、法检”：全国人大、主席、国务院、军委，然后地方、民族自治地方，最后是2018年新插入的监察委员会，再接法院检察院。“一府一委两院”里，一府是政府，一委是监察委员会，两院是法院和检察院，都由人大产生、对它负责、受它监督。","mix":"全国人大常委会不单列，属于全国人大一节；中国共产党的机构、政协不在宪法第三章的国家机构之列；检察院是国家的法律监督机关，法院是审判机关，二者不能互换。","mcq":[{"q":"2018年修宪后，宪法第三章新增的国家机构是","o":["国家监察委员会","国家主席","中央军事委员会","最高人民检察院"],"a":0,"w":"2018年宪法修正案增设国家监察委员会，列为国家机构的一节。"},{"q":"下列机构中，宪法明确规定为“最高国家权力机关”的是","o":["国务院","全国人民代表大会","中央军事委员会","最高人民法院"],"a":1,"w":"全国人大是最高国家权力机关，国务院是最高国家行政机关。"}],"rel":[{"t":"全国人民代表大会","n":"第一类机构"},{"t":"国务院","n":"最高国家行政机关"},{"t":"国家监察委员会","n":"2018年新增"},{"t":"最高人民法院与最高人民检察院","n":"两院的分工"},{"t":"公检法的分工","n":"司法机关职能"}],"more":"表格对照：全国人大（最高国家权力机关）、常委会（常设机关）、国家主席（国家元首）、国务院（最高国家行政机关）、中央军委（领导全国武装力量，主席负责制）、国家监委（最高监察机关）、最高法（最高审判机关）、最高检（最高检察机关）。","exam":[]},{"id":"a15-006","t":"全国人民代表大会","cid":"15a","p":1,"kind":"制度","alias":["全国人大","人大","全国人民代表大会（全国人大）"],"one":"最高国家权力机关，修改宪法、制定基本法律，任期五年。","ans":"全国人民代表大会是**我国的最高国家权力机关**，由省、自治区、直辖市、特别行政区和军队选出的代表组成，**每届任期五年，每年举行一次会议**。它行使国家立法权，**修改宪法（须全体代表三分之二以上多数通过）、监督宪法实施，制定和修改刑事、民事、国家机构的和其他基本法律**；选举国家主席、副主席，根据主席提名决定国务院总理人选，选举中央军委主席、国家监察委员会主任、最高法院院长和最高检察院检察长。国务院、监察委员会和两院都由它产生，对它负责。它的常设机关是全国人大常委会。","pts":["最高国家权力机关，任期五年","修改宪法（三分之二）、制定基本法律","选举或决定国家领导人，两院一府一委对其负责"],"mem":"画面：一年一度的“两会”之一，三月在北京人民大会堂开会。三个关键数字：5（任期五年）、1（每年一次会议）、2/3（修宪需三分之二）。职权用“修、监、立、选”四个字：修宪、监督、立法、选举。","mix":"制定“基本法律”归全国人大，“基本法律以外的法律”归常委会；修宪是人大，释宪是常委会；国务院是最高行政机关，不是权力机关。","mcq":[{"q":"全国人民代表大会修改宪法，须经全体代表","o":["过半数通过","五分之三以上通过","三分之二以上多数通过","四分之三以上通过"],"a":2,"w":"宪法规定修改宪法须全国人大全体代表的三分之二以上多数通过。"},{"q":"我国的最高国家权力机关是","o":["国务院","中国人民政治协商会议","最高人民法院","全国人民代表大会"],"a":3,"w":"全国人大是最高国家权力机关，政协不是国家机关。"}],"rel":[{"t":"全国人大常委会","n":"常设机关"},{"t":"人民代表大会制度","n":"根本政治制度"},{"t":"国家主席","n":"由全国人大选举"},{"t":"国务院","n":"由全国人大产生并对其负责"},{"t":"现行宪法","n":"修宪主体"}],"exam":[]},{"id":"a15-007","t":"全国人大常委会","cid":"15a","p":1,"kind":"制度","alias":["全国人民代表大会常务委员会","人大常委会","常委会"],"one":"全国人大的常设机关，解释宪法和法律，决定特赦。","ans":"全国人大常委会是**全国人民代表大会的常设机关**，也是行使国家立法权的机关，由委员长、副委员长、秘书长和委员组成，任期与全国人大相同，对全国人大负责并报告工作。它**解释宪法和法律、监督宪法实施**；**制定和修改除应当由全国人大制定的法律以外的其他法律**，在全国人大闭会期间对基本法律作部分补充和修改；监督国务院、监察委员会、最高法院和最高检察院的工作；**决定特赦**，由国家主席发布特赦令。它使人大在闭会期间保持日常运转。","pts":["全国人大的常设机关","解释宪法和法律，制定其他法律","决定特赦，主席发布特赦令"],"mem":"“释”“特”两个字要记牢：释宪（解释宪法）、特赦（决定特赦）都归常委会，修宪归大会。分工口诀：大会修宪定基本，常委释宪管其他，特赦常委定、主席宣。","mix":"最常见的错误是把“解释宪法”判给全国人大，或把“特赦”判给国家主席：主席只发布特赦令，决定权在常委会；基本法律由全国人大制定，其他法律由常委会制定。","mcq":[{"q":"根据宪法，决定特赦的机关是","o":["国家主席","全国人大常委会","国务院","全国人民代表大会"],"a":1,"w":"全国人大常委会决定特赦，国家主席根据决定发布特赦令。"},{"q":"下列职权中，属于全国人大而不属于全国人大常委会的是","o":["解释宪法","解释法律","修改宪法","决定特赦"],"a":2,"w":"修改宪法由全国人大行使，常委会只解释宪法、监督实施。"}],"rel":[{"t":"全国人民代表大会","n":"其常设机关"},{"t":"国家主席","n":"发布特赦令"},{"t":"《立法法》","n":"立法分工的依据"},{"t":"法律效力位阶","n":"法律与行政法规的位阶"}],"more":"新中国成立以来全国人大常委会决定过的特赦包括2015年（纪念抗日战争胜利70周年）和2019年（庆祝新中国成立70周年）两次。","exam":[]},{"id":"a15-008","t":"国家主席","cid":"15a","p":2,"kind":"制度","alias":["中华人民共和国主席"],"one":"我国国家元首，全国人大选举，依人大及其常委会决定公布法律等。","ans":"中华人民共和国主席是**我国的国家元首**，对内对外代表国家。国家主席由**全国人大选举**产生，须为年满**45周岁**的有选举权和被选举权的中国公民，每届任期五年。其职权须**依全国人大及其常委会决定**行使，含**公布法律**、任免国务院组成人员、授予国家勋章、**发布特赦令**、宣布战争状态和动员令，与全国人大常委会结合行使元首职权。","pts":["国家元首，全国人大选举，须年满45周岁","依人大及常委会决定公布法律、发布特赦令","代表国家进行国事活动，授予国家勋章"],"mem":"职权核心原则：“决定在人大，发布在主席”。凡看到“公布法律、发布特赦令、发布动员令、宣布战争状态”，都是国家主席依人大或常委会决定执行的宣告权。","mix":"特赦由全国人大常委会“决定”，由国家主席“发布”特赦令；2018年宪法修正案已删去国家主席、副主席“连续任职不得超过两届”的规定。","mcq":[{"q":"根据我国现行宪法，下列哪项职权由国家主席行使","o":["根据全国人大常委会的决定发布特赦令","决定特赦和解释宪法","制定和修改刑事、民事基本法律","制定行政法规和发布行政命令"],"a":0,"w":"决定特赦和解释宪法属全国人大常委会，制定基本法律属全国人大，制定行政法规属国务院；国家主席依决定发布特赦令。"}],"rel":[{"t":"宪法规定的国家机构","n":"国家机构职权总表"},{"t":"全国人民代表大会","n":"选举国家主席的机关"},{"t":"全国人大常委会","n":"共同行使国家元首职权"},{"t":"国家勋章和国家荣誉称号","n":"国家主席负责签发颁授"}],"more":"宪法第79条规定：有选举权和被选举权的年满45周岁的中华人民共和国公民可以被选为中华人民共和国主席、副主席。","exam":[]},{"id":"a15-009","t":"国务院","cid":"15a","p":2,"kind":"制度","alias":["中央人民政府"],"one":"中央人民政府，最高国家行政机关，实行总理负责制，制定行政法规。","ans":"国务院即**中央人民政府**，是最高国家权力机关的执行机关，也是我国**最高国家行政机关**。它由总理、副总理、国务委员、各部部长、各委主任、审计长和秘书长组成，实行**总理负责制**，总理、副总理、国务委员连任不超两届。核心职权包括**制定行政法规**、规定行政措施、编制和执行计划与预算、领导地方各级行政机关，对全国人大及其常委会负责。","pts":["中央人民政府，最高国家行政机关","实行总理负责制，总理等连任不超两届","制定行政法规，执行计划与国家预算"],"mem":"对比记法规层次：全国人大及常委会制定“法律”，国务院制定“行政法规”，部委制定“部门规章”。总理人选由国家主席提名、全国人大决定、国家主席任免。","mix":"国务院组成人员不含国家监察委员会主任；国务院实行总理负责制（首长负责制），区别于全国人大常委会和人民法院的集体负责制。","mcq":[{"q":"我国宪法规定，有权根据宪法和法律制定行政法规的国家机关是","o":["全国人民代表大会","全国人大常委会","最高人民法院","国务院"],"a":3,"w":"国务院是最高国家行政机关，负责制定行政法规；全国人大及其常委会制定法律。"}],"rel":[{"t":"宪法规定的国家机构","n":"“一府一委两院”之“一府”"},{"t":"法律效力位阶","n":"行政法规效力低于法律"},{"t":"国家主席","n":"提名国务院总理人选"},{"t":"2026年政府工作报告","n":"国务院向全国人大所作报告"}],"exam":[]},{"id":"a15-010","t":"中央军事委员会","cid":"15a","p":2,"kind":"制度","alias":["中央军委","国家中央军委"],"one":"领导全国武装力量的最高军事机关，实行主席负责制，无连任限制。","ans":"中华人民共和国中央军事委员会是**领导全国武装力量的最高军事机关**，由**1982年宪法**设立。它由主席、副主席和委员组成，实行**主席负责制**，每届任期五年，宪法**未设连任届数限制**。全国人大选举军委主席，依提名决定其他成员；军委主席对全国人大及其常委会负责。它与党的中央军委**“两块牌子、一套人马”**，贯彻军委管总格局。","pts":["1982年宪法设立，领导全国武装力量","实行主席负责制，无连任届数限制","军委主席对全国人大及其常委会负责"],"mem":"记三个关键特点：“82设立、主席负责、不限连任”。和国务院对比：国务院是“总理负责制”且总理限连任两届，中央军委是“主席负责制”且无连任届数限制。","mix":"1954年宪法曾规定国家主席统率全国武装力量并任国防委员会主席，1982年宪法才设立国家中央军事委员会；中央军委主席对全国人大及常委会负责，但无需作政府工作报告。","mcq":[{"q":"关于我国中央军事委员会，下列说法符合现行宪法规定的是","o":["实行委员会集体负责制","实行主席负责制，领导全国武装力量","由国务院统一领导并向国务院报告工作","中央军委主席连续任职不得超过两届"],"a":1,"w":"宪法规定中央军委领导全国武装力量，实行主席负责制，对全国人大及常委会负责，未限定连任届数。"}],"rel":[{"t":"军委管总、战区主战、军种主建","n":"新时代国防领导指挥体制"},{"t":"四个军种","n":"中央军委领导的武装力量"},{"t":"中国武装力量的构成","n":"解放军、武警与民兵"},{"t":"宪法规定的国家机构","n":"宪法第三章国家机构之一"}],"exam":[]},{"id":"a15-011","t":"国家监察委员会","cid":"15a","p":3,"kind":"制度","alias":["国家监委"],"one":"我国最高监察机关，2018年3月设立，领导地方各级监察委员会。","ans":"国家监察委员会是我国**最高监察机关**，由全国人大产生并对其负责，与中央纪委合署办公。**2018年3月**依宪法修正案与**《监察法》**设立，领导地方各级监委工作。新修正《监察法》于**2025年6月1日**施行，深化公职人员全覆盖监督。","pts":["最高监察机关，2018年3月设立","领导地方各级监委，依据《监察法》履职","与中央纪委合署办公，2025年新《监察法》施行"],"mem":"与“两院”对比记关系：最高法对下级法院是“监督”，最高检和国家监委对下级均为“领导”；设于2018年修宪，使国家机构从“一府两院”拓展为“一府一委两院”。","mix":"国家监察委员会是独立监察机关，区别于行政机关（国务院）与司法机关（法院、检察院）；主任连续任职不得超过两届。","mcq":[{"q":"关于国家监察委员会的宪法定位与上下级关系，说法正确的是","o":["隶属国务院，属最高行政监督机关","与最高法相同，监督地方各级监委","最高监察机关，领导地方各级监委","由全国人大常委会产生并向其负责"],"a":2,"w":"国家监委是最高监察机关，由全国人大产生，领导地方各级监察委员会工作。"}],"rel":[{"t":"《监察法》","n":"设立与履职法律依据"},{"t":"宪法规定的国家机构","n":"一府一委两院之一"},{"t":"现行宪法的五次修正","n":"2018年修宪增设"},{"t":"最高人民法院与最高人民检察院","n":"上下级关系对照"}],"exam":[]},{"id":"a15-012","t":"最高人民法院与最高人民检察院","cid":"15a","p":2,"kind":"制度","alias":["两高","最高法","最高检"],"one":"最高法是最高审判机关，监督下级；最高检是法律监督机关，领导下级。","ans":"最高人民法院与最高人民检察院合称**“两高”**，是宪法规定的最高司法机关。**最高人民法院**是**最高审判机关**，**监督**地方各级和专门人民法院审判工作；**最高人民检察院**是最高检察机关，人民检察院是**法律监督机关**，最高检**领导**地方各级和专门检察院工作。“两高”负责人由全国人大选举，连任不超两届，共同维护司法公正。","pts":["最高法是最高审判机关，监督下级法院","最高检是法律监督机关，领导下级检察院","两高负责人由全国人大选举，连任不超两届"],"mem":"高频考点对比口诀：“法监、检领”。法院上下级是“监督”关系（保证独立审判、两审终审），检察院上下级是“领导”关系（检察一体），一字之差最爱出选择题。","mix":"公安机关属于行政机关（国务院下设公安部），不属于司法机关；“公检法”中只有法院和检察院在宪法上称为司法机关。注意检察院才是国家的“法律监督机关”。","mcq":[{"q":"根据我国宪法，上下级人民法院和上下级人民检察院之间的关系分别是","o":["监督关系；领导关系","领导关系；监督关系","均为领导关系","均为监督关系"],"a":0,"w":"最高人民法院监督地方各级法院的审判工作；最高人民检察院领导地方各级检察院的工作。"}],"rel":[{"t":"公检法的分工","n":"刑事诉讼中分工与制约"},{"t":"两审终审制","n":"法院独立审判与监督基础"},{"t":"宪法规定的国家机构","n":"“一府一委两院”之两院"},{"t":"美国最高法院","n":"中西最高司法机关对照"}],"exam":[]},{"id":"a15-013","t":"特赦","cid":"15a","p":3,"kind":"制度","alias":["特赦令"],"one":"由全国人大常委会决定、国家主席发布特赦令的刑罚宽宥制度。","ans":"特赦是国家对特定罪犯免除全部或部分刑罚的**宽宥制度**，属宪法重要职权。我国规定特赦由**全国人大常委会决定**、**国家主席发布特赦令**。新中国自**1959年**起共实行**九次特赦**，最近一次在**2019年**建国70周年，彰显宽严相济法治精神。","pts":["全国人大常委会决定，国家主席发布特赦令","新中国1959年起共实行九次特赦","最近一次在2019年新中国成立70周年"],"mem":"口诀“常决主发，五九起九次”：全国人大常委会决定，国家主席发布；1959年首次特赦战犯，2015年第八次，2019年第九次，谐音“九次停在19年”。","mix":"我国现行宪法只规定特赦、未规定大赦；切勿将特赦决定权误记为全国人大或国务院，修改宪法归全国人大，决定特赦归全国人大常委会。","mcq":[{"q":"根据我国宪法，有权决定特赦的国家机关是","o":["全国人大常委会","全国人民代表大会","最高人民法院","国务院"],"a":0,"w":"宪法规定全国人大常委会决定特赦，国家主席根据决定发布特赦令。"}],"rel":[{"t":"全国人大常委会","n":"拥有特赦决定权"},{"t":"国家主席","n":"负责发布特赦令"},{"t":"宪法规定的国家机构","n":"国家机构职权考点"},{"t":"刑罚种类","n":"免除特定刑罚执行"}],"more":"前7次特赦（1959至1975年）主要面向战犯；第8次（2015年抗战胜利70周年）赦免四类罪犯；第9次（2019年建国70周年）赦免九类服刑罪犯。","exam":[]},{"id":"a15-014","t":"人民代表大会制度","cid":"15a","p":1,"kind":"制度","alias":["人大制度","根本政治制度"],"one":"我国的根本政治制度，国家权力由人民代表大会统一行使。","ans":"人民代表大会制度是**我国的根本政治制度**，也是实现**一切权力属于人民**的组织形式和制度载体。人民行使国家权力的机关是**全国人民代表大会和地方各级人民代表大会**，各级人大代表由民主选举产生，其中县乡两级人大代表由选民直接选举。国家行政机关、监察机关、审判机关、检察机关都由人大产生，对它负责，受它监督。这一制度以**民主集中制**为组织原则，1954年第一届全国人大一次会议召开后正式确立，保证了国家机关协调高效运转。","pts":["根本政治制度，一切权力属于人民","全国和地方各级人大行使国家权力","民主集中制；1954年首届全国人大确立"],"mem":"逻辑线：人民是主人，把权力交给代表，代表组成人大，人大再产生“一府一委两院”，所以人大居于最高位置。数字挂钩：1954 年首届全国人大，2024 年正好 70 周年。“根本”对“基本”：人大是根本政治制度，政协、民族区域自治、基层群众自治是基本政治制度。","mix":"人民代表大会制度是“根本政治制度”，中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度属于“基本政治制度”，选择题常设此对照；政协不属于国家机关。","mcq":[{"q":"我国的根本政治制度是","o":["政治协商制度","民族区域自治制度","基层群众自治制度","人民代表大会制度"],"a":3,"w":"人民代表大会制度是根本政治制度，其他三项是基本政治制度。"},{"q":"我国县乡两级人大代表的产生方式是","o":["上一级人大选举","选民直接选举","政协推荐任命","政府委派"],"a":1,"w":"不设区的市、市辖区、县、乡、民族乡、镇的人大代表由选民直接选举。"}],"rel":[{"t":"全国人民代表大会","n":"最高国家权力机关"},{"t":"中国共产党领导的多党合作和政治协商制度","n":"基本政治制度"},{"t":"民族区域自治制度与五个自治区","n":"基本政治制度"},{"t":"新中国第一部宪法","n":"1954年确立该制度"}],"more":"2024年是全国人民代表大会成立70周年。","exam":[]},{"id":"a15-015","t":"中国共产党领导的多党合作和政治协商制度","cid":"15a","p":1,"kind":"制度","alias":["多党合作和政治协商制度","政治协商制度","人民政协","中国人民政治协商会议","政协"],"one":"我国基本政治制度之一，政协是其重要实现形式。","ans":"中国共产党领导的多党合作和政治协商制度是**我国的基本政治制度**，与**民族区域自治制度、基层群众自治制度**并列，1993年写入宪法序言。它的特点是共产党执政，各民主党派参政，**共产党与各民主党派“长期共存、互相监督、肝胆相照、荣辱与共”**。中国人民政治协商会议是其重要实现形式，**1949年9月召开第一届全体会议**，通过《共同纲领》并成立中央人民政府，此后行使政治协商、民主监督、参政议政职能。政协不是国家机关，这一制度使不同党派和各界人士参与国家事务。","pts":["基本政治制度，共产党领导各党派参政","政协是重要实现形式，1949年9月首届全体会议","职能：政治协商、民主监督、参政议政"],"mem":"八个民主党派首字串联：“民革、民盟、民建、民进，农工、致公、九三、台盟”，念成“革盟建进农致九台”。政协三大职能“协、监、参”：政治协商、民主监督、参政议政。十六字方针“长期共存、互相监督、肝胆相照、荣辱与共”。","mix":"人大是根本政治制度，多党合作和政治协商制度是基本政治制度之一；政协是协商机构，不是国家权力机关，也不行使立法权；民主党派是参政党，不是反对党。","mcq":[{"q":"下列属于我国基本政治制度的是","o":["中国共产党领导的多党合作和政治协商制度","人民代表大会制度","民主集中制","人民民主专政"],"a":0,"w":"人民代表大会制度是根本政治制度，多党合作和政治协商制度是基本政治制度之一。"},{"q":"第一届中国人民政治协商会议全体会议召开于","o":["1921年","1954年","1978年","1949年"],"a":3,"w":"1949年9月召开第一届政协全体会议，通过了《共同纲领》。"}],"rel":[{"t":"《中国人民政治协商会议共同纲领》","n":"首届政协通过"},{"t":"人民代表大会制度","n":"根本政治制度"},{"t":"民族区域自治制度与五个自治区","n":"同属基本政治制度"}],"more":"八个民主党派：中国国民党革命委员会、中国民主同盟、中国民主建国会、中国民主促进会、中国农工民主党、中国致公党、九三学社、台湾民主自治同盟。","exam":[]},{"id":"a15-016","t":"八个民主党派","cid":"15a","p":2,"kind":"合称","alias":["中国八大民主党派","民主党派"],"one":"民革、民盟、民建、民进、农工党、致公党、九三学社、台盟，我国参政党。","ans":"八个民主党派是我国**多党合作和政治协商制度**中的**参政党**，接受中共领导，遵循“长期共存、互相监督、肝胆相照、荣辱与共”方针。依次为**民革、民盟、民建、民进**（国民党革命委员会、民主同盟、民主建国会、民主促进会）与**农工党、致公党、九三学社、台盟**（台湾民主自治同盟）。它们履行**参政议政、民主监督**职能。","pts":["民革、民盟、民建、民进、农工、致公、九三、台盟","我国多党合作制度中的参政党","方针：长期共存、互相监督、肝胆相照、荣辱与共"],"mem":"通行顺口溜：“革盟建进，农致九台”。前四个都带“民”字（民革、民盟、民建、民进），后四个记特色：农工（医药）、致公（归侨）、九三（科技，纪念9月3日抗战胜利）、台盟（台湾）。","mix":"我国政党制度中，民主党派是“参政党”而非“在野党”或“反对党”；中华全国工商业联合会（全国工商联）是人民团体和商会组织，不属于八个民主党派。","members":[["中国国民党革命委员会（民革）","1948年成立，同国民党民主派及对台工作有历史联系"],["中国民主同盟（民盟）","1941年成立，以文化教育及科技界知识分子为主"],["中国民主建国会（民建）","1945年成立，主要联系经济界人士"],["中国民主促进会（民进）","1945年成立，以教育文化出版传媒界为主"],["中国农工民主党（农工党）","1930年成立，以医药卫生、人口资源和生态环境界为主"],["中国致公党（致公党）","1925年成立，以归侨、侨眷中的中上层人士为主"],["九三学社","1946年正式成立，以科学技术界高、中级知识分子为主"],["台湾民主自治同盟（台盟）","1947年成立，由台湾省人士组成"]],"mcq":[{"q":"下列组织中，不属于我国八个民主党派的是","o":["中国致公党","九三学社","中华全国工商业联合会","台湾民主自治同盟"],"a":2,"w":"全国工商联是党领导的以民营企业和民营经济人士为主体的人民团体和商会组织，不属于八个民主党派。"}],"rel":[{"t":"中国共产党领导的多党合作和政治协商制度","n":"八个民主党派所在制度"},{"t":"《中国人民政治协商会议共同纲领》","n":"各民主党派共同参与制定"},{"t":"民主党与两党制","n":"中西政党制度对照"}],"more":"成立最早的是中国致公党（1925年10月在美国旧金山成立）；九三学社得名于纪念1945年9月3日抗日战争暨世界反法西斯战争胜利。","exam":[]},{"id":"a15-017","t":"民族区域自治制度与五个自治区","cid":"15a","p":2,"kind":"合称","alias":["民族区域自治","五大自治区","五个自治区"],"one":"基本政治制度，五个自治区依次为内蒙古、新疆、广西、宁夏、西藏。","ans":"民族区域自治制度是我国**基本政治制度**，指在国家统一领导下，各少数民族聚居区设立自治机关、行使自治权，分**自治区、自治州、自治县**三级。我国**五个省级自治区**按成立先后为：**内蒙古（1947年）**、**新疆（1955年）**、**广西（1958年）**、**宁夏（1958年）**、**西藏（1965年）**。该制度把国家统一与民族自治结合，保障各民族共同繁荣发展。","pts":["基本政治制度，分自治区、自治州、自治县三级","内蒙古47、新疆55、广西宁夏58、西藏65","内蒙古最早成立（早于新中国成立）"],"mem":"时间先后口诀：“内新广宁藏，四七五五五八六五”。牢记一头一尾：内蒙古1947年最早（比新中国还早两年），西藏1965年最晚；1958年双喜临门（3月广西、10月宁夏）。","mix":"民族乡不是民族自治地方，只有自治区、自治州、自治县三级才是；自治机关指民族自治地方的人大和人民政府，不包括法院和检察院。","members":[["内蒙古自治区","1947年5月1日成立，我国最早的省级自治区，首府呼和浩特"],["新疆维吾尔自治区","1955年10月1日成立，我国陆地面积最大的省级行政区，首府乌鲁木齐"],["广西壮族自治区","1958年3月5日成立（原名广西僮族自治区），首府南宁"],["宁夏回族自治区","1958年10月25日成立，首府银川"],["西藏自治区","1965年9月1日宣告成立，最晚成立的省级自治区，首府拉萨"]],"mcq":[{"q":"我国五个省级民族自治区中，成立时间最早的是","o":["新疆维吾尔自治区","内蒙古自治区","广西壮族自治区","西藏自治区"],"a":1,"w":"内蒙古自治区成立于1947年5月1日，早于1949年新中国成立，是五个自治区中最早的。"}],"rel":[{"t":"民族团结进步促进法","n":"2026年民族领域新法"},{"t":"铸牢中华民族共同体意识","n":"新时代民族工作主线"},{"t":"中国疆域与行政区划","n":"34个省级行政区构成"}],"more":"西藏自治区第一届人大一次会议于1965年9月1日开幕宣告成立、9月9日闭幕，1985年起官方统一以9月1日为成立纪念日。","exam":[]},{"id":"a15-018","t":"基层群众自治制度","cid":"15a","p":3,"kind":"制度","alias":["基层自治"],"one":"我国基本政治制度之一，以城市居委会和农村村委会为自治组织。","ans":"基层群众自治制度是我国**基本政治制度**之一，属基层民主实践。城乡居民依托**城市居民委员会**和**农村村民委员会**，依法实行自我管理、自我服务、自我教育、自我监督。新修订两部组织法于**2026年1月1日**施行，夯实全过程人民民主根基。","pts":["我国基本政治制度之一，实行“四个自我”","居委会与村委会是基层群众性自治组织","新修订两部组织法2026年1月1日施行"],"mem":"区分“根本”与“基本”：1个根本政治制度（人大制度），3个基本政治制度（多党合作、民族区域自治、基层群众自治）；记住“村委居委不姓官”，它们是非政权自治组织。","mix":"居委会、村委会是基层群众性自治组织，与乡镇人民政府或街道办事处之间是指导与协助关系，不属于一级国家政权机关。","mcq":[{"q":"关于我国城市居民委员会和农村村民委员会的性质，表述正确的是","o":["最基层的国家行政机关","乡镇政府与街道的派出机构","一级基层国家权力机关","基层群众性自治组织"],"a":3,"w":"居委会和村委会是基层群众性自治组织，不属国家政权机关，基层政府对其起指导作用。"}],"rel":[{"t":"人民代表大会制度","n":"根本政治制度对照"},{"t":"民族区域自治制度与五个自治区","n":"同属基本政治制度"},{"t":"中国共产党领导的多党合作和政治协商制度","n":"同属基本政治制度"},{"t":"全过程人民民主","n":"基层民主生动实践"}],"exam":[]},{"id":"a15-019","t":"公民的基本权利和义务","cid":"15a","p":2,"kind":"制度","alias":["宪法基本权利","选举权和被选举权"],"one":"宪法第二章：18岁享选举权，劳动和受教育既是权利也是义务。","ans":"公民的基本权利和义务规定于**《宪法》第二章**，界定国家权力与公民关系。基本权利涵盖平等权、政治权利、人身自由与社会经济权利；**年满18周岁**的中国公民都有**选举权和被选举权**（依法被剥夺政治权利者除外）。**劳动**和**受教育**具有双重属性，**既是基本权利也是基本义务**。维护国家统一、依法服兵役、依法纳税等为基本义务，体现权利与义务相统一原则。","pts":["《宪法》第二章，体现权利与义务相统一","年满18周岁享选举权和被选举权（剥政除外）","劳动和受教育既是基本权利也是基本义务"],"mem":"抓选择题三大高频点：一章（宪法第二章）、一岁（18周岁选举权）、一双（“劳教”双身份：劳动+受教育既是权利又是义务）。","mix":"“公民”是法律概念（具有中国国籍的自然人），“人民”是政治概念，选举权归属于未被剥夺政治权利的成年公民；注意“依法纳税”和“依法服兵役”只是义务，不是权利。","mcq":[{"q":"根据我国现行宪法，下列各项中既是公民基本权利又是公民基本义务的是","o":["依法纳税和服兵役","选举权和被选举权","言论自由和出版自由","劳动和受教育"],"a":3,"w":"宪法第42条、第46条明确规定，中华人民共和国公民有劳动的权利和义务，有受教育的权利和义务。"}],"rel":[{"t":"现行宪法","n":"公民权利义务规定于第二章"},{"t":"法定婚龄与民事行为能力","n":"18周岁成年标准对照"},{"t":"《人权宣言》","n":"中外宪法权利条款对照"}],"exam":[]},{"id":"a15-020","t":"国家象征","cid":"15a","p":2,"kind":"合称","alias":["宪法第四章","国旗国歌国徽首都"],"one":"宪法第四章规定：国旗五星红旗、国歌《义勇军进行曲》、国徽、首都北京。","ans":"国家象征是代表国家主权与尊严的法定标志，规定于我国**《宪法》第四章**，包括**国旗、国歌、国徽、首都**四项。国旗为**五星红旗**（曾联松设计）；国歌为**《义勇军进行曲》**（田汉词、聂耳曲，**2004年写入宪法**）；国徽由五星照耀下的**天安门、谷穗和齿轮**构成，象征工人阶级领导的工农联盟；首都是**北京**。四项象征受专门法律保护，凝聚国家认同。","pts":["《宪法》第四章：国旗、国歌、国徽、首都","国歌《义勇军进行曲》于2004年写入宪法","国徽元素：国旗五星、天安门、谷穗、齿轮"],"mem":"按宪法条文顺序记“旗、歌、徽、都”四字。国徽四元素拆成画面：天上五星，地上天安门，左右围一圈谷穗（农民）和齿轮（工人）。","mix":"1949年一届政协决定以《义勇军进行曲》为代国歌，1982年恢复其为正式国歌，但直到2004年第四次修宪才写入宪法正文；国徽中没有镰刀锤头（那是党徽）。","members":[["国旗：五星红旗","曾联松设计，大五角星代表中国共产党，四颗小星代表全国人民"],["国歌：《义勇军进行曲》","田汉词、聂耳曲，1949年定为代国歌，2004年写入宪法"],["国徽","五星照耀下的天安门，周围为谷穗和齿轮，梁思成等参与设计"],["首都：北京","1949年一届政协决定改北平为北京并定为首都"]],"mcq":[{"q":"下列元素中，不属于中华人民共和国国徽图案组成部分的是","o":["天安门","齿轮","谷穗","长城"],"a":3,"w":"宪法规定国徽中间是五星照耀下的天安门，周围是谷穗和齿轮，不含长城。"}],"rel":[{"t":"《义勇军进行曲》","n":"我国法定国歌"},{"t":"现行宪法的五次修正","n":"2004年将国歌写入宪法"},{"t":"《中国人民政治协商会议共同纲领》","n":"1949年一届政协确立国旗首都"}],"exam":[]},{"id":"a15-021","t":"国家纪念日","cid":"15a","p":2,"kind":"合称","alias":["三大国家纪念日","法定国家纪念日"],"one":"2014年全国人大常委会设立：9·3抗战胜利、9·30烈士、12·13公祭日。","ans":"国家纪念日指国家立法机关以法律决定设立的重大历史纪念日。**2014年**，十二届全国人大常委会先后确立三个法定纪念日：每年**9月3日**为**中国人民抗日战争胜利纪念日**，每年**9月30日**为**烈士纪念日**（国庆前一日），每年**12月13日**为**南京大屠杀死难者国家公祭日**（1937年南京沦陷日）。三者以国家立法铭记历史、缅怀先烈、珍爱和平。","pts":["均由十二届全国人大常委会于2014年设立","9·3抗战胜利、9·30烈士、12·13国家公祭","以国家立法铭记抗战历史与先烈功绩"],"mem":"按日历顺序串联日期：“9·3胜利 → 9·30敬烈士（国庆前一天） → 12·13公祭南京”。再加同年底设立的12·4国家宪法日，四个日期全在2014年落地。","mix":"8月15日是日本宣布无条件投降日，中国法定的抗战胜利纪念日是9月3日（而非8月15日）；9月30日烈士纪念日选在国庆前一天，寓意“饮水思源、不忘先烈”。","members":[["中国人民抗日战争胜利纪念日","每年9月3日，2014年2月27日全国人大常委会决定设立"],["烈士纪念日","每年9月30日，2014年8月31日全国人大常委会决定设立"],["南京大屠杀死难者国家公祭日","每年12月13日，2014年2月27日全国人大常委会决定设立"]],"mcq":[{"q":"2014年全国人大常委会以立法形式确立的“烈士纪念日”是每年的","o":["9月3日","9月30日","12月4日","12月13日"],"a":1,"w":"9月30日为烈士纪念日；9月3日是抗战胜利纪念日，12月4日是国家宪法日，12月13日是国家公祭日。"}],"rel":[{"t":"国家宪法日","n":"2014年同年立法设立"},{"t":"2025年九三阅兵","n":"抗战胜利80周年纪念"},{"t":"《英雄烈士保护法》","n":"保护英烈名誉的专门法律"},{"t":"全民国防教育日","n":"每年9月第三个星期六"}],"exam":[]},{"id":"a15-022","t":"依法治国与十八届四中全会","cid":"15a","p":2,"kind":"概念","alias":["全面依法治国","十八届四中全会"],"one":"1997年十五大提出、1999年入宪；2014年十八届四中全会首以法治为主题。","ans":"依法治国是党领导人民治理国家的基本方略，**全面依法治国**是“四个全面”战略布局之一。**1997年十五大**提出依法治国，**1999年修宪**写入宪法。**2014年10月**召开的**十八届四中全会**是中共**首次以法治为主题的中央全会**，通过《关于全面推进依法治国若干重大问题的决定》，确立建设中国特色社会主义法治体系和法治国家的总目标。","pts":["1997年十五大提出，1999年写入宪法","2014年十八届四中全会首次以法治为主题","总目标：建设中国特色社会主义法治体系和国家"],"mem":"三步时间轴：“97提出（十五大）→ 99入宪（第三次修宪）→ 14全会（十八届四中全会首次专讲法治）”。四中全会与“法”谐音关联“四法”，不易忘。","mix":"“法治”与“法制”不同：1999年修宪写的是“建设社会主义法治国家”（三点水“治”，强调良法善治与法律至上），区别于单纯指法律制度总和的“法制”。","mcq":[{"q":"中国共产党历史上第一次以“依法治国”为主题召开的中央全会是","o":["十一届三中全会","十八届三中全会","十八届四中全会","十九届四中全会"],"a":2,"w":"2014年10月召开的十八届四中全会是首次以法治为主题的中央全会；十八届三中全会主题是全面深化改革。"}],"rel":[{"t":"“四个全面”","n":"全面依法治国是其中之一"},{"t":"法治与法制","n":"易混核心概念辨析"},{"t":"现行宪法的五次修正","n":"1999年修宪将依法治国入宪"},{"t":"国家宪法日","n":"十八届四中全会提出设立"}],"exam":[]},{"id":"a15-023","t":"法律效力位阶","cid":"15a","p":2,"kind":"概念","alias":["法的效力层级","法律位阶"],"one":"宪法最高，依次为法律、行政法规、地方性法规与规章。","ans":"法律效力位阶指**不同国家机关所制规范性法律文件间的效力等级**，由《宪法》和《立法法》确立。我国实行**宪法至上**，**宪法具有最高法律效力**。具体层级为：**宪法 > 法律 > 行政法规 > 地方性法规和规章**；地方性法规高于本级和下级地方政府规章，**部门规章与地方政府规章具有同等效力**，保障法制统一与冲突裁决。","pts":["宪法具有最高法律效力，上位法优于下位法","依次为宪法、法律、行政法规、地方法规与规章","部门规章与地方政府规章具有同等效力"],"mem":"金字塔口诀：“宪 > 法 > 行 > 地/规”。特别记两个高频考点：同级之间“新法优于旧法、特别法优于一般法”；部门规章和地方政府规章打平手，冲突时由国务院裁决。","mix":"部门规章（国务院各部委制定）与地方性法规（省市人大制定）之间没有直接上下位关系，二者冲突时由国务院提出意见，适用部门规章须提请全国人大常委会裁决。","mcq":[{"q":"根据《立法法》，下列关于我国法律效力位阶的表述正确的是","o":["行政法规的效力高于地方性法规和规章","部门规章的效力高于地方政府规章","地方政府规章的效力高于本级地方性法规","基本法律与宪法具有同等法律效力"],"a":0,"w":"宪法效力最高，其次是法律、行政法规，再往下是地方性法规和规章；部门规章与地方政府规章具有同等效力。"}],"rel":[{"t":"《立法法》","n":"规定法律位阶的法律"},{"t":"现行宪法","n":"效力位阶的最高层"},{"t":"国务院","n":"行政法规制定与冲突裁决者"}],"exam":[]},{"id":"a15-024","t":"特别行政区基本法","cid":"15a","p":2,"kind":"制度","alias":["香港基本法","澳门基本法","基本法"],"one":"香港基本法1990通过、1997施行；澳门1993通过、1999施行。","ans":"特别行政区基本法是**全国人大依《宪法》第31条制定的全国性基本法律**，将“一国两制”制度化。**《香港特别行政区基本法》**于**1990年4月4日**通过、**1997年7月1日**施行；**《澳门特别行政区基本法》**于**1993年3月31日**通过、**1999年12月20日**施行。两法修改权属全国人大，**解释权属全国人大常委会**，保障港澳繁荣稳定。","pts":["全国人大依宪法制定，属全国性基本法律","香港90通过97施行；澳门93通过99施行","修改权属全国人大，解释权属全国人大常委会"],"mem":"两组年份配对记：香港“90通、97行（7月1日）”，澳门“93通、99行（12月20日）”。口诀：“港九零九七，澳九三九九；人大改，常委释”。","mix":"特别行政区基本法是全国性法律而非地方性法规，其效力来源于国家《宪法》；解释权归全国人大常委会，特区法院仅在审理案件时获授权对自治范围内条款作解释。","mcq":[{"q":"《中华人民共和国香港特别行政区基本法》和《澳门特别行政区基本法》的解释权属于","o":["特别行政区终审法院","全国人民代表大会常务委员会","国务院港澳事务办公室","特别行政区立法会"],"a":1,"w":"两部基本法均明确规定，基本法的解释权属于全国人民代表大会常务委员会，修改权属于全国人民代表大会。"}],"rel":[{"t":"“一国两制”","n":"基本法落实的根本方针"},{"t":"现行宪法","n":"宪法第31条是特区设立依据"},{"t":"全国人大常委会","n":"依法享有基本法解释权"}],"exam":[]},{"id":"a15-025","t":"民法基本原则","cid":"15b","p":2,"kind":"合称","alias":["民法典六大基本原则","绿色原则"],"one":"《民法典》六大原则：平等、自愿、公平、诚信、守法与公序良俗、绿色。","ans":"民法基本原则是**指导民事立法与司法的根本准则**，规定于《民法典》总则编第一章，共**六项**：**平等、自愿、公平、诚信、守法与公序良俗、绿色原则**。平等自愿体现私法自治，公平与**诚信**（民法“帝王条款”）维护交易公正，守法与公序良俗划定底线，**绿色原则**要求民事活动**节约资源、保护生态环境**，彰显我国民法典的时代特色。","pts":["平等、自愿、公平、诚信、守法与公序良俗、绿色","诚信原则被称为民法“帝王条款”","绿色原则要求节约资源、保护生态环境"],"mem":"口诀记六原则：“平、自、公、诚、俗、绿”（平自公诚，守俗护绿）。重点盯住新增特色项“绿色原则”，它是中国民法典区别于传统西方民法典的亮点。","mix":"“罪刑法定”是刑法基本原则，“合法行政”是行政法原则，常作为民法基本原则的干扰项；民法里的“公序良俗”指公共秩序和善良风俗。","members":[["平等原则","民事主体在民事活动中的法律地位一律平等"],["自愿原则","按照自己的意思设立、变更、终止民事法律关系"],["公平原则","合理确定各方的权利和义务"],["诚信原则","秉持诚实、恪守承诺，被称为民法“帝王条款”"],["守法与公序良俗原则","不得违反法律，不得违背公共秩序与善良风俗"],["绿色原则","民事活动应当有利于节约资源、保护生态环境"]],"mcq":[{"q":"《民法典》规定民事活动应有利于节约资源、保护生态环境，这体现的民法基本原则是","o":["公平原则","诚信原则","公序良俗原则","绿色原则"],"a":3,"w":"《民法典》第9条确立了绿色原则，明确民事主体从事民事活动应当有利于节约资源、保护生态环境。"}],"rel":[{"t":"民法典","n":"总则编第4至第9条规定"},{"t":"生态环境法典","n":"绿色原则的专门法典呼应"},{"t":"刑法三大基本原则","n":"民法与刑法原则对照"}],"exam":[]},{"id":"a15-026","t":"诉讼时效","cid":"15b","p":2,"kind":"制度","alias":["普通诉讼时效","三年诉讼时效"],"one":"《民法典》规定普通诉讼时效3年，最长保护期20年，不消灭实体债权。","ans":"诉讼时效是**民法上权利人长期不行使权利致对方获抗辩权的制度**，规定于《民法典》总则编。我国**普通诉讼时效为三年**，自权利人**知道或应当知道权利受损及义务人之日**起算；自受损之日起超**二十年**的，法院不予保护。时效届满不消灭实体债权，自愿履行的不得反悔；请求停止侵害、支付抚养费等不适用时效，以督促维权、稳定秩序。","pts":["普通诉讼时效3年，自知道受损及义务人起算","最长保护期20年，自权利受损害之日起算","届满后对方享抗辩权，不消灭实体债权"],"mem":"数字口诀：“普三最二十，外贸给四年”（普通3年、最长20年、国际货物买卖和技术进出口合同4年）。牢记一句话：“过期不等于债没了，只是对方可以拒绝还”。","mix":"原《民法通则》普通诉讼时效为2年，《民法总则》和《民法典》已统一延长为3年；人民法院不得主动适用诉讼时效的规定，必须由义务人提出抗辩。","mcq":[{"q":"根据我国《民法典》，向人民法院请求保护民事权利的普通诉讼时效期间为","o":["一年","二年","三年","五年"],"a":2,"w":"《民法典》第188条规定普通诉讼时效期间为三年，最长权利保护期为二十年。"}],"rel":[{"t":"民法典","n":"总则编第九章核心制度"},{"t":"民法典七编","n":"位于总则编的通用规则"},{"t":"三大诉讼","n":"民事诉讼维权程序"}],"exam":[]},{"id":"a15-027","t":"离婚冷静期","cid":"15b","p":2,"kind":"制度","alias":["三十日离婚冷静期","协议离婚冷静期"],"one":"《民法典》协议离婚制度：申请后30日内可撤回，期满30日内共同领证。","ans":"离婚冷静期是**《民法典》婚姻家庭编在协议离婚中设立的缓冲制度**，2021年1月1日施行。自婚姻登记机关收到**协议离婚**申请起**三十日内**，任一方不愿离婚的可**撤回**申请；期满后**三十日内**，双方须共同申请领离婚证，未申请视为撤回。冷静期**仅适用于协议离婚，不适用于诉讼离婚**（如遇家暴可直接起诉），以减少冲动离婚。","pts":["《民法典》婚姻家庭编新设，2021年起施行","两个30日：申请后30日可撤回，期满30日领证","仅适用协议离婚，不适用诉讼离婚"],"mem":"记“双30+只管协议”：前30天是反悔期（单方可撤），后30天是领证期（双方必去，不去作废）；遇家暴走法院诉讼离婚，完全不受冷静期限制。","mix":"最常见干扰项是说“诉讼离婚也必须经过30日冷静期”或“冷静期后自动解除婚姻关系”，两者均错；冷静期满后30日内双方不到场申请领证的，视为撤回申请。","mcq":[{"q":"关于《民法典》规定的“离婚冷静期”，下列说法正确的是","o":["同时适用于协议离婚和诉讼离婚","期限为六十日，期满后婚姻关系自动解除","仅适用于协议离婚，申请之日起三十日内任一方可撤回","冷静期内必须双方共同同意才能撤回离婚申请"],"a":2,"w":"离婚冷静期为三十日，仅适用于协议离婚，期内任何一方均可单方撤回申请，期满后三十日内须共同申领离婚证。"}],"rel":[{"t":"可撤销婚姻","n":"同属婚姻家庭编高频考点"},{"t":"无效婚姻","n":"婚姻家庭编核心制度"},{"t":"《反家庭暴力法》","n":"涉家暴可直接诉讼离婚"},{"t":"民法典","n":"2020年通过的新增制度"}],"exam":[]},{"id":"a15-028","t":"法定继承顺序","cid":"15b","p":2,"kind":"制度","alias":["继承顺序","第一顺序继承人","第二顺序继承人"],"one":"第一顺序：配偶、子女、父母；第二顺序：兄弟姐妹、祖父母、外祖父母。","ans":"法定继承顺序是**《民法典》继承编规定的无有效遗嘱时遗产分配次序**。**第一顺序**为**配偶、子女、父母**；**第二顺序**为**兄弟姐妹、祖父母、外祖父母**。有第一顺序继承人时，第二顺序不继承；无第一顺序才由第二顺序继承。尽主要赡养义务的**丧偶儿媳、丧偶女婿**列为第一顺序；《民法典》还将代位继承扩至侄甥，兼顾血缘与养老。","pts":["第一顺序：配偶、子女、父母","第二顺序：兄弟姐妹、祖父母、外祖父母","有第一则第二不继承；尽主要赡养儿媳女婿列第一"],"mem":"家庭核心圈分层记忆：第一顺序是“小家核心铁三角”（配偶+子女+父母）；第二顺序是“往外扩一圈”（同辈兄弟姐妹+隔代祖父母、外祖父母）。","mix":"常见陷阱是把“兄弟姐妹”或“孙子女”放进第一顺序：兄弟姐妹属第二顺序；孙子女、外孙子女不在法定继承顺序内，仅在父母先于祖父母去世时通过“代位继承”取得份额。","mcq":[{"q":"根据《民法典》，下列人员中不属于法定第一顺序继承人的是","o":["配偶","子女","父母","兄弟姐妹"],"a":3,"w":"第一顺序为配偶、子女、父母；兄弟姐妹、祖父母、外祖父母属于第二顺序继承人。"}],"rel":[{"t":"民法典七编","n":"规定于第六编继承编"},{"t":"民法典","n":"扩大代位继承范围"},{"t":"法定婚龄与民事行为能力","n":"同属民法典日常规则"}],"exam":[]},{"id":"a15-029","t":"遗嘱形式","cid":"15b","p":3,"kind":"制度","alias":["六种遗嘱形式"],"one":"《民法典》规定六种遗嘱，取消公证优先，抵触时以最后遗嘱为准。","ans":"遗嘱形式是《民法典》继承编规定的法定遗嘱方式，分**自书、代书、打印、录音录像、口头、公证**六种。其中**打印与录音录像遗嘱**为《民法典》新增。该编取消**公证遗嘱效力优先**，数份遗嘱抵触时以**最后的为准**，充分尊重真实意愿。","pts":["六种：自书、代书、打印、录音录像、口头、公证","新增打印与录音录像遗嘱，取消公证遗嘱优先","数份遗嘱相抵触的，以最后的遗嘱为准"],"mem":"六字口诀“自代打录口公”：自己写、别人代、电脑打、录影留声、危急口说、公证办理。记一个大反转：《民法典》施行后，公证遗嘱不再“一票压百票”，谁在最后听谁的。","mix":"代书、打印、录音录像和口头遗嘱均须有两个以上无利害关系见证人在场见证；危急情况消除后，遗嘱人能以书面或录音录像形式立遗嘱的，所立口头遗嘱无效。","mcq":[{"q":"老王先后立下经公证的遗嘱和合法有效的自书遗嘱，两份内容冲突。按《民法典》应","o":["以公证遗嘱为准","以最后的自书遗嘱为准","按法定继承重新分配","两份遗嘱均归无效"],"a":1,"w":"《民法典》取消公证遗嘱效力优先规则，立有数份遗嘱内容相抵触的，以最后的遗嘱为准。"}],"rel":[{"t":"法定继承顺序","n":"同属民法典继承编"},{"t":"民法典","n":"继承编重要制度更新"},{"t":"民法典七编","n":"归属第六编继承编"}],"exam":[]},{"id":"a15-030","t":"著作权","cid":"15b","p":1,"kind":"制度","alias":["版权","《著作权法》","翻译权","著作权法"],"one":"作者对作品享有的人身权和财产权，翻译权属财产权。","ans":"著作权即版权，是**作者及其他著作权人依法对文学、艺术和科学作品享有的权利**，由《著作权法》规范。该法**1990年通过、1991年6月1日施行**，2001年、2010年修正，**2020年第三次修正、2021年6月1日施行**。著作权包括署名权、修改权、保护作品完整权等人身权和复制、改编、**翻译**、信息网络传播等财产权。自然人作品的财产权保护期为**作者终生及死后五十年**。译文属于演绎作品，**译者享有译文的著作权，但行使时不得侵犯原作品的著作权**，翻译受保护的他人作品通常须取得许可。","pts":["1991年施行，2021年第三次修正施行","人身权与财产权，翻译权属财产权","终生及死后50年；译者不得侵犯原著权"],"mem":"年份连号：1990 通过、1991 施行；2020 修正、2021 施行，两组都是“前年通过、后年施行”，恰好与民法典 2020、2021 同步。翻译挂钩：翻译权在财产权里，保护期“生前加死后 50 年”。译者的位置：作品仍受保护时，翻译通常须经著作权人许可，译完译者有版权，但不能反过来侵犯原作者。","mix":"署名权、修改权、保护作品完整权属人身权，翻译权、改编权属财产权；保护期“终生加五十年”适用于自然人作品，法人作品和视听作品另按发表后五十年计算；翻译受保护的他人作品通常须经著作权人许可，法定例外见《著作权法》第24条。","mcq":[{"q":"下列权利中，属于著作权财产权的是","o":["署名权","修改权","翻译权","保护作品完整权"],"a":2,"w":"翻译权是著作财产权，署名权、修改权、保护作品完整权属于人身权。"},{"q":"我国自然人作品的著作财产权保护期一般为","o":["作者终生及死后三十年","作者终生及死后五十年","作者终生及死后七十年","作品发表后二十年"],"a":1,"w":"自然人作品的财产权保护期为作者终生及死后五十年。"}],"rel":[{"t":"民法典","n":"同为民事基本法律"},{"t":"翻译硕士专业学位（MTI）","n":"翻译职业的法律常识"},{"t":"国际翻译日","n":"翻译行业对照"},{"t":"《个人信息保护法》","n":"权利保护类专项立法"}],"more":"1992年中国加入《保护文学和艺术作品伯尔尼公约》。","exam":[]},{"id":"a15-031","t":"知识产权与专利保护期","cid":"15b","p":2,"kind":"合称","alias":["知识产权","专利保护期","专利权期限"],"one":"含著作权、专利权、商标权；专利期发明20年、实用新型10年、外观15年。","ans":"知识产权是民事主体就**智力成果和商业标志**享有的专有权利，主要包括**著作权、专利权、商标权**，具专有性、地域性与时间性。依现行《专利法》（2021年6月施行），专利权期限**自申请日起算**：**发明20年**、**实用新型10年**、**外观设计15年**（原10年）。注册商标有效期10年可续展，自然人著作权财产权为终生及死后50年。","pts":["三大类：著作权、专利权、商标权","专利期：发明20年、实用新型10年、外观15年","均自申请日起算；2021年起外观设计延至15年"],"mem":"专利数字顺口溜：“发20、实10、外15，全都从申请日算起”。对比易记：实用新型（小发明）最短10年，外观设计居中15年，发明专利最长20年。","mix":"旧题常写外观设计专利保护期为10年，2020年修改《专利法》（2021年6月1日施行）已改为15年；著作权中的署名权、修改权、保护作品完整权不受保护期限制。","members":[["著作权（版权）","作品创作完成即自动产生；自然人财产权保护期为终生及死后50年"],["发明专利权","保护期20年，自申请日起计算"],["实用新型专利权","保护期10年，自申请日起计算"],["外观设计专利权","保护期15年（2021年6月起由10年延长），自申请日起计算"],["商标权","注册商标有效期10年，自核准注册之日起算，期满可无限次续展"]],"mcq":[{"q":"根据我国现行《专利法》，发明、实用新型和外观设计专利权的保护期限依次为","o":["20年、10年、15年","20年、15年、10年","20年、10年、10年","50年、20年、15年"],"a":0,"w":"现行《专利法》第42条规定：发明20年，实用新型10年，外观设计15年，均自申请日起计算。"}],"rel":[{"t":"著作权","n":"与翻译直接相关的知识产权"},{"t":"民法典","n":"总则编规定知识产权客体"},{"t":"《民营经济促进法》","n":"强调加强知识产权保护"}],"more":"2020年10月17日十三届全国人大常委会第二十二次会议第四次修正《专利法》，自2021年6月1日起施行。","exam":[]},{"id":"a15-032","t":"《伯尔尼公约》","cid":"15b","p":3,"kind":"制度","alias":["伯尔尼公约","《保护文学和艺术作品伯尔尼公约》"],"one":"1886年签订的国际版权基础公约，中国1992年加入，涉及翻译版权。","ans":"《伯尔尼公约》全称**《保护文学和艺术作品伯尔尼公约》**，是首部国际著作权多边条约。**1886年**在瑞士签订，确立**国民待遇、自动保护、独立保护**三原则，涵盖**翻译权**。中国**1992年**加入，奠定涉外出版与翻译版权国际基石。","pts":["全称《保护文学和艺术作品伯尔尼公约》，1886年签","确立国民待遇、自动保护、独立保护三原则","中国1992年加入，直接关涉作品翻译权保护"],"mem":"年份巧记：1886年瑞士伯尔尼签版权，1992年双喜临门（中国同年加入《伯尔尼公约》与《不扩散核武器条约》）；三大原则记“国自独”（国民待遇、自动保护、独立保护）。","mix":"《伯尔尼公约》保护文学艺术著作权，由世界知识产权组织管理；保护专利和商标等工业产权的早期国际公约是1883年的《巴黎公约》，切勿混淆。","mcq":[{"q":"关于国际著作权基础条约《伯尔尼公约》，下列说法正确的是","o":["1886年签订，中国于1992年正式加入","主要调整发明专利与商标的国际保护","要求作品必须履行登记手续才受保护","2001年随中国加入世贸组织同步生效"],"a":0,"w":"《伯尔尼公约》1886年签订，实行自动保护原则，中国于1992年正式加入。"}],"rel":[{"t":"著作权","n":"国际版权保护依据"},{"t":"知识产权与专利保护期","n":"知识产权体系对照"},{"t":"《不扩散核武器条约》","n":"中国同于1992年加入"},{"t":"中国加入世贸组织","n":"涉外知识产权规则衔接"}],"exam":[]},{"id":"a15-033","t":"消费者权益保护法“退一赔三”","cid":"15b","p":2,"kind":"制度","alias":["退一赔三","七日无理由退货","消费者权益保护法"],"one":"经营者欺诈应退一赔三（不足500元赔500元）；网购享七日无理由退货。","ans":"“退一赔三”是**《消费者权益保护法》第55条确立的惩罚性赔偿规则**。经营者提供商品或服务有**欺诈行为**的，须返还价款并增加赔偿价款或服务费的**三倍**；增加赔偿**不足五百元的，为五百元**。该法第25条规定，网购等远程购物一般享收货起**七日无理由退货**权，定作、鲜活易腐、拆封数字化商品及报刊除外，有效震慑市场欺诈。","pts":["经营者欺诈须退一赔三，不足500元按500元","网购一般享有收货起七日无理由退货权","定作、鲜活易腐、拆封软件与报刊不适用七日退货"],"mem":"对比记两条惩罚性赔偿线：一般商品欺诈看《消法》“退一赔三、保底五百”；食品安全问题看《食品安全法》“退一赔十、保底一千”。口诀：“消三五百，食十一千”。","mix":"“退一赔三”的前提是经营者存在“欺诈行为”，单纯质量瑕疵不直接适用；七日无理由退货针对网购等远程购物，实体店购物法律并未强制规定七日无理由退货。","mcq":[{"q":"某消费者花80元买到商家故意以假充真的普通日用品，依《消费者权益保护法》可主张退还80元并另行赔偿","o":["240元","500元","800元","1000元"],"a":1,"w":"80元的三倍为240元，不足500元，依《消费者权益保护法》第55条按500元兜底赔偿。"}],"rel":[{"t":"民法典","n":"民事侵权与合同法基础"},{"t":"民法基本原则","n":"诚信原则在消费领域的体现"},{"t":"全国统一大市场","n":"营造公平诚信消费环境"}],"exam":[]},{"id":"a15-034","t":"《民营经济促进法》","cid":"15c","p":2,"kind":"制度","alias":["中华人民共和国民营经济促进法","民营经济促进法"],"one":"2025年4月30日通过、5月20日施行，首部民营经济基础性法律。","ans":"《民营经济促进法》是**我国第一部专门关于民营经济发展的基础性法律**，共**9章78条**。该法**2025年4月30日**经全国人大常委会通过，自**2025年5月20日**起施行。法律将**“两个毫不动摇”**首次写入法律，围绕**公平竞争、投融资促进、科技创新、规范经营、服务保障、权益保护**作系统规定，严禁违规异地与趋利性执法，以法治稳定民企预期。","pts":["2025年4月通过、5月20日施行，9章78条","我国首部专门关于民营经济发展的基础性法律","将“两个毫不动摇”入法，保障公平竞争与权益"],"mem":"巧记施行日：2025年“5·20”（谐音“我爱你”），国家用法治向民营经济“表白”护航。结构记核心六章：公平竞争、投融资、科创、规范经营、服务保障、权益保护。","mix":"《民营经济促进法》由全国人大常委会于2025年4月通过，而非2026年全国人大会议通过；它旨在平等保护民营经济与其他所有制经济共同发展，并非给予特权。","mcq":[{"q":"我国第一部专门关于民营经济发展的基础性法律《民营经济促进法》正式施行于","o":["2025年1月1日","2025年5月20日","2026年1月1日","2026年3月12日"],"a":1,"w":"该法于2025年4月30日通过，自2025年5月20日起施行。"}],"rel":[{"t":"社会主义市场经济体制","n":"本法服务的经济制度"},{"t":"全国统一大市场","n":"保障公平竞争与平等准入"},{"t":"国家发展规划法","n":"同期经济领域新法"}],"more":"主席令第46号公布，9章78条：总则、公平竞争、投资融资促进、科技创新、规范经营、服务保障、权益保护、法律责任、附则。","exam":[]},{"id":"a15-036","t":"《对外关系法》","cid":"15c","p":3,"kind":"制度","alias":["对外关系法"],"one":"2023年7月1日施行，我国首部集中阐述对外工作大政方针的基础法。","ans":"《对外关系法》是我国首部集中阐述**对外工作大政方针**与原则立场的**基础性涉外法律**。**2023年7月1日**起施行，系统规范对外领导体制、职权划分及**反制限制措施**，为统筹推进国内法治与涉外法治、维护国家主权提供根本依据。","pts":["2023年7月1日施行，涉外领域基础性法律","首部集中阐述我国对外工作大政方针的法律","明确对外领导体制、职权与反制措施"],"mem":"记“涉外总纲23·7·1”：2023年7月1日施行，定位为涉外法治领域的“总纲性基础法”，与反外国制裁法等专门法律形成总分衔接。","mix":"《对外关系法》是全面规定对外工作原则与体制的基础性法律，侧重宏观总纲；针对具体单边制裁的反制机制则由2021年施行的《反外国制裁法》细化规范。","mcq":[{"q":"我国第一部集中阐述对外工作大政方针的基础性法律及其施行时间是","o":["《反外国制裁法》，2021年6月","《对外关系法》，2023年7月","《国家安全法》，2015年7月","《爱国主义教育法》，2024年1月"],"a":1,"w":"《对外关系法》于2023年6月28日通过，自2023年7月1日起施行。"}],"rel":[{"t":"《国家安全法》","n":"维护国家主权安全同簇"},{"t":"《立法法》","n":"涉外立法权限衔接"},{"t":"一带一路","n":"高水平对外开放实践"}],"exam":[]},{"id":"a15-037","t":"《爱国主义教育法》","cid":"15c","p":3,"kind":"制度","alias":["爱国主义教育法"],"one":"2024年1月1日施行，以法治方式保障新时代爱国主义教育。","ans":"《爱国主义教育法》是保障新时代**爱国主义教育**的基础性专项法律。2023年10月通过，自**2024年1月1日**起施行，涵盖思想政治、历史文化、国家象征与国防安全等内容，明确**学校、家庭、社会**职责，以法治方式传承弘扬爱国主义精神。","pts":["2023年10月通过，2024年1月1日起施行","规定爱国主义教育主要内容与各方职责","以法治方式推动爱国主义精神传承弘扬"],"mem":"新年第一法：2024年元旦（1月1日）正式施行；记忆三场域“校、家、社”，把爱国主义教育从道德倡议上升为法律制度保障。","mix":"《爱国主义教育法》2024年1月1日施行，旨在全面开展爱国主义教育；《英雄烈士保护法》2018年5月1日施行，侧重保护英烈名誉荣誉与纪念设施。","mcq":[{"q":"《中华人民共和国爱国主义教育法》正式施行的日期是","o":["2023年7月1日","2023年10月1日","2024年1月1日","2025年1月1日"],"a":2,"w":"该法于2023年10月24日经十四届全国人大常委会第六次会议通过，自2024年1月1日起施行。"}],"rel":[{"t":"《英雄烈士保护法》","n":"弘扬爱国精神同簇"},{"t":"社会主义核心价值观","n":"爱国为核心价值要求"},{"t":"全民国防教育日","n":"国防与爱国教育联动"},{"t":"中国共产党人精神谱系","n":"爱国主义教育重要内容"}],"exam":[]},{"id":"a15-038","t":"《环境保护法》","cid":"15c","p":3,"kind":"制度","alias":["环保法","“史上最严”环保法"],"one":"1989年施行、2014年大修的环保基础法，2026年编入《生态环境法典》。","ans":"《环境保护法》曾是我国环保**基础性综合法律**，**1989年**施行。**2014年修订**版引入按日计罚与公益诉讼，被称为**“史上最严”环保法**。**2026年8月15日**《生态环境法典》施行，原法等10部单行法同步废止编入法典。","pts":["1989年施行，2014年修订称“史上最严”环保法","引入按日计罚与环境公益诉讼等核心机制","2026年8月15日随《生态环境法典》施行编入法典"],"mem":"三节点连线：“89立法、14大修（15施行）、26入典”，2026年8月15日全国生态日《生态环境法典》施行，《环境保护法》完成历史使命并升级入典。","mix":"《生态环境法典》是新中国第二部以“法典”命名的法律（第一部为《民法典》），2026年8月15日施行后，《环境保护法》等10部单行法同步废止而非并行。","mcq":[{"q":"2014年修订、被称为“史上最严”的《环境保护法》在2026年的最新立法变动是","o":["随《生态环境法典》施行同步废止并编入法典","更名为《生态文明建设促进法》继续单行","仅保留总则部分并降格为行政法规","与《大气污染防治法》合并为单行法"],"a":0,"w":"2026年8月15日《生态环境法典》正式施行，原《环境保护法》等10部单行法同步废止并整合入典。"}],"rel":[{"t":"生态环境法典","n":"2026年升级编入法典"},{"t":"生态环境法典五编","n":"法典体系结构承接"},{"t":"全国生态日","n":"8月15日法典施行日"},{"t":"“绿水青山就是金山银山”","n":"生态文明核心理念"}],"exam":[]},{"id":"a15-039","t":"《反家庭暴力法》","cid":"15c","p":3,"kind":"制度","alias":["反家庭暴力法","反家暴法","人身安全保护令"],"one":"2016年3月1日施行，我国首部反家暴专门法，设立人身安全保护令。","ans":"《反家庭暴力法》是我国首部预防和制止家暴的**专门法律**，属婚姻家庭保障立法。**2016年3月1日**施行，将**身体与精神侵害**及共同生活者均纳入规制，设立**人身安全保护令**、告诫书和强制报告制度，推动公权力依法介入家暴维权。","pts":["2016年3月1日施行，我国首部反家暴专门法","涵括身体与精神侵害，保护共同生活人员","设立人身安全保护令、告诫书、强制报告制度"],"mem":"日子与三件法宝：2016年“三八妇女节”前一周的3月1日施行；维权三件法宝记“保、告、报”（法院发人身安全保护令、公安发告诫书、学校医院等负强制报告义务）。","mix":"人身安全保护令由受害人向人民法院申请人身安全保护裁定，无需以提起离婚诉讼为前提；家庭成员以外共同生活的人（如同居伴侣）之间实施暴力也参照适用该法。","mcq":[{"q":"2016年3月1日施行的《反家庭暴力法》创设的核心司法保护制度是","o":["离婚冷静期制度","婚姻撤销登记制度","公益诉讼起诉制度","人身安全保护令制度"],"a":3,"w":"《反家庭暴力法》设立人身安全保护令制度，当事人遭受家暴或面临现实危险可向法院申请。"}],"rel":[{"t":"民法典","n":"婚姻家庭编配套保护"},{"t":"无效婚姻","n":"婚姻家庭规则同簇"},{"t":"可撤销婚姻","n":"婚姻家庭规则同簇"}],"exam":[]},{"id":"a15-040","t":"《英雄烈士保护法》","cid":"15c","p":3,"kind":"制度","alias":["英雄烈士保护法","英烈保护法"],"one":"2018年5月1日施行，以法律明定烈士纪念日并保护英烈名誉荣誉。","ans":"《英雄烈士保护法》是专门保护英烈名誉、荣誉与纪念设施的**专项法律**。**2018年5月1日**施行，法定每年**9月30日**为**烈士纪念日**，严禁歪曲丑化英烈事迹，并确立检察机关提起**民事公益诉讼**机制，以刚性法治捍卫民族记忆。","pts":["2018年5月1日施行，专门保护英烈权益","法定每年9月30日为烈士纪念日","禁止诋毁英烈，确立检察民事公益诉讼"],"mem":"两个日期绑定：“五一劳动节（2018年5月1日）施行英烈法，国庆前一天（9月30日）是烈士纪念日”，因为1949年9月30日人民英雄纪念碑奠基。","mix":"烈士纪念日早在2014年8月即由全国人大常委会决定设立，2018年《英雄烈士保护法》第五条将其以专门法形式固化；另勿与12月13日南京大屠杀死难者国家公祭日混淆。","mcq":[{"q":"2018年5月1日施行的《英雄烈士保护法》以专门法律形式确定的“烈士纪念日”是每年","o":["9月3日","9月30日","12月13日","8月15日"],"a":1,"w":"每年9月30日为烈士纪念日，9月3日为抗战胜利纪念日，12月13日为国家公祭日。"}],"rel":[{"t":"国家纪念日","n":"9月30日烈士纪念日"},{"t":"《爱国主义教育法》","n":"弘扬英烈精神同簇"},{"t":"2025年九三阅兵","n":"铭记抗战英烈呼应"}],"exam":[]},{"id":"a15-041","t":"大陆法系","cid":"15d","p":1,"kind":"制度","alias":["民法法系","罗马法系","成文法系","大陆法"],"one":"以罗马法为源头、成文法典为主要渊源的法系，法德日为代表。","ans":"大陆法系又称民法法系、罗马法系，是**以古罗马法为源头、以成文法典为主要法律渊源的法系**，形成于欧洲大陆。它以**1804年《法国民法典》（《拿破仑法典》）和1900年施行的《德国民法典》为代表**，法国、德国、意大利、日本等国属于此系。其特点是法律分门别类编成系统的法典，法官主要依据成文法裁判，判例不是正式的法律渊源。大陆法系与**以判例法为特征的英美法系**并称世界两大法系，近代以来中国的法律制度也深受其影响。","pts":["源于罗马法，成文法典为主","《法国民法典》1804，《德国民法典》1900","与判例法的英美法系并称"],"mem":"“大陆=法典，英美=判例”：大陆法系的人翻法典，英美法系的人翻案例。人物挂钩：罗马法（优士丁尼《民法大全》）→拿破仑法典（1804）→德国民法典（1900），一条线传下来。国家：“法德日”三个字。","mix":"大陆法系又叫民法法系，因其核心是民法典；英美法系叫普通法系、判例法系；中华法系是中国古代法律体系，以《唐律疏议》为代表，是历史上的法系，与这两个现代两大法系不同。","mcq":[{"q":"下列国家中，属于大陆法系的是","o":["英国","美国","德国","澳大利亚"],"a":2,"w":"德国属大陆法系，英、美、澳属英美法系。"},{"q":"大陆法系的主要法律渊源是","o":["判例","成文法典","习惯","宗教经典"],"a":1,"w":"大陆法系以成文法典为主要渊源，英美法系以判例为重要渊源。"}],"rel":[{"t":"英美法系","n":"两大法系对举"},{"t":"罗马法与《民法大全》","n":"大陆法系的源头"},{"t":"《拿破仑法典》","n":"代表性法典"},{"t":"中华法系与《唐律疏议》","n":"中国古代法系"}],"exam":[]},{"id":"a15-042","t":"英美法系","cid":"15d","p":1,"kind":"制度","alias":["普通法系","判例法系","普通法","海洋法系"],"one":"以英国普通法为基础、以判例为重要渊源的法系，遵循先例。","ans":"英美法系又称普通法系、判例法系，是**以英国普通法为基础、以判例为重要法律渊源的法系**，起源于中世纪的英国，英国、美国、加拿大（魁北克除外）、澳大利亚、印度等国属于此系。其核心是**遵循先例原则**，上级法院的判例对以后案件有约束力，法官的判决可以创造法律；审判中重视陪审团和当事人对抗。它与**以成文法典为主的大陆法系**并称世界两大法系，美国虽有成文宪法，仍属英美法系。","pts":["以英国普通法为基础，判例法","遵循先例原则","英国、美国等；与大陆法系对举"],"mem":"“英美=判例”：英国发源，美国继承，共同点是先例有约束力（遵循先例，拉丁语 stare decisis）。画面：法官翻过去的案卷找依据，而大陆法系的法官翻法典。国家挂钩：“英美加澳印”。","mix":"美国有成文宪法和联邦成文法，但整体仍属英美法系；加拿大魁北克省、美国路易斯安那州保留了大陆法传统；英美法系不是“只有判例没有成文法”，而是判例处于重要地位。","mcq":[{"q":"英美法系最重要的特征是","o":["以成文法典为唯一渊源","遵循先例的判例法","法官不得解释法律","以宗教法为基础"],"a":1,"w":"英美法系以判例为重要渊源，实行遵循先例原则。"},{"q":"下列属于英美法系的国家是","o":["法国","德国","日本","美国"],"a":3,"w":"美国属英美法系；法、德、日属大陆法系。"}],"rel":[{"t":"大陆法系","n":"两大法系对举"},{"t":"美国最高法院","n":"判例法的典型机构"},{"t":"《权利法案》（英国）","n":"英国宪法性文件"},{"t":"英国议会的起源","n":"英国法治传统"}],"exam":[]},{"id":"a15-043","t":"中华法系与《唐律疏议》","cid":"15d","p":2,"kind":"制度","alias":["中华法系","《唐律疏议》","《永徽律疏》"],"one":"中华法系礼法结合，《唐律疏议》是现存最早最完整的封建成文法典。","ans":"中华法系是**世界五大法系之一**，以中国古代法为主体，特征为**儒家指导、礼法结合**、诸法合体。其代表是唐高宗永徽四年（653年）**长孙无忌**等编纂的**《唐律疏议》**（原名《永徽律疏》），全书**12篇502条**，主张“德礼为政教之本，刑罚为政教之用”。它是我国**现存最早、最完整的封建成文法典**，影响宋元明清立法及日本《大宝律令》等东亚法典。","pts":["中华法系特征：儒家指导、礼法结合、诸法合体","《唐律疏议》（长孙无忌，653年）12篇502条","现存最早最完整封建成文法典，影响东亚"],"mem":"记“三最一主线”：《法经》是中国第一部系统封建成文法典（已佚），《唐律疏议》是“现存最早、最完整”的封建成文法典；“礼法结合”一以贯之（德礼为本，刑罚为用）。","mix":"《法经》（战国李悝）是中国历史上第一部比较系统的成文法典，但早已亡佚；现存最早且完整保留至今的是唐代《唐律疏议》，别把两者“第一”说混。","mcq":[{"q":"被公认为中华法系代表作、我国现存最早最完整的封建成文法典是","o":["《唐律疏议》","《法经》","《大明律》","《宋刑统》"],"a":0,"w":"《唐律疏议》（《永徽律疏》）是现存最早、最完整的封建成文法典，代表中华法系最高成就；《法经》已失传。"}],"rel":[{"t":"《法经》","n":"中国古代最早成文法典"},{"t":"大陆法系","n":"世界主要法系对照"},{"t":"英美法系","n":"世界主要法系对照"},{"t":"罗马法与《民法大全》","n":"中西古代法典双璧"},{"t":"外儒内法（霸王道杂之）","n":"礼法结合的思想源头"}],"more":"名句：德礼为政教之本，刑罚为政教之用，犹昏晓阳秋相须而成者也。｜《唐律疏议·名例律》","exam":[]},{"id":"a15-044","t":"《法经》","cid":"15d","p":2,"kind":"作品","alias":["法经","李悝法经"],"one":"战国魏国李悝编撰，中国第一部较系统的封建成文法典。","ans":"《法经》是**战国时期魏国李悝**编撰的法典，为**中国历史上第一部比较系统的封建成文法典**。它是先秦法家立法的代表，汇总了春秋以来各国成文法经验。全书共**六篇**：《盗法》《贼法》《囚法》《捕法》《杂法》《具法》，以惩治盗贼居首，以总则性质的《具法》殿后。**商鞅据此入秦改法为律**，汉代萧何扩充为《九章律》，奠定了中国古代以刑为主的法典框架。","pts":["战国魏国李悝编撰，首部系统封建成文法典","共六篇：盗、贼、囚、捕、杂、具","商鞅据此改法为律，萧何扩为《九章律》"],"mem":"六篇口诀：**“盗贼囚捕，杂具殿后”**。按办案流程走：先有“盗”（侵财）和“贼”（杀伤谋反），接着“囚”（审讯关押）和“捕”（追捕），其余归“杂”，量刑总则叫“具”。传授链：李悝《法经》→商鞅改法为律→汉代《九章律》。","mix":"春秋郑国子产“铸刑书”是最早公布成文法，但第一部比较系统的封建成文法典是战国李悝《法经》；现存最早、最完整的封建法典则是唐代《唐律疏议》。","mcq":[{"q":"中国历史上第一部比较系统的封建成文法典《法经》的编撰者是","o":["子产","商鞅","李悝","萧何"],"a":2,"w":"战国魏国李悝编撰《法经》；商鞅携之入秦改法为律，萧何在汉初扩为《九章律》。"}],"rel":[{"t":"商鞅变法","n":"据《法经》改法为律"},{"t":"中华法系与《唐律疏议》","n":"一脉相承的法典体系"},{"t":"法家","n":"成文法典的思想源流"},{"t":"罗马法与《十二铜表法》","n":"中西早期成文法对照"}],"more":"六篇：《盗法》《贼法》（实体）、《囚法》又称《网法》与《捕法》（程序）、《杂法》（其他犯罪）、《具法》（总则）。","exam":[]},{"id":"a15-046","t":"罗马法与《十二铜表法》","cid":"15d","p":2,"kind":"作品","alias":["十二铜表法","罗马法","民法大全","国法大全"],"one":"古罗马法律体系，以《十二铜表法》为成文法开端，《民法大全》集大成。","ans":"罗马法指**古罗马共和国至帝国时期的法律总称**，是**现代大陆法系的源头**。约公元前450年颁布的**《十二铜表法》**刻于十二块铜牌，是**古罗马第一部成文法**，限制了贵族对习惯法的任意解释。公元6世纪，东罗马皇帝**查士丁尼一世**主持编纂**《民法大全》**，含《查士丁尼法典》《学说汇纂》《法学阶梯》《新律》。罗马法深远影响了近代欧洲与现代民法。","pts":["《十二铜表法》约前450年制定，罗马首部成文法","东罗马查士丁尼主持编纂《民法大全》四部分","大陆法系源头，深远影响欧洲与现代民法"],"mem":"时间双锚：前450年《十二铜表法》起头（刻铜牌防贵族随意解释），公元6世纪查士丁尼《民法大全》集大成。《民法大全》四部分记口诀：**“法典、汇纂、阶梯、新律”**。","mix":"世界现存最早较完整成文法典是古巴比伦《汉谟拉比法典》，《十二铜表法》是古罗马第一部成文法；罗马法是大陆法系源头，英美法系以英国普通法和判例法为基础。","mcq":[{"q":"关于罗马法的发展历程，下列说法正确的是","o":["《十二铜表法》是古罗马第一部成文法","《民法大全》由西罗马皇帝查士丁尼主持编纂","罗马法是现代英美法系的直接源头","《十二铜表法》颁布于罗马帝国全盛时期"],"a":0,"w":"《十二铜表法》约前450年颁布于罗马共和国时期；查士丁尼是东罗马皇帝；罗马法是大陆法系源头。"}],"rel":[{"t":"大陆法系","n":"以罗马法为历史源头"},{"t":"《拿破仑法典》","n":"近代继承罗马法传统"},{"t":"《汉谟拉比法典》","n":"更早的古巴比伦成文法"},{"t":"《法经》","n":"中西早期成文法对照"}],"more":"《民法大全》（又称《国法大全》，Corpus Juris Civilis）四部分：《查士丁尼法典》《学说汇纂》《法学阶梯》《新律》。","exam":[]},{"id":"a15-047","t":"刑法三大基本原则","cid":"15d","p":1,"kind":"合称","alias":["刑法基本原则","罪刑法定原则","罪责刑相适应","适用刑法人人平等"],"one":"罪刑法定、适用刑法人人平等、罪责刑相适应三项原则。","ans":"刑法三大基本原则指**罪刑法定原则、适用刑法人人平等原则、罪责刑相适应原则**，规定在《刑法》第3条至第5条。现行刑法**1979年制定、1997年全面修订**，1997年修订时正式确立罪刑法定。**罪刑法定**即法律明文规定为犯罪的才定罪处刑，**法无明文规定不为罪、不处罚**；**适用刑法人人平等**指对任何人犯罪，在适用法律上一律平等；**罪责刑相适应**指刑罚的轻重应与犯罪的社会危害性和刑事责任相适应。三原则共同保障公民权利，防止刑罚滥用。","pts":["罪刑法定：法无明文规定不为罪","适用刑法人人平等","罪责刑相适应；1997年修订确立"],"members":[["罪刑法定原则","法无明文规定不为罪、不处罚（第3条）"],["适用刑法人人平等原则","对任何人犯罪一律平等适用（第4条）"],["罪责刑相适应原则","罪行、责任与刑罚相称（第5条）"]],"mem":"条文序号 3、4、5 与原则顺序对应：3 罪刑法定，4 人人平等，5 罪责刑相适应。简称“定、等、适”。罪刑法定的拉丁格言“法无明文规定不为罪”，用一句话记住：没有法律写着，就不能治你的罪。","mix":"罪刑法定的反面是“类推定罪”，1979年刑法允许类推，1997年修订后废除；“罪责刑相适应”是三个字加“相适应”，不要写成“罪刑相适应”；平等原则指适用法律平等，不是量刑结果相同。","mcq":[{"q":"“法无明文规定不为罪、不处罚”体现的刑法原则是","o":["罪刑法定原则","罪责刑相适应原则","适用刑法人人平等原则","从旧兼从轻原则"],"a":0,"w":"这是罪刑法定原则的经典表述。"},{"q":"我国现行刑法的制定与修订年份是","o":["1949年制定，1982年修订","1979年制定，1997年修订","1954年制定，1979年修订","1997年制定，2020年修订"],"a":1,"w":"刑法1979年制定，1997年全面修订，此后以修正案方式修改。"}],"rel":[{"t":"刑罚种类","n":"原则指导刑罚适用"},{"t":"刑事责任年龄","n":"刑事责任的前提"},{"t":"古代五刑","n":"古代刑罚对照"},{"t":"法治与法制","n":"法治原则"}],"exam":[]},{"id":"a15-048","t":"刑罚种类","cid":"15d","p":1,"kind":"合称","alias":["主刑","附加刑","五种主刑","三种附加刑"],"one":"主刑五种（管制至死刑），附加刑三种（罚金、剥夺政治权利、没收财产）。","ans":"刑罚种类指《刑法》规定的刑罚体系，分为**主刑和附加刑**。**主刑有五种：管制、拘役、有期徒刑、无期徒刑、死刑**，按轻重排列，只能单独适用，不能附加。**附加刑有三种：罚金、剥夺政治权利、没收财产**，既可独立适用，也可附加主刑适用；另有**驱逐出境**，对犯罪的外国人可独立或附加适用。死刑分立即执行和缓期二年执行两种。这一体系体现罪责刑相适应，轻重有序、主附配合。","pts":["主刑五种：管拘有无死","附加刑：罚金、剥政、没财产","主刑不能附加，附加刑可独立"],"members":[["管制","主刑，限制自由但不羁押"],["拘役","主刑，短期剥夺自由"],["有期徒刑","主刑，六个月以上十五年以下"],["无期徒刑","主刑，终身剥夺自由"],["死刑","主刑，立即执行或缓期二年执行"],["罚金","附加刑，缴纳金钱"],["剥夺政治权利","附加刑"],["没收财产","附加刑"]],"mem":"口诀“管拘有无死，罚剥没（驱）”：前五个是主刑，由轻到重；后三个是附加刑，罚金、剥夺政治权利、没收财产，驱逐出境只对外国人。数轻重画面：管（不关）、拘（关短）、有（关定期）、无（关一生）、死。","mix":"数罪中如判有期徒刑或拘役并判管制，前者执行完毕后仍须执行管制，附加刑可与主刑并用；罚金是附加刑，不是主刑；驱逐出境只适用于犯罪的外国人；“没收财产”与“罚金”不同，前者没收个人财产的一部分或全部，后者是缴纳一定数额金钱。","mcq":[{"q":"下列刑罚中，属于附加刑的是","o":["管制","拘役","剥夺政治权利","无期徒刑"],"a":2,"w":"剥夺政治权利是附加刑，管制、拘役、无期徒刑属于主刑。"},{"q":"下列刑罚中，不属于主刑的是","o":["罚金","管制","死刑","拘役"],"a":0,"w":"罚金是附加刑；主刑为管制、拘役、有期徒刑、无期徒刑、死刑。"}],"rel":[{"t":"刑法三大基本原则","n":"罪责刑相适应"},{"t":"古代五刑","n":"古今刑罚对照"},{"t":"刑事责任年龄","n":"刑法基础概念"},{"t":"三大诉讼","n":"刑事诉讼适用刑罚"}],"exam":[]},{"id":"a15-049","t":"刑事责任年龄","cid":"15d","p":1,"kind":"制度","alias":["刑事责任年龄划分","负刑事责任年龄","刑责年龄"],"one":"16岁完全负责，14至16岁八种罪负责，12至14岁特定情形核准追诉。","ans":"刑事责任年龄是**法律规定的行为人对犯罪应当负刑事责任的年龄界限**。《刑法》规定：**已满16周岁**的人犯罪，应当负刑事责任；**已满14不满16周岁**的人，只对**故意杀人、故意伤害致人重伤或死亡、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质**八种犯罪负责。**2020年刑法修正案（十一）**规定，**已满12不满14周岁**的人犯故意杀人、故意伤害罪致人死亡或以特别残忍手段致人重伤造成严重残疾，情节恶劣的，**经最高人民检察院核准追诉**，应负刑事责任。","pts":["16周岁完全负责；14至16周岁八种罪","12至14周岁：杀人、伤害致死等，最高检核准","2020年刑法修正案（十一）新增"],"mem":"三档数字“16、14、12”：十六全责，十四八罪，十二核准。八种罪口诀“杀伤强抢，毒放爆投”：故意杀人、故意伤害（致重伤或死亡）、强奸、抢劫、贩卖毒品、放火、爆炸、投放危险物质。","mix":"12至14周岁只涉及故意杀人和故意伤害两罪，且须最高检核准；14至16周岁是八种罪，不是所有罪；不满18周岁的人不适用死刑；对依《刑法》第17条追究刑责的不满18周岁者，应当从轻或者减轻处罚。","mcq":[{"q":"根据刑法，已满14不满16周岁的人应负刑事责任的犯罪是","o":["盗窃","诈骗","抢劫","寻衅滋事"],"a":2,"w":"抢劫属于八种犯罪之一；盗窃、诈骗、寻衅滋事不在其列。"},{"q":"2020年刑法修正案（十一）规定，已满多少周岁不满14周岁的人在特定情形下经最高检核准可追诉","o":["10周岁","11周岁","12周岁","13周岁"],"a":2,"w":"已满12不满14周岁，犯故意杀人、故意伤害致死等并经最高检核准，应负刑事责任。"}],"rel":[{"t":"刑法三大基本原则","n":"刑法基本框架"},{"t":"刑罚种类","n":"责任之后的刑罚"},{"t":"法定婚龄与民事行为能力","n":"年龄界限的民事对照"},{"t":"《未成年人网络保护条例》","n":"未成年人保护相关"}],"more":"刑法修正案（十一）2020年12月通过，2021年3月1日施行。","exam":[]},{"id":"a15-050","t":"正当防卫与紧急避险","cid":"15d","p":2,"kind":"制度","alias":["正当防卫","紧急避险","无限防卫","特殊防卫"],"one":"我国刑法两项免责事由：反击不法侵害与避险损小保大。","ans":"正当防卫与紧急避险是我国**《刑法》第20条、第21条**规定的免责制度。**正当防卫**针对正在进行的不法侵害；对正在进行**行凶、杀人、抢劫、强奸、绑架**等严重暴力犯罪可**无限防卫**，致伤亡不负刑责。**紧急避险**针对正在发生的危险，不得已损害较小合法权益，避免本人危险不适用于特定职责人员。二者体现法不能向不法让步与损小保大。","pts":["正当防卫针对正在进行的不法侵害人本人","行凶、杀人、抢劫、强奸、绑架等适用无限防卫","紧急避险损小保大，特定职责者不得避本人险"],"mem":"对比记：正当防卫是**“正对不正”**（打坏人），紧急避险是**“正对正”**（迫不得已牺牲无辜小利益保大利益，如躲车撞坏路边摊）。无限防卫五类犯罪记口诀：**“行杀抢强绑”**。","mix":"防卫过当与避险过当均应负刑责，但应当减轻或者免除处罚；消防员、警察、船长等职务或业务上负有特定责任的人，不能为避免本人危险实行紧急避险。","mcq":[{"q":"关于我国《刑法》中的正当防卫与紧急避险，下列说法错误的是","o":["正当防卫必须针对正在进行的不法侵害","对正在进行的绑架犯罪采取防卫造成伤亡的不属防卫过当","紧急避险造成的损害必须小于所保护的合法权益","消防员救火时可为避免本人危险实行紧急避险"],"a":3,"w":"《刑法》第21条规定，关于避免本人危险的规定，不适用于职务上、业务上负有特定责任的人。"}],"rel":[{"t":"刑法三大基本原则","n":"同属刑法总则基础"},{"t":"刑罚种类","n":"刑法体系近邻"},{"t":"刑事责任年龄","n":"同属犯罪成立与免责要件"}],"more":"过当处罚：防卫过当、避险过当均应当负刑事责任，但是应当减轻或者免除处罚。","exam":[]},{"id":"a15-051","t":"三大诉讼","cid":"15d","p":1,"kind":"合称","alias":["民事诉讼","刑事诉讼","行政诉讼","诉讼三类","民告官"],"one":"民事、刑事、行政三类诉讼，行政诉讼俗称“民告官”。","ans":"三大诉讼指**民事诉讼、刑事诉讼和行政诉讼**，是我国人民法院审理案件的三种基本程序，分别由《民事诉讼法》《刑事诉讼法》《行政诉讼法》规范。**民事诉讼解决平等主体间的人身、财产纠纷**；**刑事诉讼由公安机关侦查、检察院公诉、法院审判，追究犯罪**；**行政诉讼俗称“民告官”**，公民、法人或其他组织认为行政机关或法定授权组织的行政行为侵犯其合法权益时，可依法起诉，《行政诉讼法》1989年通过、1990年10月1日施行。我国一般实行**两审终审制**，符合条件的小额诉讼案件一审终审。","pts":["民事、刑事、行政三类","行政诉讼是“民告官”，1990年10月1日施行","两审终审制"],"members":[["民事诉讼","平等主体间的人身、财产纠纷，《民事诉讼法》"],["刑事诉讼","追究犯罪，公安侦查、检察院公诉、法院审判"],["行政诉讼","公民法人告行政机关，“民告官”，1990年施行"]],"mem":"“民、刑、行”三个字，对应“民与民”“国家与犯罪人”“民与官”。行政诉讼四字：民告官，被告通常是行政机关，也可以是法定授权组织。两审终审可配画面：一审不服上诉，二审判决后就是终审，小额诉讼等依法一审终审。","mix":"行政诉讼的被告可以是行政机关或法定授权组织；刑事诉讼中检察院代表国家公诉；我国一般实行两审终审，小额诉讼等有法定例外；仲裁和调解不属于三大诉讼。","mcq":[{"q":"俗称“民告官”的诉讼类型是","o":["民事诉讼","刑事诉讼","行政诉讼","仲裁"],"a":2,"w":"行政诉讼是公民、法人起诉行政机关，俗称“民告官”。"},{"q":"我国人民法院审判案件一般实行","o":["一审终审制","两审终审制","三审终审制","四级二审制与三审并用"],"a":1,"w":"一般实行两审终审，符合条件的小额诉讼案件一审终审。"}],"rel":[{"t":"公检法的分工","n":"诉讼主体的职责"},{"t":"最高人民法院与最高人民检察院","n":"两院的职能"},{"t":"《监察法》","n":"监察与诉讼衔接"},{"t":"美国最高法院","n":"英美司法对照"}],"more":"《刑事诉讼法》1979年通过，《民事诉讼法》1991年通过，《行政诉讼法》1989年通过、1990年10月1日施行。","exam":[]},{"id":"a15-052","t":"两审终审制","cid":"15d","p":2,"kind":"制度","alias":["两审终审","审级制度"],"one":"我国诉讼基本审级制度：案件经两级法院审判即告终结。","ans":"两审终审制是我国**三大诉讼共同实行的基本审级制度**。一个案件经**两级人民法院审判**即告终结，当事人不服地方各级法院一审裁判，可依法向上一级法院上诉，二审裁判即为终审生效裁判。例外情形包括：**最高人民法院一审案件**实行**一审终审**；**死刑案件**另有**死刑复核程序**，由最高人民法院统一核准。它兼顾诉讼效率与上级纠错监督，并配以再审程序保障公正。","pts":["三大诉讼基本制度：经两级法院审判即终结","最高人民法院审理的一审案件实行一审终审","死刑案件另有死刑复核程序，由最高法核准"],"mem":"逻辑链：我国法院分四级（基层、中级、高级、最高），打官司走“两级”就停（一审+二审），省时又能纠错。例外记“一顶一重”：顶头最高法一审终审；最重的死刑多加最高法死刑复核。","mix":"二审终审后发现确有错误仍可通过审判监督程序（再审）纠错；自2007年1月1日起，全国死刑案件核准权统一收归最高人民法院行使。","mcq":[{"q":"关于我国的两审终审制，下列说法正确的是","o":["所有刑事案件都必须经过两级法院审理才能生效","最高人民法院审理的第一审案件实行一审终审","中级法院判处死刑后经高级法院二审即可直接执行","两审终审制仅适用于刑事诉讼和民事诉讼"],"a":1,"w":"最高法一审案件一审终审；死刑案件须报最高法核准；三大诉讼均实行两审终审制。"}],"rel":[{"t":"三大诉讼","n":"共同适用两审终审制"},{"t":"最高人民法院与最高人民检察院","n":"最高法一审终审与死刑核准"},{"t":"公检法的分工","n":"同属诉讼制度核心"}],"more":"关键年份：2007年1月1日起，全国死刑案件核准权统一收归最高人民法院行使。","exam":[]},{"id":"a15-053","t":"公检法的分工","cid":"15d","p":2,"kind":"制度","alias":["公检法三机关","分工负责互相配合互相制约"],"one":"公安侦查、检察批捕公诉监督、法院审判，分工配合制约。","ans":"公检法的分工是我国**《宪法》第140条和《刑事诉讼法》第7条**确立的司法原则。办理刑事案件时，**公安机关**负责侦查、拘留、执行逮捕和预审；**人民检察院**负责检察、批准逮捕、提起公诉和法律监督；**人民法院**负责审判。三机关实行**“分工负责，互相配合，互相制约”**。这一机制明晰权力边界，依次把守侦查、起诉与审判关口，有效防止冤错案。","pts":["公安侦查与执行逮捕，检察批捕公诉监督，法院审判","原则：分工负责、互相配合、互相制约","宪法第140条与刑诉法第7条确立，防冤假错案"],"mem":"流水线画面：**公安“查和抓”（侦查、执行逮捕）→检察“批和告”（批捕、公诉、监督）→法院“审和判”（审判）**。盯紧“逮捕”两字：检察院“批”，公安“抓”。","mix":"公安机关属于行政机关，只有检察院和法院属于司法机关；逮捕权分工最常考：检察院批准逮捕（或法院决定逮捕），公安机关执行逮捕。","mcq":[{"q":"在我国刑事诉讼中，有权批准逮捕并提起公诉的机关是","o":["公安机关","人民法院","人民检察院","国家监察委员会"],"a":2,"w":"人民检察院负责批准逮捕、提起公诉和法律监督；公安机关负责侦查和执行逮捕；法院负责审判。"}],"rel":[{"t":"宪法规定的国家机构","n":"公检法的宪法定位"},{"t":"最高人民法院与最高人民检察院","n":"审判与检察最高机关"},{"t":"两审终审制","n":"法院审判的审级规则"},{"t":"疑罪从无与无罪推定","n":"同属刑事诉讼核心原则"}],"more":"法律条文：《宪法》第140条与《刑事诉讼法》第7条均规定：公检法办理刑事案件应当分工负责，互相配合，互相制约。","exam":[]},{"id":"a15-054","t":"疑罪从无与无罪推定","cid":"15d","p":2,"kind":"概念","alias":["疑罪从无","无罪推定"],"one":"未经法院依法判决不得确定有罪，证据不足应判无罪。","ans":"疑罪从无与无罪推定是现代**刑事诉讼核心原则**。我国**《刑事诉讼法》第12条**规定：**“未经人民法院依法判决，对任何人都不得确定有罪。”**定罪权专属于法院。审理中若**证据不足、不能认定被告人有罪**，法院应当作出证据不足、指控犯罪不能成立的**无罪判决**，即“疑罪从无”。该原则摒弃“疑罪从有”“疑罪从轻”旧观，是保障人权与防范冤错案的底线。","pts":["刑诉法第12条：未经法院依法判决不得确定有罪","证据不足、不能认定有罪的，作出无罪判决","定罪权专属法院，取代疑罪从有与疑罪从轻"],"mem":"两句话对两个词：**判前算无罪**（无罪推定，刑诉法第12条）+ **存疑判无罪**（疑罪从无，证据不足宣告无罪）。称呼跟着阶段变：侦查起诉叫“犯罪嫌疑人”，进法院叫“被告人”，判了才叫“罪犯”。","mix":"检察院起诉书只能指控犯罪，不能确定有罪，定罪权专属于法院；证据不足时法院必须作出无罪判决，不能作出“疑罪从轻”判决。","mcq":[{"q":"根据我国《刑事诉讼法》关于“疑罪从无”原则的规定，案件经审理证据不足、不能认定被告人有罪的，人民法院应当","o":["作出证据不足、指控犯罪不能成立的无罪判决","作出疑罪从轻的减轻处罚判决","无限期中止审理等待新证据","交由公安机关直接作出有罪认定"],"a":0,"w":"依“疑罪从无”原则，证据不足、不能认定被告人有罪的，法院应作出无罪判决。"}],"rel":[{"t":"公检法的分工","n":"定罪权专属于人民法院"},{"t":"两审终审制","n":"同属刑事诉讼基本制度"},{"t":"刑法三大基本原则","n":"罪刑法定与无罪推定呼应"}],"more":"法律条文：《刑事诉讼法》第12条确立未经法院依法判决不得确定有罪；第200条规范一审有罪与无罪判决类型。","exam":[]},{"id":"a15-055","t":"仲裁","cid":"15d","p":3,"kind":"制度","alias":["商事仲裁","一裁终局"],"one":"当事人依协议将争议交仲裁机构裁决，实行一裁终局的解纷制度。","ans":"仲裁是独立于法院诉讼的**非诉纠纷解决制度**。平等主体依自愿**仲裁协议**将合同或财产权益争议交仲裁机构裁决，实行**一裁终局**，裁决生效后不得再申裁或起诉。新修订**《仲裁法》**于**2026年3月1日**施行，完善在线与涉外仲裁规则。","pts":["依双方自愿仲裁协议交仲裁机构裁决","实行一裁终局，与诉讼两审终审相对","新修订《仲裁法》2026年3月1日施行"],"mem":"与诉讼对比记：“诉讼两审终审、讲级别管辖；仲裁一裁终局、无级别管辖，且必须先有仲裁协议”。三类不仲裁口诀：“家事不裁、行政不裁”（婚姻收养监护继承和行政争议不适用）。","mix":"商事仲裁适用《仲裁法》，实行或裁或审、一裁终局；劳动争议仲裁适用《劳动争议调解仲裁法》，实行“先裁后审”，不服劳动仲裁大多可向法院起诉，二者不可混同。","mcq":[{"q":"根据我国《仲裁法》，关于商事仲裁基本原则与受案范围的说法正确的是","o":["实行一裁终局制，裁决作出后不得再就同一纠纷起诉","与民事诉讼一样实行两审终审制","离婚与遗产继承纠纷可依协议提交仲裁","当事人无需仲裁协议即可单方申请仲裁"],"a":0,"w":"仲裁须以自愿仲裁协议为前提，实行一裁终局；婚姻、继承等身份纠纷及行政争议不得仲裁。"}],"rel":[{"t":"两审终审制","n":"与一裁终局直接对照"},{"t":"三大诉讼","n":"诉讼与非诉解纷并列"},{"t":"民法基本原则","n":"体现当事人意思自治"}],"exam":[]},{"id":"a15-056","t":"法治与法制","cid":"15d","p":3,"kind":"概念","alias":["法制与法治"],"one":"法制侧重法律制度本身，法治强调法律至上与依法治理的治国状态。","ans":"法治与法制是法学基础中字形相近、内涵有别的两个概念。**“法制”**指法律和制度总称，侧重静态**法律规范体系**；**“法治”**指法律至上、依法治理的**治国方略与良法善治状态**，重在权力制约与权利保障。法制是法治前提，有法制未必有法治。","pts":["法制指法律制度体系，侧重静态规则本身","法治指法律至上、依法治理的方略与状态","法制是法治前提，有法制未必实现法治"],"mem":"拆字直记：“制”是制度（静态的法条与机器），“治”是治理（动态的依法治国与良法善治）。封建专制王朝也有严苛“法制”，唯独现代民主国家追求“法治”。","mix":"党的十五大（1997年）将“建设社会主义法制国家”正式改写为“建设社会主义法治国家”，一字之变是常考的政治与法学辨析点。","mcq":[{"q":"关于“法制”与“法治”的关系，下列辨析表述准确的是","o":["二者含义完全相同，仅写法略有差异","法治专指古代法律制度，法制专指现代法律","法制侧重法律制度体系，法治侧重法律至上的治国方略","只要建立完备的法制就自然实现了法治"],"a":2,"w":"法制侧重静态的法律制度本身，法治强调良法善治与依法治国的动态状态，有法制未必有法治。"}],"rel":[{"t":"依法治国与十八届四中全会","n":"全面依法治国方略"},{"t":"法律效力位阶","n":"法制体系层级结构"},{"t":"大陆法系","n":"法学基础同簇"}],"exam":[]},{"id":"a15-057","t":"军委管总、战区主战、军种主建","cid":"15e","p":1,"kind":"制度","alias":["军委管总","战区主战","军种主建","领导管理体制和作战指挥体制"],"one":"2015年底国防和军队改革确立的领导管理与作战指挥体制。","ans":"“军委管总、战区主战、军种主建”是**2015年底启动的国防和军队改革所确立的军队领导管理体制和联合作战指挥体制**。**军委管总**指中央军委统管全军，2016年1月军委机关由四总部改为15个职能部门；**战区主战**指2016年2月成立的**五大战区**负责联合作战指挥；**军种主建**指陆、海、空、火箭军等军种负责力量建设。这一体制理顺了“建”与“用”的关系，把作战指挥权与建设管理权分开，推动军队由按军种分头指挥转向联合作战。","pts":["2015年底改革确立","军委统管、战区作战、军种建设","2016年五大战区、15个职能部门"],"mem":"十二字拆三段，各管一件事：管（军委管总）、战（战区主战）、建（军种主建）。画面：军委是总管家，战区是前线指挥官，军种是后方的训练和装备部门，“建的不管打，打的不管建”。","mix":"军种不再直接指挥作战，作战指挥归战区；“军委管总”不是军委直接带兵打仗，而是领导管理；该体制与2024年4月形成的“4+4”军兵种结构是先后两步改革成果。","mcq":[{"q":"在“军委管总、战区主战、军种主建”体制中，负责联合作战指挥的是","o":["中央军委机关各部门","军种","战区","联勤保障部队"],"a":2,"w":"战区主战，战区是联合作战指挥机构。"},{"q":"该体制确立于","o":["1955年","1985年","2003年","2015年底启动的改革"],"a":3,"w":"2015年底国防和军队改革启动，形成这一体制。"}],"rel":[{"t":"五大战区","n":"战区主战的载体"},{"t":"四个军种","n":"军种主建的主体"},{"t":"中央军事委员会","n":"军委管总"},{"t":"军队编制序列","n":"编制层级"}],"exam":[]},{"id":"a15-058","t":"五大战区","cid":"15e","p":1,"kind":"合称","alias":["东部战区","南部战区","西部战区","北部战区","中部战区","战区"],"one":"2016年2月1日成立的东、南、西、北、中五个战区。","ans":"五大战区指**2016年2月1日成立的东部、南部、西部、北部、中部战区**，取代原来的七大军区，是**联合作战指挥机构**。五大战区的司令部分别设在**南京（东部）、广州（南部）、成都（西部）、沈阳（北部）、北京（中部）**。战区按“军委管总、战区主战、军种主建”的原则，承担本方向联合作战指挥和战略任务，平时负责战备、训练和应对安全威胁。设立五大战区使军队指挥体制由军区制转变为战区制，适应联合作战的要求。","pts":["2016年2月1日成立","取代七大军区","东南西北中，联合作战指挥"],"members":[["东部战区","司令部南京"],["南部战区","司令部广州"],["西部战区","司令部成都"],["北部战区","司令部沈阳"],["中部战区","司令部北京"]],"mem":"“东南西北中”五个方位，对应司令部城市“宁、穗、蓉、沈、京”，可念成：南京管东，广州管南，成都管西，沈阳管北，北京居中。原七大军区是沈阳、北京、兰州、济南、南京、广州、成都，战区制后减为五个。","mix":"战区不是军区，军区时代有七大军区，战区只有五个；战区负责作战指挥，不负责军种建设；西部战区司令部在成都，不是兰州（兰州军区已撤销）。","mcq":[{"q":"东部战区司令部所在地是","o":["上海","济南","南京","广州"],"a":2,"w":"东部战区司令部设在南京。"},{"q":"五大战区取代的是","o":["四大野战军","七大军区","十一个集团军","十三个军区"],"a":1,"w":"2016年2月成立五大战区，取代原来的七大军区。"}],"rel":[{"t":"军委管总、战区主战、军种主建","n":"体制背景"},{"t":"中央军事委员会","n":"统一领导"},{"t":"军队编制序列","n":"编制层级"},{"t":"八一建军节","n":"军队常识"}],"more":"2016年2月1日在北京八一大楼举行五大战区成立大会，中央军委主席向各战区授予军旗。","exam":[]},{"id":"a15-059","t":"中国武装力量的构成","cid":"15e","p":1,"kind":"合称","alias":["武装力量构成","三位一体武装力量","解放军武警民兵"],"one":"解放军、武警部队、民兵三部分，由中央军委统一领导。","ans":"中国武装力量的构成指**中国人民解放军、中国人民武装警察部队和民兵**三部分，现行《国防法》（2020年修订，2021年1月1日施行）作了规定。**中国人民解放军**是主力，分为现役部队和预备役部队；**武警部队**担负执勤、处置突发事件等任务，2018年1月1日起由中央军委统一领导指挥；**民兵**是不脱离生产的群众武装组织，是武装力量的重要组成部分。全国武装力量由**中央军事委员会领导**，实行主席负责制。","pts":["解放军、武警、民兵","解放军含现役和预备役","由中央军委统一领导"],"members":[["中国人民解放军","主力，分现役部队和预备役部队"],["中国人民武装警察部队","2018年起归中央军委统一领导"],["民兵","不脱离生产的群众武装"]],"mem":"三个关键词“军、警、民”：解放军、武警、民兵。解放军内部再分“现役、预备役”两种。顺口：军警民，一委领。","mix":"武装力量包括武警和民兵，不能只说解放军；民兵不脱产，解放军现役部队是常备军；中央军委领导全国武装力量，国务院领导的是国防建设中的行政工作，二者不能混淆。","mcq":[{"q":"下列不属于中国武装力量组成部分的是","o":["中国人民解放军","中国人民武装警察部队","民兵","公安机关警察"],"a":3,"w":"武装力量由解放军、武警部队和民兵构成，公安机关不在其列。"},{"q":"领导全国武装力量的机关是","o":["国务院","国防部","中央军事委员会","全国人大常委会"],"a":2,"w":"宪法规定中央军事委员会领导全国武装力量。"}],"rel":[{"t":"中央军事委员会","n":"领导全国武装力量"},{"t":"军队编制序列","n":"解放军的编制"},{"t":"全民国防教育日","n":"国防教育常识"},{"t":"八一建军节","n":"解放军诞辰"}],"exam":[]},{"id":"a15-060","t":"中国人民武装警察部队","cid":"15e","p":2,"kind":"制度","alias":["武警部队","武警"],"one":"我国武装力量组成部分，2018年起由党中央、中央军委集中统一领导。","ans":"中国人民武装警察部队（简称武警）是**我国武装力量的重要组成部分**，**1982年决定组建、1983年成立**，不列入解放军序列。自**2018年1月1日零时起**，武警部队由**党中央、中央军委集中统一领导**，归中央军委建制，**不再列国务院序列**；同年7月1日**海警队伍整体划归武警**。它主要担负维护政治安全与社会稳定、海上维权执法和防卫作战任务。","pts":["我国武装力量组成部分，不列入解放军序列","2018年1月1日起由党中央、中央军委集中统一领导","不再列国务院序列，2018年7月海警整体划归武警"],"mem":"记住2018年“一头一中”两次大改：**1月1日**体制改（归中央军委集中统一领导，退出国务院序列），**7月1日**海警并入（组建武警海警总队，对外称中国海警局）。","mix":"武警部队虽归中央军委建制，但不列入中国人民解放军序列，与解放军、民兵并列构成我国武装力量；2018年改革前武警实行国务院、中央军委双重领导，改革后不再列国务院序列。","mcq":[{"q":"自2018年1月1日零时起，中国人民武装警察部队的领导指挥体制调整为","o":["由党中央、中央军委集中统一领导，不再列国务院序列","由国务院、中央军委实行双重领导","正式并入中国人民解放军陆军序列","划归公安部统一指挥管理"],"a":0,"w":"2018年1月1日零时起，武警部队归中央军委建制，由党中央、中央军委集中统一领导，不再列国务院序列。"}],"rel":[{"t":"中央军事委员会","n":"集中统一领导武警部队"},{"t":"四个军种","n":"同属国家武装力量体系"},{"t":"联合国海洋法公约的海域划分","n":"武警海警维护海洋权益"}],"more":"2018年7月1日零时起，海警队伍整体划归武警部队领导指挥，对外称中国海警局。","exam":[]},{"id":"a15-061","t":"火箭军","cid":"15e","p":2,"kind":"制度","alias":["中国人民解放军火箭军","第二炮兵","二炮"],"one":"解放军战略导弹军种，前身为1966年组建的第二炮兵，2015年底更名。","ans":"中国人民解放军火箭军是**解放军四个军种之一**，是**我国战略威慑的核心力量**和战略导弹部队。其前身为**1966年7月1日**组建的战略导弹部队，由周恩来命名为**“第二炮兵”**，原属直属中央军委的战略独立兵种。**2015年12月31日**，第二炮兵正式更名为**火箭军**，由独立兵种升格为独立军种。它承担战略核威慑、核反击与常规导弹精确打击使命。","pts":["前身为1966年7月1日组建的第二炮兵","2015年12月31日更名为火箭军，由兵种升为军种","解放军四个军种之一，我国战略威慑核心力量"],"mem":"记住两个整点日期与一次升级：**1966年7月1日**（建党节）成立“二炮”（周恩来为保密命名），**2015年12月31日**（跨年夜）改名“火箭军”，从“独立兵种”升格为“独立军种”。2026年为其前身组建60周年。","mix":"2024年4月调整后，解放军四个军种为陆军、海军、空军、火箭军，四个兵种为军事航天、网络空间、信息支援、联勤保障部队；别把火箭军混入兵种，也别把二炮组建年份错记为1964年。","mcq":[{"q":"2015年12月31日正式更名并由独立兵种升格为独立军种的是","o":["战略支援部队","军事航天部队","信息支援部队","火箭军"],"a":3,"w":"火箭军前身为1966年7月1日组建的第二炮兵，2015年12月31日更名为火箭军并升格为独立军种。"}],"rel":[{"t":"四个军种","n":"陆海空火箭军之一"},{"t":"四个兵种","n":"2024年调整后的军兵种体系"},{"t":"军种成立纪念日","n":"7月1日为火箭军成立纪念日"},{"t":"“两弹一星”功勋科学家","n":"战略导弹技术奠基"}],"more":"关键年份：1966年7月1日组建第二炮兵（2026年为60周年）；2015年12月31日更名为火箭军。","exam":[]},{"id":"a15-062","t":"军种成立纪念日","cid":"15e","p":3,"kind":"常识","alias":["海军节","空军节"],"one":"海军4月23日、空军11月11日，陆军领导机构与火箭军12月31日。","ans":"军种成立纪念日指人民解放军**四大军种**的重要建军节点。海军成立于**1949年4月23日**，空军成立于**1949年11月11日**；**2015年12月31日**，**陆军领导机构与火箭军**同日成立并获授军旗，见证人民军队向联合作战体系转型。","pts":["海军4月23日、空军11月11日（均1949年）","陆军领导机构与火箭军2015年12月31日成立","陆军传统溯源八一，火箭军前身二炮建于1966年"],"mem":"巧用节日搭桥记：4月23日世界读书日也是海军成立日；11月11日双十一是空军成立日；12月31日跨年夜（2015年）陆军领导机构与火箭军同日成立。","mix":"陆军作为最早组建的军种随1927年8月1日建军节纪念，2015年12月31日成立的是陆军独立领导机构；火箭军由第二炮兵（1966年7月1日组建）更名而来；2024年4月19日新组建的是信息支援部队（属兵种）。","mcq":[{"q":"下列中国人民解放军军种与其成立纪念日对应有误的一项是","o":["海军：1949年4月23日","空军：1949年11月11日","火箭军：2015年12月31日","陆军领导机构：2024年4月19日"],"a":3,"w":"陆军领导机构与火箭军同于2015年12月31日成立；2024年4月19日成立的是信息支援部队。"}],"rel":[{"t":"四个军种","n":"陆海空火四大军种"},{"t":"四个兵种","n":"2024年军兵种新格局"},{"t":"火箭军","n":"2015年由二炮更名"},{"t":"八一建军节","n":"人民军队建军纪念日"}],"exam":[]},{"id":"a15-063","t":"军衔“三等十级”","cid":"15e","p":1,"kind":"合称","alias":["军官军衔","三等十级","将校尉"],"one":"军官军衔分将、校、尉三等十级：将官三级、校官四级、尉官三级。","ans":"军衔“三等十级”指解放军**现行军官军衔分将官、校官、尉官三等，共十级**。**将官三级：上将、中将、少将；校官四级：大校、上校、中校、少校；尉官三级：上尉、中尉、少尉**。我国1955年首次实行军衔制，授予元帅、大将等，1965年取消，1988年恢复军衔制。现行军衔没有元帅和大将，上将是常态下的最高军衔，由中央军委主席授予。军衔是区分军人等级的标志，体现军人的责任、荣誉和待遇。","pts":["将、校、尉三等","3+4+3共十级","1955年首授，1965年取消，1988年恢复"],"members":[["将官","上将、中将、少将"],["校官","大校、上校、中校、少校"],["尉官","上尉、中尉、少尉"]],"mem":"“三、四、三”：将官三级，校官四级（多一个大校），尉官三级，合计十级。等级名称用“上中少”重复三遍：上将中将少将，上校中校少校（前面多一个大校），上尉中尉少尉。","mix":"1955年授衔有元帅和大将，现行军衔制没有；大校是校官中最高一级，没有“大将”“大尉”；校官四级而不是三级，选择题常在数字上设陷阱。","mcq":[{"q":"下列军衔中，属于现行校官军衔的是","o":["大将","大校","大尉","准尉"],"a":1,"w":"现行校官为大校、上校、中校、少校。"},{"q":"现行军官军衔制的“三等十级”中，尉官有","o":["二级","三级","四级","五级"],"a":1,"w":"尉官为上尉、中尉、少尉三级；将官三级，校官四级。"}],"rel":[{"t":"十大元帅与十大将","n":"1955年授衔"},{"t":"军队编制序列","n":"军队等级"},{"t":"中央军事委员会","n":"授予上将军衔"},{"t":"八一建军节","n":"军队常识"}],"more":"1955年9月授衔，设元帅、大将、上将、中将、少将、大校至少尉；1965年取消军衔；1988年恢复。","exam":[]},{"id":"a15-064","t":"十大元帅与十大将","cid":"15e","p":1,"kind":"合称","alias":["十大元帅","十大将","1955年授衔","开国元帅","开国大将"],"one":"1955年授衔的十位元帅和十位大将。","ans":"十大元帅与十大将指**1955年9月授予军衔时评定的十位元帅和十位大将**。**十大元帅为朱德、彭德怀、林彪、刘伯承、贺龙、陈毅、罗荣桓、徐向前、聂荣臻、叶剑英**；**十大将为粟裕、徐海东、黄克诚、陈赓、谭政、萧劲光、张云逸、罗瑞卿、王树声、许光达**。他们大多是红军时期和抗日战争、解放战争中的高级将领，如粟裕指挥淮海战役，萧劲光为海军首任司令员。1955年军衔制在1965年被取消，1988年恢复时不再设元帅和大将。","pts":["1955年9月授衔","十元帅：朱彭林刘贺陈罗徐聂叶","十大将：粟徐黄陈谭萧张罗王许"],"members":[["朱德","元帅，红军总司令"],["彭德怀","元帅，抗美援朝志愿军司令员"],["林彪","元帅，辽沈、平津战役主帅"],["刘伯承","元帅，刘邓大军"],["贺龙","元帅，南昌起义领导者之一"],["陈毅","元帅，曾任上海市长、外交部长"],["罗荣桓","元帅，政治工作"],["徐向前","元帅，红四方面军"],["聂荣臻","元帅，“两弹一星”组织者"],["叶剑英","元帅，1976年粉碎“四人帮”"],["粟裕","大将，淮海战役主要指挥者"],["徐海东","大将"],["黄克诚","大将"],["陈赓","大将"],["谭政","大将"],["萧劲光","大将，海军首任司令员"],["张云逸","大将"],["罗瑞卿","大将"],["王树声","大将"],["许光达","大将，装甲兵创建者"]],"mem":"元帅十字口诀“朱彭林刘贺，陈罗徐聂叶”，各取姓氏首字，念两句五字。大将十字“粟徐黄陈谭，萧张罗王许”，同样两句五字。数量记 10+10；授衔年份 1955，九月；毛泽东、周恩来没有授衔。","mix":"邓小平、周恩来、毛泽东没有授衔，当时他们主要担任党政职务；粟裕是十大将之首，不是元帅；林彪、彭德怀是元帅，不是大将。","mcq":[{"q":"下列人物中，不属于十大元帅的是","o":["聂荣臻","罗荣桓","陈毅","粟裕"],"a":3,"w":"粟裕是十大将之首，不是元帅。"},{"q":"十大将中，曾任海军首任司令员的是","o":["陈赓","萧劲光","许光达","罗瑞卿"],"a":1,"w":"萧劲光是人民海军首任司令员。"}],"rel":[{"t":"军衔“三等十级”","n":"现行军衔制"},{"t":"三大战役","n":"多位元帅大将指挥"},{"t":"红军长征","n":"他们多是红军将领"},{"t":"黄埔军校","n":"部分将帅出身"}],"more":"1955年9月27日授衔，国家主席毛泽东发布命令。","exam":[]},{"id":"a15-065","t":"中国航空母舰","cid":"15e","p":1,"kind":"常识","alias":["辽宁舰","山东舰","福建舰","国产航母","电磁弹射航母"],"one":"辽宁舰、山东舰、福建舰：第一艘、第一艘国产、第一艘电磁弹射型。","ans":"中国航空母舰目前有三艘。**辽宁舰2012年9月交付海军，是中国第一艘航空母舰**，由原苏联未完工舰体“瓦良格号”改建；**山东舰2019年12月入列，是第一艘国产航母**；**福建舰2025年11月入列，是第一艘电磁弹射型航母**。辽宁舰和山东舰采用滑跃起飞方式，福建舰采用电磁弹射，舰载机出动能力显著提升。三艘航母的舷号依次为16、17、18。航母的列装标志着海军向远海防卫型发展，福建舰入列使中国航母进入电磁弹射时代。","pts":["辽宁舰2012年，第一艘","山东舰2019年，第一艘国产","福建舰2025年，电磁弹射"],"mem":"舷号 16、17、18 连号，对应辽宁、山东、福建，入列年份 2012、2019、2025。三个“第一”：辽宁＝第一艘，山东＝第一艘国产，福建＝第一艘电磁弹射。画面：辽宁、山东用“滑跃甲板”（像滑梯），福建用“电磁弹射”（像弹弓）。","mix":"山东舰是第一艘国产航母，辽宁舰不是国产（由瓦良格号改建）；福建舰是电磁弹射型，辽宁、山东是滑跃起飞；三艘航母入列时间不同，不要把2025年11月的福建舰说成“第二艘”。","mcq":[{"q":"中国第一艘国产航空母舰是","o":["辽宁舰","福建舰","山东舰","瓦良格号"],"a":2,"w":"山东舰2019年12月入列，是第一艘国产航母。"},{"q":"中国第一艘电磁弹射型航母是","o":["福建舰","山东舰","辽宁舰","南昌舰"],"a":0,"w":"福建舰2025年11月入列，采用电磁弹射。"}],"rel":[{"t":"四个军种","n":"海军装备"},{"t":"军种成立纪念日","n":"海军成立于4月23日"},{"t":"英国击败西班牙无敌舰队","n":"海权史对照"},{"t":"中央军事委员会","n":"军队领导"}],"more":"辽宁舰2012年9月交付，舷号16；山东舰2019年12月入列，舷号17；福建舰2022年6月下水，2025年11月入列，舷号18。","exam":[]},{"id":"a15-066","t":"建军100周年","cid":"15e","p":3,"kind":"事件","alias":["建军一百年奋斗目标","建军百年"],"one":"1927年8月1日南昌起义建军，2027年为中国人民解放军建军100周年。","ans":"建军100周年是人民军队百年历史坐标与强军战略节点。**1927年8月1日**周恩来等领导**南昌起义**，打响武装反抗国民党反动派第一枪，**2027年**即迎来**建军100周年**。如期实现**建军一百年奋斗目标**，是推进军队现代化的关键阶段任务。","pts":["1927年8月1日南昌起义标志人民军队诞生","2027年为中国人民解放军建军100周年","如期实现建军一百年奋斗目标为战略部署"],"mem":"时间锚点：2027年备考届别正好碰上“1927至2027”整百年！记清“1927南昌八一→2027建军百年→2035基本实现国防和军队现代化→本世纪中叶建成世界一流军队”。","mix":"1927年8月1日南昌起义是建军节来源，1927年9月9日秋收起义首次打出“工农革命军”旗帜并引兵井冈山，切勿将两场起义的标志意义混淆。","mcq":[{"q":"2027年将迎来中国人民解放军建军100周年，其历史起点标志事件是1927年的","o":["秋收起义","南昌起义","广州起义","三湾改编"],"a":1,"w":"1927年8月1日南昌起义打响武装反抗国民党反动派的第一枪，8月1日因此定为建军节。"}],"rel":[{"t":"八一建军节","n":"南昌起义确立建军节"},{"t":"军委管总、战区主战、军种主建","n":"新时代强军体制格局"},{"t":"“两步走”战略安排","n":"与国防现代化步调一致"},{"t":"2025年九三阅兵","n":"新时代强军风貌展示"}],"exam":[]},{"id":"a15-068","t":"《孙膑兵法》","cid":"15e","p":3,"kind":"作品","alias":["《齐孙子》"],"one":"战国齐人孙膑兵书，1972年银雀山汉墓与《孙子兵法》同墓出土。","ans":"《孙膑兵法》又称**《齐孙子》**，是战国齐国军事家**孙膑**及其弟子整理的兵学典籍。该书失传千余年，直至**1972年**在**山东临沂银雀山汉墓**与**《孙子兵法》**竹简同出，终结孙武与孙膑是否同一人的千年公案，丰富了先秦兵家理论。","pts":["战国齐人孙膑著，又称《齐孙子》","1972年山东临沂银雀山汉墓与《孙子兵法》同出","终结孙武孙膑合一公案，代表战国兵学成就"],"mem":"一墓解千古谜：记“1972临沂银雀山，一坑挖出两孙子”，春秋孙武写《孙子兵法》（吴孙子），战国孙膑写《孙膑兵法》（齐孙子），从此不再张冠李戴。","mix":"《孙子兵法》入选北宋“武经七书”居首，而《孙膑兵法》因当时早已失传，并不在“武经七书”之列；孙膑曾主导“围魏救赵”（桂陵之战）与马陵之战。","mcq":[{"q":"1972年与《孙子兵法》竹简同墓出土、终结“二孙公案”的《孙膑兵法》发现于","o":["山东临沂银雀山汉墓","湖南长沙马王堆汉墓","湖北云梦睡虎地秦墓","湖北随州曾侯乙墓"],"a":0,"w":"1972年山东临沂银雀山汉墓同时出土《孙子兵法》与《孙膑兵法》竹简。"}],"rel":[{"t":"《孙子兵法》","n":"同墓出土的姊妹兵书"},{"t":"孙武与孙膑","n":"春秋与战国两位兵家"},{"t":"武经七书","n":"《孙膑兵法》未入七书"},{"t":"兵家","n":"先秦诸子兵学流派"}],"exam":[]},{"id":"a15-069","t":"《三十六计》","cid":"15e","p":2,"kind":"作品","alias":["三十六计","三十六策"],"one":"古代著名计谋兵书，分胜、敌、攻、混、并、败战六套共36计。","ans":"《三十六计》是中国古代一部**成书年代与作者不详的兵书**，集中总结了传统军事谋略。其语源最早见于**《南齐书·王敬则传》**“檀公三十六策，走是上计”，完整体例一般认为**成书于明末清初**。全书按战局分为**胜战、敌战、攻战、混战、并战、败战六套，每套六计**，以**“走为上计”**收尾。它以简练成语概括兵家辩证智慧，深远影响了军事文化与汉语表达。","pts":["成书年代不详，语源出自《南齐书·王敬则传》","分胜战、敌战、攻战、混战、并战、败战六套","每套六计，集中总结中国古代军事谋略"],"mem":"六套顺序口诀：**“胜敌攻，混并败”**（前3套占优或相持：胜战、敌战、攻战；后3套复杂或劣势：混战、并战、败战，末计“走为上计”）。","mix":"《三十六计》不在北宋官方颁定的“武经七书”之列；“三十六策，走是上计”最早见于南朝《南齐书》典出刘宋名将檀道济，并非出自《孙子兵法》。","mcq":[{"q":"《三十六计》全书分为六套、每套六计，下列不属于这六套的是","o":["胜战计","奇战计","混战计","败战计"],"a":1,"w":"六套依次为胜战计、敌战计、攻战计、混战计、并战计、败战计，没有“奇战计”。"}],"rel":[{"t":"《孙子兵法》","n":"中国兵学最高经典"},{"t":"武经七书","n":"《三十六计》不在其列"},{"t":"兵家","n":"先秦至后世兵学脉络"},{"t":"克劳塞维茨《战争论》","n":"中西军事著作对照"}],"more":"语源：《南齐书·王敬则传》“檀公三十六策，走是上计”。现存最早印本发现于1941年。","exam":[]},{"id":"a15-070","t":"克劳塞维茨《战争论》","cid":"15e","p":2,"kind":"作品","alias":["战争论","克劳塞维茨","Vom Kriege"],"one":"普鲁士克劳塞维茨著，1832年出版，提出“战争是政治的继续”。","ans":"《战争论》（Vom Kriege）是**普鲁士军事理论家克劳塞维茨**（1780–1831）的代表作，于**1832年由其遗孀玛丽整理出版**。该书是**西方近代军事理论集大成之作**，全书八篇，论述战争本质与攻防规律。书中提出**“战争是政治的继续”**，揭示战争服从政治目的的本质。它奠定西方现代战略学基石，常与《孙子兵法》并称东西方兵学双璧。","pts":["普鲁士克劳塞维茨著，1832年遗作出版","核心论断：战争是政治的继续","西方近代军事理论集大成，与《孙子兵法》并称"],"mem":"东西方兵学双峰对照：东方春秋**孙武《孙子兵法》**讲“不战而屈人之兵”（重谋略），西方19世纪普鲁士**克劳塞维茨《战争论》**讲“战争是政治的继续”（重政治本质）。","mix":"克劳塞维茨是普鲁士人，1831年病逝前仅完成第一篇第一章定稿及前六篇誊清稿，1832至1834年由遗孀玛丽陆续整理出版全书，别误记为法国军事家或拿破仑本人著作。","mcq":[{"q":"提出“战争是政治的继续”这一著名论断的西方军事著作是","o":["马汉《海权论》","若米尼《战争艺术概论》","克劳塞维茨《战争论》","杜黑《制空权》"],"a":2,"w":"普鲁士军事理论家克劳塞维茨在1832年出版的《战争论》中提出“战争是政治的继续”。"}],"rel":[{"t":"《孙子兵法》","n":"东西方两大兵学经典"},{"t":"《三十六计》","n":"中西兵书对照"},{"t":"拿破仑","n":"克劳塞维茨亲历并总结其战法"}],"more":"核心名言：战争是政治通过其他手段的继续。｜《战争论》","exam":[]},{"id":"a15-071","t":"官渡之战","cid":"15e","p":2,"kind":"事件","alias":["官渡大战"],"one":"公元200年曹操以少胜多击败袁绍，奠定统一北方基础。","ans":"官渡之战发生于**东汉建安五年（公元200年）**，是**曹操与袁绍**在官渡展开的决战，属**三国三大战役**之一。当时袁绍兵强马壮、实力占优，两军相持不下；曹操采纳谋士建议，率精锐**偷袭袁军粮仓乌巢**，尽焚其粮草，导致袁军溃败。此战是中国古代**以少胜多**的经典战例。战后曹操逐步消灭袁氏势力，**奠定了统一中国北方的基础**，改写了东汉末年的群雄格局。","pts":["公元200年曹操以少胜多击败袁绍","关键一击：曹操率精锐偷袭乌巢烧毁袁军粮草","奠定曹操统一北方的基础，三国三大战役之一"],"mem":"对比连记：**200年官渡**（曹操烧袁绍乌巢粮→统北方）→ 8年后 **208年赤壁**（孙刘火烧曹船→三国鼎立），两战主角都有曹操，前胜后败、全是以少胜多和火攻。","mix":"官渡之战奠定的是曹操“统一北方”的基础，奠定“三国鼎立”基础的是208年赤壁之战；两战均发生在东汉末年，当时魏蜀吴三国尚未正式建立。","mcq":[{"q":"公元200年发生的官渡之战中，曹操取得决定性胜利的关键行动是","o":["借东风火烧连环战船","偷袭乌巢烧毁袁军粮草","草船借箭补充军备","决水淹没敌军营寨"],"a":1,"w":"官渡之战中曹操偷袭袁绍粮仓乌巢、烧毁粮草，大败袁军；火烧战船属赤壁之战。"}],"rel":[{"t":"赤壁之战","n":"8年后曹操南下惨败"},{"t":"三国三大战役","n":"官渡、赤壁、夷陵之首"},{"t":"曹操","n":"战役获胜方统帅"},{"t":"淝水之战","n":"同为古代以少胜多战役"}],"more":"关键年份：东汉建安五年（200年），曹操胜袁绍，奠定统一北方基础。","exam":[]},{"id":"a15-072","t":"赤壁之战","cid":"15e","p":2,"kind":"事件","alias":["赤壁大战"],"one":"公元208年孙刘联军火攻击败曹操，奠定三国鼎立基础。","ans":"赤壁之战发生于**东汉建安十三年（公元208年）**，是**孙权、刘备联军**与南下**曹操**在赤壁展开的决战，属**三国三大战役**。面对曹军战船首尾相连之势，吴军统帅**周瑜**采纳老将**黄盖**诈降火攻之策，借东南风纵火焚毁曹军水师与江北营寨。此战是中国古代**以少胜多**的著名水战。战后曹操北归，孙刘巩固地盘，**奠定了三国鼎立的基础**。","pts":["公元208年孙权、刘备联军击败曹操","周瑜统帅，黄盖诈降并借东南风火攻破曹","以少胜多著名水战，奠定三国鼎立基础"],"mem":"区分“正史vs演义”：正史里赤壁核心功臣是**周瑜**统帅、**黄盖**献计诈降火攻；《三国演义》才添上苦肉计、草船借箭与借东风。年份记208（比官渡200年晚8年）。","mix":"赤壁之战奠定三国鼎立基础，官渡之战奠定曹操统一北方基础；苏轼《赤壁赋》所游是湖北黄冈“文赤壁”，并非古战场赤壁。","mcq":[{"q":"下列关于公元208年赤壁之战的说法，符合史实的是","o":["交战双方是曹操与袁绍","奠定了曹操统一中国北方的基础","发生在曹丕建立魏国之后","孙刘联军由周瑜指挥，借黄盖诈降火攻击败曹军"],"a":3,"w":"赤壁之战中周瑜统帅孙刘联军，以黄盖诈降火攻击败曹操，奠定三国鼎立基础。"}],"rel":[{"t":"官渡之战","n":"8年前曹操胜袁绍"},{"t":"三国三大战役","n":"决定三国鼎立的一役"},{"t":"《三国演义》人物与情节","n":"衍生众多经典桥段"},{"t":"曹操","n":"战役南下失利一方"}],"more":"关键年份：东汉建安十三年（208年）。名诗：杜牧《赤壁》“东风不与周郎便，铜雀春深锁二乔”。","exam":[]},{"id":"a15-074","t":"长平之战与巨鹿之战","cid":"15e","p":3,"kind":"事件","alias":["巨鹿之战","纸上谈兵","破釜沉舟"],"one":"长平之战白起胜赵括“纸上谈兵”，巨鹿之战项羽“破釜沉舟”破秦。","ans":"长平之战与巨鹿之战是关系秦国崛起与秦朝覆亡的两次著名战役。**前260年长平之战**，秦将**白起**大败**“纸上谈兵”**的赵括，六国再难抗秦；**前207年巨鹿之战**，**项羽**率楚军**“破釜沉舟”**大破秦军主力，成为推翻秦朝的决定性转折。","pts":["长平之战：前260年，白起胜赵括，典故纸上谈兵","巨鹿之战：前207年，项羽破秦军，典故破釜沉舟","前者奠定秦统一大势，后者加速秦朝覆亡"],"mem":"一兴一亡对称记：“长平白起兴秦，赵括纸上谈兵；巨鹿项羽灭秦，楚军破釜沉舟”。相隔五十三年（前260到前207），正好串起秦帝国崛起与崩塌。","mix":"长平之战是秦赵实力相近的大规模决战，不属于典型“以少胜多”；巨鹿之战与官渡、赤壁、淝水等并称中国古代以少胜多经典战例，切勿将“背水一战”（韩信井陉之战）混为巨鹿典故。","mcq":[{"q":"下列古代战役、核心人物与相关成语典故对应完全正确的一组是","o":["长平之战、廉颇、破釜沉舟","巨鹿之战、韩信、背水一战","巨鹿之战、项羽、破釜沉舟","长平之战、白起、围魏救赵"],"a":2,"w":"公元前207年巨鹿之战项羽“破釜沉舟”大破秦军；长平之战对应白起与赵括“纸上谈兵”。"}],"rel":[{"t":"长平之战","n":"单列战史词条互参"},{"t":"战国七雄","n":"长平之战改写战国格局"},{"t":"秦始皇统一六国","n":"长平大捷奠定统一基础"},{"t":"淝水之战","n":"古代以少胜多战役对照"}],"exam":[]},{"id":"a15-075","t":"三大战役","cid":"15e","p":1,"kind":"合称","alias":["辽沈战役","淮海战役","平津战役","三大战役（解放战争）","渡江战役"],"one":"1948至1949年解放战争的辽沈、淮海、平津三大战略决战。","ans":"三大战役指**解放战争时期1948年9月至1949年1月，人民解放军同国民党军进行的辽沈、淮海、平津三大战略决战**。**辽沈战役**（1948年9月至11月）解放东北全境；**淮海战役**（1948年11月至1949年1月）由刘伯承、陈毅、邓小平、粟裕等指挥，歼敌50多万；**平津战役**（1948年11月至1949年1月）以北平和平解放告终。三大战役共歼灭国民党军**150多万人**，基本消灭国民党军主力，随后**1949年4月渡江战役**打开通往南京、上海的大门，奠定了全国胜利的基础。","pts":["辽沈、淮海、平津，1948.9至1949.1","共歼国民党军150多万","基本消灭国民党军主力，后有渡江战役"],"members":[["辽沈战役","1948年9月至11月，东北野战军，解放东北"],["淮海战役","1948年11月至1949年1月，华东、中原野战军，歼敌50多万"],["平津战役","1948年11月至1949年1月，北平和平解放"]],"mem":"顺序口诀“辽（9月）、淮（11月）、平（11月）”：辽沈最先，淮海与平津同月开打；记“东北先、中原中、华北后”。三大战役之后紧接“渡江战役”，4 月，南京解放。数字：共歼敌 150 多万。","mix":"三大战役是辽沈、淮海、平津，不包括渡江战役和孟良崮战役；淮海战役由刘邓陈粟指挥，辽沈、平津战役由林彪、罗荣桓领导的东北野战军指挥；平津战役以和平方式解放北平，天津是攻克的。","mcq":[{"q":"下列不属于三大战役的是","o":["辽沈战役","淮海战役","平津战役","渡江战役"],"a":3,"w":"渡江战役发生于1949年4月，不属于三大战役。"},{"q":"三大战役中最先开始的是","o":["淮海战役","平津战役","辽沈战役","渡江战役"],"a":2,"w":"辽沈战役1948年9月开始，淮海、平津战役在11月开始。"}],"rel":[{"t":"十大元帅与十大将","n":"主要指挥者"},{"t":"上海解放","n":"渡江战役之后"},{"t":"三国三大战役","n":"古代三大战役对照"},{"t":"斯大林格勒战役与诺曼底登陆","n":"世界史转折战役对照"}],"more":"渡江战役：1949年4月20日至21日发起，4月23日占领南京。","exam":[]},{"id":"a15-076","t":"平型关大捷","cid":"15e","p":2,"kind":"事件","alias":["平型关战役","平型关战斗"],"one":"1937年9月八路军115师伏击日军，全国抗战首个大胜仗。","ans":"平型关大捷发生于**1937年9月25日**，是全民族抗战爆发后**八路军第115师**在山西平型关伏击日军取得的胜利。在师长**林彪**、副师长**聂荣臻**指挥下，115师依托险要山地设伏，重创进犯日军并缴获大批物资。此战是**全国抗战以来中国军队取得的第一个大胜仗**。它**打破了“日军不可战胜”的神话**，极大振奋了全国抗战信心，扩大了八路军的威望。","pts":["1937年9月25日，八路军第115师设伏取胜","全国抗战以来中国军队第一个大胜仗","打破“日军不可战胜”神话，振奋抗战信心"],"mem":"抗战三场名战按年排序：**1937.9 平型关**（115师，全国抗战首胜）→ **1938春 台儿庄**（李宗仁，正面战场重大胜利）→ **1940.8 百团大战**（彭德怀，八路军规模最大）。","mix":"“全国抗战以来第一个大胜仗”是平型关大捷（八路军115师）；“抗战以来正面战场最大规模重大胜利”是1938年台儿庄战役（李宗仁），两者常互作干扰项。","mcq":[{"q":"1937年9月取得全国抗战以来中国军队第一个大胜仗的部队和战役是","o":["八路军第115师、平型关大捷","国民党第五战区、台儿庄战役","八路军105个团、百团大战","新四军、黄桥战役"],"a":0,"w":"1937年9月25日，八路军第115师取得平型关大捷，是全国抗战以来中国军队第一个大胜仗。"}],"rel":[{"t":"台儿庄战役","n":"1938年正面战场重大胜利"},{"t":"百团大战","n":"1940年八路军最大规模战役"},{"t":"2025年九三阅兵","n":"纪念抗战胜利80周年"}],"more":"关键日期：1937年9月25日；参战部队：八路军第115师（师长林彪、副师长聂荣臻）。","exam":[]},{"id":"a15-077","t":"台儿庄战役","cid":"15e","p":2,"kind":"事件","alias":["台儿庄大捷"],"one":"1938年春李宗仁指挥国民党军取胜，抗战正面战场重大胜利。","ans":"台儿庄战役发生于**1938年3月至4月**，是抗日战争时期**徐州会战**的重要组成部分。国民党第五战区司令长官**李宗仁**指挥中国军队，在山东台儿庄一带与日军激战并实施围歼，重创来犯日军。此战是**全国抗战以来中国军队在正面战场取得的重大胜利**。它沉重打击了日本侵略者的嚣张气焰，延缓了日军南下西进的战略步伐，极大鼓舞了全国军民坚持抗战的士气。","pts":["1938年3至4月，属徐州会战重要组成部分","第五战区司令长官李宗仁指挥国民党军队取胜","抗战以来正面战场取得的重大胜利"],"mem":"四要素绑牢：**台儿庄 = 1938春 + 李宗仁 + 徐州会战 + 正面战场重大胜利**。地理位置助记：台儿庄在山东最南端、紧邻江苏徐州，故归入“徐州会战”。","mix":"区分抗战三战役定位：平型关大捷（1937.9，全国抗战首胜，八路军115师）、台儿庄战役（1938春，正面战场重大胜利，李宗仁）、百团大战（1940，八路军规模最大主动进攻，彭德怀）。","mcq":[{"q":"1938年春由李宗仁指挥、属于徐州会战组成部分的正面战场重大胜利是","o":["淞沪会战","平型关大捷","台儿庄战役","武汉会战"],"a":2,"w":"台儿庄战役发生于1938年3至4月，由第五战区司令长官李宗仁指挥，属徐州会战。"}],"rel":[{"t":"平型关大捷","n":"1937年全国抗战首胜"},{"t":"百团大战","n":"敌后战场最大规模战役"},{"t":"2025年九三阅兵","n":"抗战胜利纪念"}],"more":"关键时间：1938年3月至4月；所属会战：徐州会战；指挥官：第五战区司令长官李宗仁。","exam":[]},{"id":"a15-078","t":"百团大战","cid":"15e","p":2,"kind":"事件","alias":["正太战役"],"one":"1940年彭德怀指挥八路军发动，抗战中八路军规模最大战役。","ans":"百团大战发生于**1940年8月至12月**，由**彭德怀**指挥**八路军**在华北敌后发动。战役先后投入**105个团**的兵力，重点破袭日军交通线、拔除据点，沉重打击了日军分割封锁根据地的**“囚笼政策”**。它是**抗日战争中八路军规模最大、持续时间最长的主动进攻战役**，振奋了全国士气，彰显了敌后战场的中流砥柱作用。","pts":["1940年8至12月，彭德怀指挥八路军发动","先后投入105个团，在华北打击日军“囚笼政策”","抗战中八路军规模最大的主动进攻战役"],"mem":"数字与人物串记：**1940年** + **105个团**（过百团，称百团）+ 破日军**“囚笼政策”** + 指挥员**彭德怀**（后来又指挥抗美援朝，一人串起两战）。","mix":"百团大战实际参战兵力达105个团，并非恰好100个团；它属于1940年敌后战场最大规模战役，不要与1937年的“首个大胜仗”平型关大捷混淆。","mcq":[{"q":"关于1940年发动的百团大战，下列说法错误的是","o":["由彭德怀指挥八路军发动","先后参战兵力达到105个团","沉重打击了华北日军的“囚笼政策”","是全国抗战以来中国军队取得的第一个大胜仗"],"a":3,"w":"全国抗战以来中国军队第一个大胜仗是1937年9月的平型关大捷；百团大战是抗战中八路军规模最大的战役。"}],"rel":[{"t":"平型关大捷","n":"1937年八路军抗战首胜"},{"t":"台儿庄战役","n":"正面战场代表战役对照"},{"t":"抗美援朝战争","n":"同由彭德怀指挥作战"}],"more":"关键信息：1940年8月至12月，华北敌后，八路军投入105个团。","exam":[]},{"id":"a15-079","t":"抗美援朝战争","cid":"15e","p":2,"kind":"事件","alias":["抗美援朝","抗美援朝保家卫国"],"one":"1950至1953年志愿军赴朝作战，经上甘岭等役签板门店停战协定。","ans":"抗美援朝战争是**1950年10月至1953年7月**中国人民志愿军赴朝保家卫国的正义战争。**1950年10月19日**彭德怀率军跨过鸭绿江，**10月25日**打响首战，定为**出国作战纪念日**。1952年秋季反击作战与**上甘岭战役**涌现**邱少云、黄继光**等英模；**1953年7月27日**双方在**板门店**签订《朝鲜停战协定》。此战打出国威军威，锻造了伟大抗美援朝精神。","pts":["1950年10月25日志愿军出国作战纪念日","1952年秋季反击作战与上甘岭战役涌现邱少云、黄继光等英模","1953年7月27日板门店签订《朝鲜停战协定》"],"mem":"时间三节点：**1950.10.25**首战纪念日→**1952**上甘岭坚守→**1953.7.27**板门店停战。英模按事迹记：黄继光（堵枪眼）、邱少云（烈火烧身严守纪律）。","mix":"志愿军10月19日秘密跨过鸭绿江，但抗美援朝出国作战纪念日是打响首战的10月25日；1953年7月27日在板门店签署的是《朝鲜停战协定》，并非和平条约。黄继光牺牲于上甘岭战役，邱少云则牺牲于该战役打响前两天的1952年10月12日391高地反击战。","mcq":[{"q":"中国人民志愿军抗美援朝出国作战纪念日是每年的","o":["10月19日","10月25日","7月27日","8月1日"],"a":1,"w":"1950年10月25日志愿军打响赴朝首战，这一天被定为抗美援朝出国作战纪念日；10月19日为秘密入朝日期，7月27日为停战协定签署日。"}],"rel":[{"t":"百团大战","n":"同由彭德怀任指挥员"},{"t":"《英雄儿女》","n":"抗美援朝题材经典作品"},{"t":"冷战","n":"冷战格局下的局部热战"},{"t":"伟大建党精神","n":"中国共产党人精神谱系"}],"more":"关键日期：1950年10月19日入朝，10月25日首战（纪念日）；1952年10月至11月上甘岭战役；1953年7月27日板门店签停战协定。","exam":[]},{"id":"a15-080","t":"两次世界大战","cid":"15e","p":2,"kind":"事件","alias":["一战与二战","世界大战"],"one":"1914至1918年一战与1939至1945年二战，重塑20世纪世界格局。","ans":"两次世界大战是20世纪席卷全球的大战。**第一次世界大战（1914–1918）**以**萨拉热窝事件**为导火索，同盟国与协约国交锋，战后形成凡尔赛-华盛顿体系。**第二次世界大战（1939–1945）**以**1939年9月德攻波兰**爆发，反法西斯同盟击败轴心国，**1945年9月2日日本签投降书**结束。二战催生**联合国**与雅尔塔体系，重塑国际秩序。","pts":["一战1914至1918年，萨拉热窝事件为导火索","二战1939年9月爆发，1945年9月2日结束","战后先后形成凡尔赛-华盛顿体系与联合国、雅尔塔体系"],"mem":"对称对比记：一战**1914–1918**（萨拉热窝导火索，同盟vs协约，战后建国联）；二战**1939–1945**（德攻波兰爆发，轴心vs反法西斯，9月2日日本签降书，战后建联合国）。","mix":"1945年5月8日德国投降只是欧洲战事结束，二战全面结束的标志是1945年9月2日日本签署投降书；9月3日是中国抗日战争胜利纪念日。","mcq":[{"q":"关于两次世界大战的关键节点，下列对应错误的是","o":["一战导火索：萨拉热窝事件","二战全面爆发：1939年9月德国进攻波兰","二战正式结束：1945年5月8日德国投降","战后国际组织：一战后建国联，二战后建联合国"],"a":2,"w":"1945年5月8日德国投降只是欧洲战事结束，二战全面结束的标志是1945年9月2日日本签署投降书。"}],"rel":[{"t":"三国同盟与三国协约","n":"一战前两大军事集团"},{"t":"凡尔赛-华盛顿体系","n":"一战后国际秩序"},{"t":"雅尔塔体系","n":"二战后国际秩序"},{"t":"联合国","n":"二战后成立的国际组织"}],"more":"两次大战起止：一战1914–1918年；二战1939年9月–1945年9月2日。","exam":[]},{"id":"a15-081","t":"斯大林格勒战役","cid":"15e","p":2,"kind":"事件","alias":["斯大林格勒保卫战"],"one":"1942至1943年苏军合围击败德军，苏德战场与二战欧洲转折点。","ans":"斯大林格勒战役发生于**1942年7月至1943年2月**，是二战中**苏联红军与德军**在伏尔加河畔的决战。德军企图夺城切断水运、进逼高加索油田，苏军坚守后发动**“天王星行动”**反攻合围，迫使德军第6集团军司令**保卢斯**元帅投降。此战是**苏德战场和二战欧洲战场的根本转折点**，粉碎了德军不可战胜的神话，苏军自此转入战略进攻。","pts":["1942年7月至1943年2月，苏德伏尔加河畔决战","苏军反攻合围，德军保卢斯率第6集团军投降","苏德战场与二战欧洲战场的根本转折点"],"mem":"二战欧亚美转折点一起记：**苏德/欧洲 = 斯大林格勒**（1942.7–1943.2），**太平洋 = 中途岛海战**（1942.6），都在1942年实现战局翻盘。","mix":"斯大林格勒战役（1942–1943）是苏德战场与二战欧洲战场的根本转折点；诺曼底登陆（1944.6）的意义则是开辟欧洲第二战场，二者常被混考。","mcq":[{"q":"标志着苏德战场和第二次世界大战欧洲战场根本转折的战役是","o":["斯大林格勒战役","莫斯科保卫战","诺曼底登陆","中途岛海战"],"a":0,"w":"1942年7月至1943年2月的斯大林格勒战役是苏德战场和二战欧洲战场的根本转折点。"}],"rel":[{"t":"诺曼底登陆","n":"1944年开辟欧洲第二战场"},{"t":"两次世界大战","n":"二战核心转折战役"},{"t":"中途岛海战与珍珠港事件","n":"太平洋战场转折点对照"}],"more":"关键信息：苏军反攻代号“天王星行动”，德军第6集团军司令保卢斯成为纳粹德国首位被俘元帅。","exam":[]},{"id":"a15-082","t":"诺曼底登陆","cid":"15e","p":2,"kind":"事件","alias":["霸王行动","D日","D-Day","诺曼底战役"],"one":"1944年6月6日盟军登陆法国诺曼底，开辟欧洲第二战场。","ans":"诺曼底登陆发生于**1944年6月6日**，行动代号**“霸王行动”**，是二战中盟军在欧洲西线实施的大规模两栖登陆战。在盟军最高统帅**艾森豪威尔**指挥下，美、英等盟军横渡英吉利海峡，突破“大西洋壁垒”，在**法国诺曼底**抢滩成功。这是人类史上规模最大的两栖登陆，标志着**欧洲第二战场的开辟**，使纳粹德国陷入东西两面夹击，加速其覆灭。","pts":["1944年6月6日，行动代号“霸王行动”","艾森豪威尔指挥美英等盟军登陆法国诺曼底","开辟欧洲第二战场，使德军陷入东西夹击"],"mem":"顺口串联：**1944.6.6**（三个偶数：44、6、6）→ **霸王行动** → **艾森豪威尔** → 横渡英吉利海峡 → **开辟欧洲第二战场**（第一战场是东线苏德战场）。","mix":"诺曼底登陆的意义是“开辟欧洲第二战场”，二战欧洲战场的根本转折点则是1942–1943年的斯大林格勒战役，切勿张冠李戴。","mcq":[{"q":"1944年6月6日盟军发起、代号“霸王行动”并开辟欧洲第二战场的战役是","o":["敦刻尔克大撤退","诺曼底登陆","斯大林格勒战役","柏林战役"],"a":1,"w":"1944年6月6日盟军在法国诺曼底实施“霸王行动”，开辟了欧洲第二战场。"}],"rel":[{"t":"斯大林格勒战役","n":"东线转折与西线开辟呼应"},{"t":"两次世界大战","n":"加速二战欧洲战事终结"},{"t":"英吉利海峡与英法海底隧道","n":"盟军横渡的海峡地理"}],"more":"英文代号：Operation Overlord（霸王行动），登陆当日被称为D-Day。","exam":[]},{"id":"a15-083","t":"中途岛海战与珍珠港事件","cid":"15e","p":3,"kind":"事件","alias":["中途岛海战","偷袭珍珠港"],"one":"1941年12月珍珠港引发太平洋战争，1942年6月中途岛为战场转折。","ans":"珍珠港事件与中途岛海战是**二战太平洋战场**的开端与转折点。**1941年12月7日**日本偷袭美军**珍珠港**，**太平洋战争爆发**，二战达最大规模；**1942年6月**美军在**中途岛海战**击沉日军四艘航母，扭转太平洋攻守态势，加速轴心国溃败。","pts":["1941年12月7日珍珠港事件，太平洋战争爆发","1942年6月中途岛海战，太平洋战场转折点","前者使二战达最大规模，后者扭转太平洋攻守态势"],"mem":"二战三大转折打包记：“欧洲东线斯大林格勒、北非阿拉曼、太平洋中途岛”，全发生在1942年！珍珠港记“41·12·7”偷袭开战，半年后“42·6”中途岛翻盘。","mix":"莫斯科保卫战打破德军“不可战胜”神话，斯大林格勒战役是二战整体与苏德战场的转折点，中途岛海战是太平洋战场的转折点，考试常混淆各自定位。","mcq":[{"q":"第二次世界大战中，标志太平洋战争爆发和成为太平洋战场转折点的事件分别是","o":["珊瑚海海战、诺曼底登陆","珍珠港事件、斯大林格勒战役","莱特湾海战、中途岛海战","珍珠港事件、中途岛海战"],"a":3,"w":"1941年12月7日珍珠港事件引发太平洋战争，1942年6月中途岛海战是太平洋战场转折点。"}],"rel":[{"t":"珍珠港事件","n":"单列事件词条互参"},{"t":"第二次世界大战","n":"二战太平洋战区主线"},{"t":"斯大林格勒战役","n":"同期苏德战场转折点"},{"t":"《联合国家宣言》","n":"珍珠港后促成同盟成立"}],"exam":[]},{"id":"a15-084","t":"滑铁卢战役","cid":"15e","p":3,"kind":"事件","alias":["滑铁卢","遭遇滑铁卢"],"one":"1815年拿破仑在比利时滑铁卢败于英普联军，后喻指决定性失败。","ans":"滑铁卢战役是终结**拿破仑战争**的决定性会战，**1815年6月**发生于**比利时**滑铁卢。百日复辟的法皇**拿破仑**惨败于威灵顿与布吕歇尔统帅的**英普联军**，被流放圣赫勒拿岛。战役奠定维也纳体系，“遭遇滑铁卢”也演变为喻指**彻底失败**的典故。","pts":["1815年6月，拿破仑在比利时滑铁卢败于英普联军","终结拿破仑帝国与百日王朝，被流放圣赫勒拿岛","后衍生为“遭遇滑铁卢”，喻指决定性失败"],"mem":"记住两个流放岛与一个地名：滑铁卢不在法国在比利时；拿破仑第一次退位去地中海厄尔巴岛（还能溜回来），滑铁卢大败后被送到遥远大西洋圣赫勒拿岛（彻底终结）。","mix":"滑铁卢位于今比利时境内，而非法国或英国；击败拿破仑的是英国威灵顿公爵与普鲁士布吕歇尔的英普联军，并非单一英军。","mcq":[{"q":"1815年终结拿破仑军事生涯、并衍生出“决定性失败”典故的滑铁卢战役发生在今","o":["法国","比利时","奥地利","德国"],"a":1,"w":"滑铁卢位于今比利时布鲁塞尔以南，1815年6月18日拿破仑在此败于英普联军。"}],"rel":[{"t":"拿破仑","n":"战役法方核心统帅"},{"t":"法国大革命","n":"拿破仑时代历史源头"},{"t":"维也纳体系","n":"战后欧洲秩序重建"},{"t":"《拿破仑法典》","n":"拿破仑留下的法治遗产"}],"exam":[]},{"id":"a15-085","t":"《不扩散核武器条约》","cid":"15e","p":3,"kind":"制度","alias":["NPT","核不扩散条约"],"one":"1968年签署的国际核军控基石，承认美俄英法中五国为有核国。","ans":"《不扩散核武器条约》简称**NPT**，是国际核军控体系的基石性多边条约。**1968年**签署、1970年生效，确立**防扩散、核裁军、和平利用核能**三大支柱，承认**美、苏（俄）、英、法、中**五国为有核国。中国**1992年**加入，维护全球战略稳定。","pts":["简称NPT，1968年签署、1970年生效","承认美、苏（俄）、英、法、中五个有核国家","防扩散、核裁军、和平利用核能；中国1992年加入"],"mem":"五核国恰好就是联合国安理会五个常任理事国（五常）！记住条约时间线：“68签、70效、92中国加入”（与《伯尔尼公约》同年加入），三大支柱记“防、裁、用”。","mix":"印度、巴基斯坦、以色列未加入《不扩散核武器条约》，朝鲜于2003年宣布退出；条约承认的有核国以1967年1月1日前制造并爆炸核装置为界。","mcq":[{"q":"1968年签署的《不扩散核武器条约》（NPT）承认的五个有核武器国家是","o":["美、苏（俄）、英、法、中","美、俄、英、法、印","美、俄、中、印、巴","美、英、法、德、日"],"a":0,"w":"条约承认1967年前完成核试验的美、苏（俄）、英、法、中五国为有核武器国家，与安理会五常一致。"}],"rel":[{"t":"联合国安理会与五个常任理事国","n":"五常与五核国一致"},{"t":"“两弹一星”功勋科学家","n":"中国核威慑奠基背景"},{"t":"《伯尔尼公约》","n":"中国同于1992年加入"},{"t":"冷战","n":"条约签署的国际背景"}],"exam":[]},{"id":"a15-086","t":"全民国防教育日","cid":"15e","p":3,"kind":"常识","alias":["国防教育日"],"one":"2001年立法设立，定于每年9月的第三个星期六，普及国防观念。","ans":"全民国防教育日是我国立法设立的**群众性国防教育专题节日**。**2001年**全国人大常委会决定将每年**9月的第三个星期六**定为该日，各地多开展**防空警报试鸣**与国防宣传。**2024年9月**新修订**《国防教育法》**施行，强化全民国防法治保障。","pts":["2001年设立，每年9月第三个星期六","开展防空警报试鸣与群众性国防宣传","2024年9月新修订《国防教育法》施行"],"mem":"巧记时间：“九·一八”事变在9月中旬，选在紧邻的“9月第三个星期六”既能避开工作日便于全民参与，又紧扣铭记历史、居安思危的国防主题（如上海当日通常试鸣防空警报）。","mix":"易与4月15日全民国家安全教育日、9月3日抗战胜利纪念日、9月30日烈士纪念日混淆；该日无固定阳历日期，随每年9月日历浮动。","mcq":[{"q":"2001年经全国人大常委会决定设立的我国“全民国防教育日”是每年的","o":["4月15日","8月1日","9月第三个星期六","9月18日"],"a":2,"w":"2001年8月31日全国人大常委会决定将每年9月的第三个星期六定为全民国防教育日。"}],"rel":[{"t":"《国家安全法》","n":"4月15日国安教育日对照"},{"t":"国家纪念日","n":"国家级专题纪念日同簇"},{"t":"中国武装力量的构成","n":"国防教育核心常识"},{"t":"《爱国主义教育法》","n":"国防与爱国教育呼应"}],"exam":[]},{"id":"a15-087","t":"军队编制序列","cid":"15e","p":3,"kind":"常识","alias":["军师旅团营连排班","三三制编制"],"one":"现代陆军常见建制由大到小为军、师、旅、团、营、连、排、班。","ans":"军队编制序列是武装力量自上而下划分作战层级的**组织建制体系**。我国陆军传统序列由大到小一般为**军、师、旅、团、营、连、排、班**八级。2015年军改后普遍推进**“师改旅”**，形成**集团军、合成旅、合成营**的高效联合作战指挥链条。","pts":["由大到小一般为军、师、旅、团、营、连、排、班","军改推进“师改旅”，向合成旅与合成营转型","与军衔制度配合构成军队指挥体系"],"mem":"顺口溜八字诀：“军师旅团，营连排班”，前四个是大中级作战单位（军师旅团），后四个是基层连队单位（营连排班）；军改后记“省掉师团，集团军直管合成旅”。","mix":"“旅”介于“师”与“团”之间，部分人易将“旅”误排在“团”之后；编制序列讲部队建制规模，军衔“三等十级”讲军官个人等级，二者对应而非等同。","mcq":[{"q":"按照现代陆军由大到小的通行编制序列，排列完全正确的一项是","o":["军、师、团、旅、营、连、排、班","军、旅、师、团、营、连、排、班","军、师、旅、团、连、营、排、班","军、师、旅、团、营、连、排、班"],"a":3,"w":"军队编制由大到小通行序列为军、师、旅、团、营、连、排、班，旅在师与团之间。"}],"rel":[{"t":"军衔“三等十级”","n":"军官等级与编制呼应"},{"t":"五大战区","n":"战区主战高层指挥体制"},{"t":"四个军种","n":"军兵种建制同簇"},{"t":"军委管总、战区主战、军种主建","n":"军改后指挥体系"}],"exam":[]},{"id":"a15-088","t":"顾拜旦与国际奥委会","cid":"15f","p":2,"kind":"人物","alias":["顾拜旦","现代奥林匹克之父","国际奥委会","IOC"],"one":"法国顾拜旦倡议1894年成立国际奥委会，总部现设瑞士洛桑。","ans":"皮埃尔·德·顾拜旦（1863–1937）是**法国教育家**，被誉为**“现代奥林匹克之父”**。在他倡议下，**1894年6月23日**巴黎国际体育会议成立**国际奥林匹克委员会（IOC）**，决定复兴古代奥运会。首任主席为希腊人**维凯拉斯**，顾拜旦继任并于**1915年将总部迁至瑞士洛桑**。他还设计五环标志，奠定了现代奥林匹克运动的制度与精神基石。","pts":["法国顾拜旦被誉为“现代奥林匹克之父”","1894年6月23日巴黎成立国际奥委会","首任主席维凯拉斯，1915年总部迁至瑞士洛桑"],"mem":"记住两个常考反转：①顾拜旦是**法国人**（不是希腊人），且是**第二任**主席（首任为希腊人维凯拉斯）；②**1894巴黎**成立，**1915迁至瑞士洛桑**（“奥林匹克之都”）。","mix":"常见干扰项有两个：把国际奥委会总部误记为瑞士日内瓦或法国巴黎（实为瑞士洛桑）；把顾拜旦误当成国际奥委会首任主席（首任是希腊文学家维凯拉斯，1894–1896）。","mcq":[{"q":"关于“现代奥林匹克之父”顾拜旦与国际奥委会，下列说法正确的是","o":["顾拜旦是希腊人，任首任国际奥委会主席","国际奥委会于1896年在雅典正式成立","国际奥委会于1894年成立，总部现设瑞士洛桑","国际奥委会总部一直设在瑞士日内瓦"],"a":2,"w":"法国人顾拜旦倡议于1894年6月23日在巴黎成立国际奥委会，1915年总部迁至瑞士洛桑。"}],"rel":[{"t":"第一届现代奥运会","n":"1896年雅典落地复兴"},{"t":"奥林匹克五环与格言","n":"顾拜旦1913年设计五环"},{"t":"奥林匹克运动会","n":"国际奥委会领导的赛事"}],"more":"关键日期：1894年6月23日成立（6月23日为国际奥林匹克日）；1915年总部迁往“奥林匹克之都”洛桑。","exam":[]},{"id":"a15-089","t":"第一届现代奥运会","cid":"15f","p":2,"kind":"事件","alias":["1896年雅典奥运会","首届现代奥运会"],"one":"1896年4月在希腊雅典举行，2026年为其举办130周年。","ans":"第一届现代奥林匹克运动会于**1896年4月6日至15日**在奥运发源地**希腊雅典**举行，由**顾拜旦**倡议推动、国际奥委会主办。共有**14个国家241名运动员**参赛，美国三级跳远选手**詹姆斯·康诺利**成为**第一位现代奥运会冠军**。本届赛事成功复兴了始于公元前776年的古代奥运传统，开启现代全球体育盛会，**2026年正值其举办130周年**。","pts":["1896年4月6日至15日在希腊雅典举行","14国241名运动员参赛，康诺利夺现代首冠","复兴古代奥运传统，2026年正值130周年"],"mem":"年份与周年锚定：**前776年**古代奥运起点 → **1894年巴黎**建IOC → **1896年雅典**办第一届现代奥运 → **2026年正好130周年**。","mix":"1894年是国际奥委会成立年份（巴黎），1896年才是第一届现代奥运会举办年份（雅典）；古代奥运会始于公元前776年，393年被罗马皇帝狄奥多西一世废除。","mcq":[{"q":"2026年正值第一届现代奥运会举办130周年，该届奥运会于1896年4月举办于","o":["法国巴黎","希腊雅典","瑞士洛桑","英国伦敦"],"a":1,"w":"1896年4月6日至15日，第一届现代奥运会在希腊雅典举行；1894年国际奥委会成立于巴黎。"}],"rel":[{"t":"顾拜旦与国际奥委会","n":"赛事发起人与主办机构"},{"t":"奥林匹克五环与格言","n":"现代奥运核心标志与精神"},{"t":"奥林匹克运动会","n":"现代奥运体系的起点"},{"t":"雅典民主","n":"同源古希腊雅典文明"}],"more":"2026年周年节点：1896年第一届现代奥运会举办130周年。首届现代奥运冠军：美国选手詹姆斯·康诺利（三级跳远）。","exam":[]},{"id":"a15-090","t":"奥林匹克五环与格言","cid":"15f","p":2,"kind":"常识","alias":["奥运五环","奥林匹克格言","奥林匹克标志"],"one":"蓝黄黑绿红五环象征五大洲团结，格言2021年增入“更团结”。","ans":"奥林匹克五环与格言是**现代奥林匹克的核心标志与精神信条**。五环由**顾拜旦1913年设计**，1920年安特卫普奥运首升五环旗，**蓝、黄、黑、绿、红**五环相扣，象征**五大洲团结**与运动员相聚。格言原为**“更快、更高、更强”**，**2021年7月20日**国际奥委会第138次全会加入**“更团结”**，为108年来首次修改，彰显全球协作精神。","pts":["蓝黄黑绿红五环由顾拜旦设计，象征五大洲团结","原格言“更快、更高、更强”，2021年增“更团结”","1920年安特卫普首升五环旗，2021年首次改格言"],"mem":"五环排列记：**上三环“蓝、黑、红”，下两环“黄、绿”**。格言记“3+1”：原“快高强”三词，2021年东京奥运前夕加“更团结”，108年来首次修改。","mix":"国际奥委会官方规定五环整体象征五大洲团结，任何单一颜色并不固定对应某一大洲（尽管民间常流传对应说法）；原格言由顾拜旦好友迪东提出，2021年由巴赫提议加入“更团结”。","mcq":[{"q":"2021年7月国际奥委会第138次全会表决通过，在原有奥林匹克格言“更快、更高、更强”之后加入的是","o":["更和平","更友好","更包容","更团结"],"a":3,"w":"2021年7月20日，国际奥委会正式在格言中加入“更团结”（Together，拉丁语Communiter）。"}],"rel":[{"t":"顾拜旦与国际奥委会","n":"五环设计者与格言修订机构"},{"t":"第一届现代奥运会","n":"现代奥运的开端"},{"t":"“双奥之城”","n":"北京冬奥践行“更团结”"}],"more":"拉丁语格言：Citius, Altius, Fortius - Communiter（更快、更高、更强、更团结）。五环旗首次升起：1920年安特卫普奥运会。","exam":[]},{"id":"a15-091","t":"杨扬","cid":"15f","p":2,"kind":"人物","alias":["大杨扬","中国冬奥首金"],"one":"2002年盐湖城冬奥短道速滑500米夺冠，中国冬奥首枚金牌。","ans":"杨扬（人称“大杨扬”）是**中国著名女子短道速滑运动员**。**2002年2月16日**，在美国**盐湖城第19届冬奥会**短道速滑**女子500米**决赛中，她以44秒187夺冠，为**中国实现冬奥会金牌“零的突破”**，拿下中国首枚冬奥金牌。同届她再夺**女子1000米金牌**和3000米接力银牌。她与夏奥首金得主**许海峰**成对载入史册，标志中国冰雪迈上新台阶。","pts":["2002年盐湖城冬奥会短道速滑女子500米冠军","实现中国冬奥会金牌“零的突破”","同届再夺女子1000米金牌，与许海峰夏奥首金成对"],"mem":"中国奥运首金双璧配对：**夏奥首金 = 1984洛杉矶·许海峰（射击）**；**冬奥首金 = 2002盐湖城·杨扬（短道速滑500米）**。巧记：两个“杨”字成双，她在盐湖城正好独揽两金（500米+1000米）。","mix":"同队另有“小杨阳”（阳字无提手旁），中国冬奥首金得主是“大杨扬”（扬字有提手旁）；莫将杨扬的冬奥首金与许海峰1984年夏奥首金混淆。","mcq":[{"q":"2002年盐湖城冬奥会上，为中国实现冬奥会金牌“零的突破”的运动员和项目是","o":["叶乔波、速度滑冰","王濛、短道速滑女子500米","杨扬、短道速滑女子500米","申雪赵宏博、花样滑冰"],"a":2,"w":"2002年2月16日，杨扬在盐湖城冬奥会短道速滑女子500米决赛夺冠，拿下中国冬奥会首枚金牌。"}],"rel":[{"t":"许海峰","n":"夏奥首金与冬奥首金成对"},{"t":"“双奥之城”","n":"中国冰雪运动的延续高峰"},{"t":"2026年米兰—科尔蒂纳丹佩佐冬奥会","n":"最新一届冬奥赛事"}],"more":"关键日期：2002年2月16日，第19届盐湖城冬奥会，女子500米夺冠成绩44秒187。","exam":[]},{"id":"a15-092","t":"中国女排与女排精神","cid":"15f","p":2,"kind":"事件","alias":["女排精神","中国女排五连冠","铁榔头"],"one":"1981至1986年夺世界大赛五连冠，铸就顽强拼搏的女排精神。","ans":"中国女排是**中国三大球率先夺世界冠军的队伍**。**1981至1986年**，在**袁伟民**等教练带领下，中国女排连夺1981世界杯、1982世锦赛、1984洛杉矶奥运、1985世界杯、1986世锦赛冠军，成就**“五连冠”**。主力**郎平**后任主教练，并于**2016年里约奥运会**率队逆转夺冠。她们铸就团结协作、顽强拼搏的**女排精神**，激励了数代国人。","pts":["1981至1986年连夺世界杯、世锦赛、奥运五连冠","袁伟民奠基，郎平任主力与2016里约夺冠主帅","铸就无私奉献、团结协作、顽强拼搏的女排精神"],"mem":"五连冠按赛制轮转记：**81世界杯→82世锦赛→84奥运→85世界杯→86世锦赛**（中间只空83年，三大赛轮流夺冠）。2026年正好是1986年成就五连冠40周年。","mix":"1981年女排世界杯冠军是中国“三大球”第一个世界冠军，新中国体育史上第一个世界冠军则是1959年乒乓球的容国团；郎平既以球员身份获1984奥运冠军，又以主教练身份率队夺2016里约奥运冠军。","mcq":[{"q":"1981至1986年中国女排在世界排球三大赛中实现“五连冠”，其中首夺奥运金牌是在","o":["1984年洛杉矶奥运会","1988年汉城奥运会","2004年雅典奥运会","2016年里约奥运会"],"a":0,"w":"中国女排在1984年洛杉矶奥运会决赛3:0胜美国首夺奥运金牌，完成三连冠，此后连夺1985世界杯、1986世锦赛实现五连冠。"}],"rel":[{"t":"许海峰","n":"同在1984洛杉矶奥运创辉煌"},{"t":"容国团","n":"中国体育拼搏精神先驱"},{"t":"社会主义核心价值观","n":"时代精神谱系组成部分"}],"more":"2026年周年节点：1986年中国女排实现五连冠40周年。2016年里约奥运会决赛，郎平率队3:1逆转塞尔维亚夺冠。","exam":[]},{"id":"a15-093","t":"刘翔与李娜","cid":"15f","p":3,"kind":"人物","alias":["刘翔","李娜"],"one":"刘翔2004年雅典奥运110米栏夺冠，李娜2011年首夺网球大满贯单打。","ans":"刘翔与李娜是在国际主流体育项目实现**亚洲历史突破**的中国代表选手。**刘翔**在**2004年雅典奥运会**男子110米栏平世界纪录夺冠；**李娜**于**2011年法网**夺得女单桂冠，成为首位获**网球大满贯单打冠军**的亚洲球员，扩大了中国体育国际影响。","pts":["刘翔：2004年雅典奥运男子110米栏夺冠并平纪录","李娜：2011年法网夺冠，亚洲首位大满贯单打冠军","二人均在欧美主导的主流项目实现亚洲突破"],"mem":"两串年份配地名：“04雅典刘翔飞跃110米栏，11巴黎法网李娜红土封后”，顺带记刘翔还曾创12秒88世界纪录、李娜2014年再夺澳网并入选国际网球名人堂。","mix":"首位获得网球大满贯单打冠军的亚洲球员是李娜（2011年法网），首位获得奥运网球单打金牌的中国球员是郑钦文（2024年巴黎奥运会）；刘翔夺冠是在2004年雅典而非2008年北京。","mcq":[{"q":"2011年成为历史上首位夺得网球大满贯单打冠军的亚洲球员及所夺赛事是","o":["李娜，法国网球公开赛","李娜，温布尔登网球锦标赛","郑钦文，澳大利亚网球公开赛","李娜，美国网球公开赛"],"a":0,"w":"李娜于2011年6月夺得法国网球公开赛女单冠军，成为亚洲首位网球大满贯单打冠军。"}],"rel":[{"t":"网球四大满贯","n":"李娜夺法网与澳网冠军"},{"t":"许海峰","n":"中国奥运首金里程碑"},{"t":"中国女排与女排精神","n":"中国体坛拼搏精神对照"},{"t":"容国团","n":"新中国首位世界冠军"}],"exam":[]},{"id":"a15-094","t":"网球四大满贯","cid":"15f","p":3,"kind":"合称","alias":["四大满贯","澳网法网温网美网"],"one":"澳网、法网（红土）、温网（草地）、美网，世界职业网球最高赛事。","ans":"网球四大满贯是国际职业网坛级别最高的四项年度顶级赛事合称。按举办次序为**澳网**（硬地）、**法网（红土）**、**温网（草地）**和**美网**（硬地）。其中1877年创办的**温网历史最悠久**，集齐四冠称“全满贯”，代表网球至高荣誉。","pts":["按时间序：澳网、法网、温网、美网","场地特征：法网红土、温网草地、澳网美网硬地","温网创办于1877年，历史最悠久"],"members":[["澳大利亚网球公开赛","简称澳网，1月墨尔本举办，硬地赛场"],["法国网球公开赛","简称法网，5至6月巴黎举办，红土赛场"],["温布尔登网球锦标赛","简称温网，6至7月伦敦举办，草地赛场，1877年创办最悠久"],["美国网球公开赛","简称美网，8至9月纽约举办，硬地赛场"]],"mem":"口诀“澳法温美，硬红草硬”：按四季顺序排，1月南半球夏天澳网（硬）、春末法网（红土浪漫巴黎）、仲夏温网（英伦草地白衣）、秋初美网（硬地压轴）。","mix":"同一年囊括四大满贯称“年度全满贯”，职业生涯集齐称“生涯全满贯”，若再加上奥运会单打金牌则称“金满贯”；法网是四大满贯中唯一的红土赛事，温网是唯一的草地赛事。","mcq":[{"q":"网球四大满贯中，唯一采用红土场地和历史最悠久且采用草地场地的赛事分别是","o":["澳网、美网","法网、温网","温网、法网","美网、温网"],"a":1,"w":"法网是唯一的红土大满贯，1877年创办的温网历史最久且是唯一的草地大满贯。"}],"rel":[{"t":"刘翔与李娜","n":"李娜夺法网与澳网单打"},{"t":"奥林匹克运动会","n":"叠加大满贯成金满贯"},{"t":"国际足联世界杯","n":"全球顶级单项赛事对照"}],"exam":[]},{"id":"a15-095","t":"国际足联世界杯","cid":"15f","p":3,"kind":"常识","alias":["世界杯","FIFA世界杯","大力神杯"],"one":"1930年乌拉圭首办，四年一届；中国男足2002年首进决赛圈。","ans":"国际足联世界杯是世界最高级别国家队足球赛，四年一届，与奥运会并称全球两大体育盛会。**1930年**首届在**乌拉圭**举办，巴西五冠居首；中国男足**2002年**首进决赛圈。**2026年美加墨世界杯**首次扩军至**48队**，西班牙队夺冠。","pts":["1930年乌拉圭首办，四年一届，巴西五冠居首","中国男足2002年韩日世界杯首次晋级决赛圈","2026年美加墨世界杯扩至48队，西班牙夺冠"],"mem":"三组数字串联：“1930乌拉圭起点（记住首届在南美）→2002韩日中国首进决赛圈→2026美加墨扩军48队西班牙加时夺冠”；奖杯记“前雷米特杯、现大力神杯”。","mix":"1970年巴西三次夺冠后永久保留雷米特杯，1974年起改颁大力神杯且不再永久归属任何国家；世界杯始于1930年，晚于1896年首届现代奥运会。","mcq":[{"q":"关于国际足联世界杯历史，下列陈述准确的一项是","o":["首届世界杯于1896年在英国举办","中国男足于1998年法国世界杯首次晋级决赛圈","首届世界杯1930年在乌拉圭举办，中国男足2002年首次进决赛圈","2026年美加墨世界杯沿用32支球队赛制"],"a":2,"w":"1930年首届世界杯在乌拉圭举办，中国男足2002年首次进入决赛圈，2026年扩军至48队。"}],"rel":[{"t":"2026年美加墨世界杯","n":"最新一届扩军至48队"},{"t":"奥林匹克运动会","n":"全球两大顶级体育盛会"},{"t":"网球四大满贯","n":"世界主流职业体育同簇"}],"exam":[]},{"id":"a15-096","t":"马拉松","cid":"15f","p":3,"kind":"常识","alias":["马拉松赛跑","全程马拉松"],"one":"源于前490年马拉松战役报捷传说，标准赛程为42.195千米。","ans":"马拉松是国际标准长跑项目，源于**公元前490年**希波战争**马拉松战役**士兵跑回雅典报捷传说。**1896年**首届现代奥运会列入正式项目，1908年伦敦奥运定下**42.195千米**距离（1921年确立标准），象征极限耐力并喻指持久进程。","pts":["源于公元前490年马拉松战役士兵报捷传说","1896年首届现代奥运会列入正式比赛项目","标准距离42.195千米，定型于1908年伦敦奥运"],"mem":"数字趣记：“42.195千米”来自1908年伦敦奥运从温莎城堡跑到白城体育场皇家包厢的实测距离；谐音记“前490（试就灵）跑回雅典，全马42.195”。","mix":"马拉松战役属希波战争（希腊对抗波斯），而非伯罗奔尼撒战争（雅典对抗斯巴达）；半程马拉松标准距离为21.0975千米，切勿与全马42.195千米混淆。","mcq":[{"q":"现代马拉松运动起源于哪场古代战争中的战役传说，其标准全程距离是多少","o":["伯罗奔尼撒战争，40千米","特洛伊战争，42.195千米","布匿战争，21.0975千米","希波战争，42.195千米"],"a":3,"w":"马拉松源于公元前490年希波战争马拉松战役的报捷传说，全程标准距离为42.195千米。"}],"rel":[{"t":"马拉松战役","n":"项目名称与典故来源"},{"t":"希波战争","n":"马拉松战役所属战争"},{"t":"第一届现代奥运会","n":"1896年首列正式项目"},{"t":"奥林匹克五环与格言","n":"体育耐力精神呼应"}],"exam":[]},{"id":"a15-097","t":"牛顿与经典力学","cid":"15g","p":2,"kind":"人物","alias":["牛顿","经典力学","牛顿力学","自然哲学的数学原理"],"one":"英国物理学家，1687年著《原理》提出三大运动定律与万有引力。","ans":"艾萨克·牛顿（1643–1727）是**英国物理学家与数学家**，**经典力学奠基人**。**1687年**，他出版**《自然哲学的数学原理》**，提出**三大运动定律**（惯性、加速度、作用与反作用）和**万有引力定律**，首次以统一数学框架解释天体与地面物体运动。他独立发明**微积分**，揭示日光分光。牛顿力学宣告近代自然科学成熟，奠定宏观低速物理基石。","pts":["英国科学家（1643–1727），经典力学奠基人","1687年《原理》提出三大运动定律与万有引力","独立发明微积分与日光分光，标志近代科学成熟"],"mem":"三大定律简记：**一惯性、二公式（F=ma）、三反作用**；加**万有引力**，全装进1687年《自然哲学的数学原理》，实现“天上行星与地上苹果”的大统一。","mix":"牛顿经典力学适用于宏观、低速领域，高速运动需由爱因斯坦相对论修正；微积分由牛顿与莱布尼茨各自独立创立，并非牛顿一人独占。","mcq":[{"q":"1687年出版、系统提出三大运动定律和万有引力定律的科学巨著是","o":["哥白尼《天体运行论》","牛顿《自然哲学的数学原理》","达尔文《物种起源》","伽利略《关于两大世界体系的对话》"],"a":1,"w":"英国科学家牛顿于1687年出版《自然哲学的数学原理》，建立经典力学体系。"}],"rel":[{"t":"爱因斯坦与相对论","n":"现代物理对经典力学的拓展"},{"t":"伽利略","n":"近代实验物理先驱，牛顿前辈"},{"t":"斯宾诺莎与莱布尼茨","n":"莱布尼茨与牛顿同创微积分"},{"t":"达尔文与进化论","n":"科学史“之父”并举"}],"more":"关键年份：1687年《自然哲学的数学原理》（简称《原理》）出版，奠定经典力学体系。","exam":[]},{"id":"a15-098","t":"爱因斯坦与相对论","cid":"15g","p":2,"kind":"人物","alias":["爱因斯坦","相对论","狭义相对论","广义相对论","质能方程"],"one":"现代物理学奠基人，创立相对论；1921年诺奖因光电效应而非相对论。","ans":"阿尔伯特·爱因斯坦（1879–1955）是**德裔理论物理学家**，现代物理学奠基人之一。他于**1905年**提出**狭义相对论**与**质能方程**（E=mc²），**1915年**建立**广义相对论**，以时空弯曲解释引力。他凭**光电效应定律**获**1921年诺贝尔物理学奖**，授奖理由不含相对论。相对论突破经典力学框架，奠基核能利用、宇宙学与卫星导航。","pts":["1905狭义相对论与质能方程，1915广义相对论","1921年诺贝尔物理学奖因光电效应定律","突破牛顿经典力学，奠基现代物理学"],"mem":"时间与考点口诀：“05狭义、15广义、21光电拿诺奖”。记住“相对论没拿奖，光电效应拿了奖”，这是科学史选择题最高频的反转陷阱。","mix":"常见干扰项是“爱因斯坦因相对论获1921年诺贝尔物理学奖”；当年诺奖于1922年补颁，核心理由是光电效应定律及对理论物理学的贡献。","mcq":[{"q":"爱因斯坦获得1921年诺贝尔物理学奖的主要授奖理由是","o":["提出狭义相对论","建立广义相对论","发现光电效应定律","提出万有引力定律"],"a":2,"w":"爱因斯坦获1921年诺贝尔物理学奖的理由是对理论物理学的贡献，尤其是发现光电效应定律。"}],"rel":[{"t":"牛顿与经典力学","n":"经典与现代物理对照"},{"t":"诺贝尔奖","n":"1921年物理学奖得主"},{"t":"量子科技","n":"光电效应奠基量子论"}],"more":"1905年被称为爱因斯坦“奇迹年”，同年发表光电效应、布朗运动、狭义相对论与质能等价四篇论文。","exam":[]},{"id":"a15-099","t":"门捷列夫与元素周期表","cid":"15g","p":2,"kind":"人物","alias":["门捷列夫","元素周期表","元素周期律"],"one":"俄国化学家门捷列夫1869年发表元素周期表，并预言未知元素。","ans":"门捷列夫（1834–1907）是**俄国化学家**，元素周期律发现者。他在**1869年**发表首张**元素周期表**，按**相对原子质量**递增排列元素，揭示其性质呈周期性变化，并大胆留出空位准确预言镓、锗等新元素。该表使化学研究走向系统化，现代周期表则按**原子序数**（质子数）排列，是整个化学学科的核心工具。","pts":["俄国化学家，1869年发表元素周期表","按相对原子质量排列，留空位预言新元素","现代周期表改按原子序数排列"],"mem":"画面记忆：1869年门捷列夫像拼图高手，把已知元素按体重（相对原子质量）排好，故意留出空格并精准预言“缺的拼图长什么样”。","mix":"门捷列夫1869年按“相对原子质量”排表，而1913年莫塞莱之后现代周期表按“原子序数（质子数）”排列，二者切勿混淆。","mcq":[{"q":"1869年发表元素周期表并成功预言未知元素性质的俄国化学家是","o":["门捷列夫","拉瓦锡","道尔顿","居里夫人"],"a":0,"w":"俄国化学家门捷列夫于1869年发表元素周期表。"}],"rel":[{"t":"门捷列夫国际基础科学奖","n":"以他命名的国际奖项"},{"t":"达尔文与进化论","n":"19世纪科学发现同期"},{"t":"牛顿与经典力学","n":"近代自然科学奠基人"}],"more":"联合国大会曾宣布2019年为“国际化学元素周期表年”，纪念门捷列夫发表周期表150周年。","exam":[]},{"id":"a15-100","t":"达尔文与进化论","cid":"15g","p":2,"kind":"人物","alias":["达尔文","进化论","物种起源","自然选择"],"one":"英国博物学家达尔文1859年出版《物种起源》，提出自然选择学说。","ans":"达尔文（1809–1882）是**英国博物学家**，现代生物进化论奠基人。他在随“贝格尔号”环球考察后，于**1859年**出版**《物种起源》**，提出以**自然选择**为核心的进化论，主张生物在生存斗争中适者生存。清末**严复**据赫胥黎《进化论与伦理学》译成**《天演论》**，引入“物竞天择”思想，有力推动维新变法与近代思想启蒙。","pts":["英国博物学家，1859年出版《物种起源》","核心主张：自然选择、适者生存","严复据赫胥黎著作译《天演论》传入中国"],"mem":"逻辑链：坐“贝格尔号”看遍物种→1859写《物种起源》讲自然选择→赫胥黎写《进化论与伦理学》→严复译成《天演论》震撼中国。","mix":"《天演论》的原著是英国学者赫胥黎的《进化论与伦理学》，并非直接翻译达尔文的《物种起源》；“用进废退”是法国拉马克的观点，属于常见干扰项。","mcq":[{"q":"清末严复译成《天演论》以宣传进化思想，其所依据的原著作者是","o":["达尔文","拉马克","孟德尔","赫胥黎"],"a":3,"w":"严复据赫胥黎的《进化论与伦理学》译成《天演论》，而非直译《物种起源》。"}],"rel":[{"t":"严复","n":"借《天演论》传播进化论"},{"t":"《天演论》","n":"进化论传入中国的名译"},{"t":"孟德尔与DNA双螺旋","n":"补充进化论的遗传机制"}],"more":"恩格斯将细胞学说、能量守恒与转化定律、达尔文生物进化论并称为“19世纪自然科学的三大发现”。","exam":[]},{"id":"a15-101","t":"孟德尔与DNA双螺旋","cid":"15g","p":2,"kind":"事件","alias":["孟德尔","遗传学之父","DNA双螺旋","沃森和克里克"],"one":"孟德尔借豌豆实验创立遗传定律；1953年沃森、克里克提出DNA双螺旋模型。","ans":"孟德尔遗传定律与DNA双螺旋是**现代遗传学与分子生物学的两大里程碑**。奥地利学者**孟德尔**通过**豌豆杂交实验**提出**遗传定律**（分离定律与自由组合定律），被称为**“遗传学之父”**。**1953年**，**沃森和克里克**结合富兰克林等人的X射线衍射数据，提出**DNA双螺旋结构模型**。两项发现先后阐明遗传规律与分子载体，开启基因时代。","pts":["孟德尔做豌豆杂交实验，称“遗传学之父”","1953年沃森和克里克提出DNA双螺旋模型","奠定现代遗传学与分子生物学基础"],"mem":"对比记两人与两物：19世纪“修道院种豌豆”的是孟德尔（遗传学之父）；1953年“搭双螺旋积木”的是沃森和克里克（沃克组合）。","mix":"1962年诺贝尔生理学或医学奖授予沃森、克里克与威尔金斯三人，提供关键X射线衍射图谱的富兰克林因已于1958年病逝未获奖。孟德尔实验材料是豌豆，果蝇实验代表人物是摩尔根。","mcq":[{"q":"通过豌豆杂交实验提出遗传定律、被称为“遗传学之父”的科学家是","o":["达尔文","孟德尔","摩尔根","沃森"],"a":1,"w":"奥地利学者孟德尔通过豌豆杂交实验提出遗传定律，被誉为“遗传学之父”。"}],"rel":[{"t":"达尔文与进化论","n":"进化论与遗传学互补"},{"t":"克隆羊多莉","n":"现代遗传技术应用"},{"t":"人工合成牛胰岛素","n":"中国分子生物学里程碑"}],"more":"孟德尔论文《植物杂交实验》发表于1866年，2026年正值发表160周年。","exam":[]},{"id":"a15-102","t":"青霉素与疫苗","cid":"15g","p":2,"kind":"事件","alias":["青霉素","弗莱明","盘尼西林","琴纳","牛痘疫苗"],"one":"1928年弗莱明发现首个抗生素青霉素；1796年琴纳种牛痘开创免疫学。","ans":"青霉素与牛痘疫苗是**现代医学抗击传染病的两大里程碑**。**1796年**，英国医生**琴纳**用**牛痘接种**预防天花，开创**免疫学**，1980年世卫组织宣布全球根除天花。**1928年**，英国细菌学家**弗莱明**发现**青霉素**（盘尼西林），后经弗洛里、钱恩量产，成为人类首个广泛应用抗生素。二者从预防与治疗两端大幅降低了感染病死亡率。","pts":["1796年英国琴纳种牛痘防天花，开创免疫学","1928年英国弗莱明发现首个抗生素青霉素","分别奠基疫苗预防与抗生素治疗"],"mem":"谐音+时间锚点：“1796琴纳牵牛（牛痘）防天花；1928弗莱明发霉（青霉菌）得青霉素”。记住：抗生素杀细菌，对病毒无效；疫苗重在事前预防。","mix":"青霉素由弗莱明发现，但临床提纯量产归功于弗洛里与钱恩，三人共获1945年诺贝尔生理学或医学奖。另注意区别巴斯德（狂犬病疫苗、巴氏消毒法）与琴纳（牛痘预防天花）。","mcq":[{"q":"1928年发现青霉素、开启抗生素时代的英国细菌学家是","o":["琴纳","巴斯德","弗莱明","科赫"],"a":2,"w":"英国科学家弗莱明于1928年发现青霉素；琴纳发明牛痘疫苗，巴斯德研制狂犬病疫苗。"}],"rel":[{"t":"屠呦呦与青蒿素","n":"中国原创抗感染药物"},{"t":"诺贝尔奖","n":"弗莱明等获1945年奖"},{"t":"ABO血型","n":"近代医学重大发现"}],"more":"1796年琴纳首次实施牛痘接种，2026年正值230周年。","exam":[]},{"id":"a15-103","t":"维生素缺乏症","cid":"15g","p":2,"kind":"常识","alias":["维生素缺乏","夜盲症","坏血病","脚气病","佝偻病"],"one":"缺A夜盲、缺B1脚气病、缺C坏血病、缺D佝偻病，生活常识高频考点。","ans":"维生素缺乏症指**人体长期摄入或吸收某种维生素不足所致的营养缺乏病**，属基础医学与生活常识。常见四种对应为：**缺维生素A**易患夜盲症；**缺维生素B1**（硫胺素）易患脚气病；**缺维生素C**易患坏血病，表现为牙龈出血；**缺维生素D**影响钙吸收，儿童易患**佝偻病**、成人易患骨软化症。准确识别对应关系是合理膳食与疾病预防的基础。","pts":["缺A夜盲症，缺B1脚气病","缺C坏血病，缺D儿童佝偻病","脚气病属营养缺乏，不同于真菌性足癣"],"mem":"顺口溜：“A眼（夜盲）B脚（脚气病）C牙（坏血病）D骨（佝偻病）”。从头到脚记身体部位：眼睛→脚→牙龈→骨骼，字母A、B、C、D刚好一一对应。","mix":"易混点：缺维生素B1导致的“脚气病”会损伤神经与心血管，与真菌感染引起的“脚气（足癣）”完全不同；补钙需配合维生素D促进吸收，晒太阳可促使皮肤合成维生素D。","mcq":[{"q":"历史上远洋水手因长期缺乏新鲜蔬果而易患坏血病，主要是因为体内缺乏","o":["维生素C","维生素A","维生素B1","维生素D"],"a":0,"w":"坏血病由缺乏维生素C引起；缺A致夜盲症，缺B1致脚气病，缺D致佝偻病。"}],"rel":[{"t":"ABO血型","n":"同属基础医学常识"},{"t":"青霉素与疫苗","n":"同簇医学健康知识"},{"t":"地理大发现","n":"大航海期坏血病多发"}],"exam":[]},{"id":"a15-104","t":"ABO血型","cid":"15g","p":3,"kind":"常识","alias":["ABO血型系统","ABO blood group"],"one":"奥地利科学家兰德施泰纳1900年发现的人类最重要红细胞血型系统。","ans":"ABO血型是人类最重要的血型分类系统，由奥地利科学家**兰德施泰纳于1900年发现**并获**诺贝尔生理学或医学奖**。系统依据红细胞抗原分为**A型、B型、AB型与O型**。临床输血须严格**同型输血与交叉配血**，防止凝集反应导致溶血。","pts":["奥地利科学家兰德施泰纳1900年发现","按红细胞抗原分为A、B、AB、O四型","临床输血遵循同型输血与交叉配血原则"],"mem":"口诀：“施泰纳发现ABO，诺奖输血保同型”。AB型红细胞含A、B双抗原，O型无A、B抗原。","mix":"过去常说O型是“万能输血者”、AB型是“万能受血者”，但现代临床医学严格要求“同型输血”，异型输血仅限极紧急且少量输注红细胞情况。","mcq":[{"q":"1900年发现人类ABO血型系统并荣获1930年诺贝尔生理学或医学奖的科学家是","o":["卡尔·兰德施泰纳","亚历山大·弗莱明","爱德华·詹纳","路易·巴斯德"],"a":0,"w":"奥地利科学家卡尔·兰德施泰纳发现了ABO血型系统，奠定了现代输血医学的基石。"}],"rel":[{"t":"人体之最","n":"人体生理结构常识"},{"t":"孟德尔与DNA双螺旋","n":"遗传学与生物科学"},{"t":"克隆羊多莉","n":"生命科学里程碑"}],"exam":[]},{"id":"a15-105","t":"人体之最","cid":"15g","p":3,"kind":"常识","alias":["人体生理之最","人体结构之最"],"one":"人体解剖学中关于器官、腺体与骨骼等关键尺寸维度的常识集锦。","ans":"人体之最是常识考查的高频考点。人体**最大的器官是皮肤**，具备保护与调节体温功能；**最大的消化腺是肝脏**，参与解毒代谢；**最长的骨骼是大腿处的股骨**；**最小的骨骼是中耳听小骨中的镫骨**，仅约3毫米长。","pts":["最大器官是皮肤，最大消化腺是肝脏","最长骨骼是股骨，最小骨骼是镫骨","各器官结构协同维持生命机能运转"],"mem":"口诀：“皮最大、肝最巨，股骨最长镫骨微”。皮肤包全身最大，镫骨在耳内极微小。","mix":"人体最大的内脏器官/最大消化腺是肝脏，但人体整体最大的器官是覆盖全身的皮肤；切勿将二者混淆。","mcq":[{"q":"下列关于人体生理与解剖结构的“之最”，对应错误的是","o":["人体最大的器官是皮肤","人体最大的消化腺是胃","人体最长粗的骨骼是股骨","人体最小的骨骼是镫骨"],"a":1,"w":"人体最大的消化腺是肝脏（成人重约1.2至1.5千克），而不是胃。"}],"rel":[{"t":"ABO血型","n":"人体生理血液常识"},{"t":"紧急求助电话","n":"院前急救生活常识"},{"t":"克隆羊多莉","n":"生命科学与生物医学"}],"exam":[]},{"id":"a15-106","t":"克隆羊多莉","cid":"15g","p":3,"kind":"事件","alias":["多莉","多利羊","Dolly"],"one":"1996年英国罗斯林研究所诞生的世界首个体细胞克隆哺乳动物。","ans":"克隆羊多莉是生命科学史上的里程碑。**1996年7月诞生于英国罗斯林研究所**，由威尔穆特团队培育。它是世界**首个由成年体细胞核移植克隆的哺乳动物**，证实了高度分化体细胞核具全能性。2026年为其**诞生30周年**。","pts":["1996年7月诞生于英国罗斯林研究所","世界上首个体细胞克隆成功的哺乳动物","证实分化体细胞核具有全能性（30周年）"],"mem":"口诀：“九六多莉罗斯林，体细胞克隆羊第一”。1996年诞生，2026年恰逢诞生30周年。","mix":"多莉是由“成年体细胞（乳腺细胞）核移植”培育出来的，而非早期胚胎细胞克隆，因而打破了分化细胞不可逆的传统认知。","mcq":[{"q":"1996年诞生于英国罗斯林研究所的世界上第一只体细胞克隆哺乳动物是","o":["克隆牛多莉","克隆猴中中","克隆羊多莉","克隆猪小花"],"a":2,"w":"1996年7月5日，伊恩·威尔穆特团队培育的克隆羊多莉诞生，2026年恰逢其诞生30周年。"}],"rel":[{"t":"孟德尔与DNA双螺旋","n":"生物遗传学发展历程"},{"t":"达尔文与进化论","n":"生命科学演进"},{"t":"ABO血型","n":"生物与医学常识"}],"exam":[]},{"id":"a15-107","t":"海市蜃楼","cid":"15g","p":2,"kind":"常识","alias":["蜃景","海市"],"one":"光线在密度不均的空气中折射与全反射形成的自然虚像，属光学现象。","ans":"海市蜃楼又称**蜃景**，是**光线在密度不均的空气中发生折射与全反射形成的光学现象**。海面、沙漠或夏日路面上下层空气温差悬殊，密度与折射率随之变化，远处景物的光线经弯曲和**全反射**入眼，人眼逆光线方向便看到空中或地面的**虚像**。日常中筷子入水看似“折断”亦属光的**折射**。它是大气光学中折射与全反射的典型实例。","pts":["本质：光的折射与全反射形成的虚像","成因：空气受热不均导致密度与折射率差异","同类折射现象：筷子入水“折断”、池水变浅"],"mem":"光学原理速配表：海市蜃楼=折射+全反射；彩虹=折射+色散；天空蓝=瑞利散射；水中倒影=反射；小孔成像/日食月食=光沿直线传播。","mix":"选择题常把海市蜃楼与“光的反射”“光的散射”或“光的直线传播”混设选项：水中倒影是平面镜反射，海市蜃楼是大气折射与全反射。","mcq":[{"q":"沙漠和海面常出现“海市蜃楼”奇观，其主要光学原理是","o":["光的直线传播","光的折射与全反射","光的瑞利散射","光的干涉与衍射"],"a":1,"w":"海市蜃楼由光线在密度不均的空气中发生折射和全反射形成。"}],"rel":[{"t":"彩虹","n":"同簇光学现象（色散）"},{"t":"天空为什么是蓝色","n":"同簇光学现象（散射）"},{"t":"《墨经》与墨家科学","n":"古代光学小孔成像对照"}],"exam":[]},{"id":"a15-108","t":"超声波与次声波","cid":"15g","p":2,"kind":"常识","alias":["超声波","次声波"],"one":"高于20000赫兹为超声波，低于20赫兹为次声波；声波不能在真空中传播。","ans":"超声波与次声波是**超出人耳听觉频率范围的两类声波**，属声学基础常识。人耳可听频率约为**20赫兹至20000赫兹**。高于20000赫兹为**超声波**，穿透力强，用于**B超**、声呐及**蝙蝠回声定位**；低于20赫兹为**次声波**，传播远，常由**地震、台风、海啸**产生。二者均属机械波，**不能在真空中传播**，广泛服务于医疗检测与灾害预警。","pts":["人耳可听范围：20至20000赫兹","超声>2万Hz（B超），次声<20Hz（地震）","声波依赖介质，不能在真空中传播"],"mem":"数轴记忆：[次声波] < 20Hz < [人耳可听] < 20000Hz < [超声波]。记“两头大数字都是2”：20和20000；“超高看B超，次低听地震”。","mix":"常见误区：一是以为超声波能在太空（真空）中传播（太空通信靠电磁波而非声波）；二是混淆声呐、B超（超声波）与地震预警监测（次声波）。","mcq":[{"q":"关于超声波与次声波，下列说法错误的是","o":["蝙蝠利用超声波进行回声定位","医院B超检查应用了超声波","地震和台风发生时常伴随次声波","超声波频率极高，可以在真空中传播"],"a":3,"w":"超声波与次声波都属于机械波，必须依赖介质传播，不能在真空中传播。"}],"rel":[{"t":"先见闪电后闻雷声","n":"同簇声学常识（声速）"},{"t":"微波炉","n":"电磁波与声波对比"},{"t":"海市蜃楼","n":"同簇生活物理原理"}],"exam":[]},{"id":"a15-109","t":"干冰与人工降雨","cid":"15g","p":3,"kind":"常识","alias":["人工降雨","人工增雨","干冰人工降雨"],"one":"利用干冰升华吸热降温或碘化银充当凝结核促成水汽降雨的技术。","ans":"干冰是**固态二氧化碳**，常压下**升华吸热**能使环境急剧降温。人工降雨（人工增雨）通常向云层播撒**干冰或碘化银**：干冰升华骤冷促成水汽凝华形成冰晶，碘化银则充当**人工凝结核**，冰晶长大下落融化形成雨水。","pts":["干冰为固态二氧化碳，升华强烈吸热","人工增雨催化剂主要为干冰和碘化银","降低温度或提供凝结核促成水汽降雨"],"mem":"口诀：“干冰升华吸热冷，碘化银做凝结核”。二氧化碳固态直接变气态叫升华。","mix":"人工降雨并非“凭空造雨”，必须在天空有合适云层水汽条件下进行；常用催化剂中干冰主要负责降温，碘化银主要提供凝结核。","mcq":[{"q":"在实施人工降雨（人工增雨）作业中，最常用的化学催化物质是","o":["氯化钠与纯碱","生石灰与活性炭","高锰酸钾与酒精","干冰（固态CO₂）与碘化银"],"a":3,"w":"人工增雨常用干冰升华吸热降温使冰晶形成，或用碘化银作为高效冰核促进水汽凝结。"}],"rel":[{"t":"冰箱制冷","n":"相变吸热原理生活应用"},{"t":"彩虹","n":"云雾水滴与大气现象"},{"t":"温室效应","n":"二氧化碳与气候常识"}],"exam":[]},{"id":"a15-110","t":"84消毒液不能与洁厕灵混用","cid":"15g","p":2,"kind":"常识","alias":["84消毒液","氯气中毒"],"one":"84消毒液含次氯酸钠，与含盐酸的洁厕灵混合会生成有毒氯气。","ans":"84消毒液不能与洁厕灵混用是**日常居家化学安全常识**。**84消毒液**由北京第一传染病医院（今地坛医院）于1984年研制，主要成分为**次氯酸钠**（NaClO）；**洁厕灵**含强酸**盐酸**（HCl）。二者混合发生氧化还原反应，释放大量黄绿色、强刺激性有毒气体**氯气**（Cl₂），吸入会灼伤呼吸道甚至引发**肺水肿**。掌握这一原理可有效防范家庭清洁中毒。","pts":["84消毒液含次氯酸钠，洁厕灵含盐酸","混合发生化学反应生成有毒氯气","吸入氯气损伤呼吸道，严重可致肺水肿"],"mem":"口诀：“84遇洁厕，氯气来索命”。84里的“次氯酸钠”和洁厕灵里的“盐酸”，名字都带“氯/酸”，一碰就把“氯气”放出来。","mix":"选择题常把生成的有毒气体误设为“氨气”“一氧化碳”或“二氧化硫”，正确答案是氯气（Cl₂）；84消毒液同样不能与白醋、酒精随意混用。","mcq":[{"q":"84消毒液与含盐酸的洁厕灵混合使用会产生有毒气体，该气体是","o":["氯气","一氧化碳","氨气","硫化氢"],"a":0,"w":"84消毒液中的次氯酸钠与洁厕灵中的盐酸反应，生成有毒的氯气（Cl₂）。"}],"rel":[{"t":"一氧化碳中毒","n":"同簇居家有毒气体常识"},{"t":"酸雨","n":"同簇生活化学常识"},{"t":"门捷列夫与元素周期表","n":"氯元素位于卤族"}],"more":"反应方程式：NaClO + 2HCl = NaCl + Cl₂↑ + H₂O。","exam":[]},{"id":"a15-111","t":"一氧化碳中毒","cid":"15g","p":2,"kind":"常识","alias":["煤气中毒","CO中毒"],"one":"一氧化碳与血红蛋白亲和力远高于氧气，导致血液丧失输氧能力。","ans":"一氧化碳中毒俗称**煤气中毒**，是**含碳燃料不完全燃烧产生一氧化碳（CO）引发的急性缺氧中毒**，属重要生活安全常识。一氧化碳**无色无味**，吸入后与**血红蛋白**结合生成碳氧血红蛋白，其亲和力约为氧气的**200至300倍**且解离极慢，使血液丧失**输氧能力**，导致脑心缺氧。日常需保持通风，中毒后应立即开窗通风、转移至新鲜空气处并送医。","pts":["俗称煤气中毒，含碳物质不完全燃烧产生","与血红蛋白亲和力约为氧气的200–300倍","导致血液丧失输氧能力，引发组织缺氧"],"mem":"画面记忆：血红蛋白是“运氧快递车”，一氧化碳像“霸座乘客”，抢座能力是氧气的两三百倍，坐上去就不下车，全身细胞因此断氧。","mix":"常见生活误区：在室内放一盆水不能预防一氧化碳中毒，因为一氧化碳难溶于水；家庭管道煤气有刺鼻味是人为添加了硫醇等加臭剂，纯一氧化碳本身无色无味。","mcq":[{"q":"关于一氧化碳中毒，下列说法正确的是","o":["在煤炉旁放一盆清水可有效吸收一氧化碳","一氧化碳具有强烈刺激性气味，易于察觉","一氧化碳与血红蛋白结合力远强于氧气，导致缺氧","一氧化碳中毒是因含碳燃料完全燃烧所致"],"a":2,"w":"一氧化碳无色无味且难溶于水，由不完全燃烧产生，与血红蛋白亲和力远高于氧气。"}],"rel":[{"t":"84消毒液不能与洁厕灵混用","n":"同簇生活安全常识"},{"t":"ABO血型","n":"同涉血液生理知识"},{"t":"温室效应","n":"CO与CO₂性质对照"}],"exam":[]},{"id":"a15-112","t":"避雷针与富兰克林","cid":"15g","p":3,"kind":"人物","alias":["富兰克林避雷针","本杰明·富兰克林"],"one":"美国科学家富兰克林1752年证实雷电本质并随后发明的防雷装置。","ans":"富兰克林是美国启蒙思想家与科学家。他于**1752年进行风筝实验**证实雷电本质，随后**发明避雷针**。该装置利用尖端引雷并**安全导入大地**以保护建筑物免受雷击。他同时也是美国**《独立宣言》起草委员**与建国元勋。","pts":["1752年风筝实验证实雷电电学本质","发明避雷针利用尖端放电导入大地避雷","富兰克林兼为美国建国元勋与思想家"],"mem":"口诀：“富兰克林放风筝，发明避雷引地深”。一手抓科学实验发明避雷针，一手起草《独立宣言》。","mix":"避雷针的作用不是“阻挡雷电”，而是“主动吸引雷电”（接闪）并通过接地导线安全泄入大地，故国家标准也称其为“接闪杆”。","mcq":[{"q":"1752年通过风筝实验证实雷电本质并随后发明避雷针的美国科学家是","o":["本杰明·富兰克林","托马斯·爱迪生","迈克尔·法拉第","尼古拉·特斯拉"],"a":0,"w":"富兰克林通过风筝实验证明雷电就是电，发明了避雷针，也是美国《独立宣言》起草人之一。"}],"rel":[{"t":"先见闪电后闻雷声","n":"同属雷电物理常识"},{"t":"电磁炉与白炽灯","n":"电学应用与发明史对照"},{"t":"牛顿与经典力学","n":"近代科学启蒙"}],"exam":[]},{"id":"a15-113","t":"电磁炉与白炽灯","cid":"15g","p":3,"kind":"常识","alias":["电磁灶与白炽灯","电热电光常识"],"one":"电磁炉利用涡流感应发热、白炽灯利用电流热效应发光的家电常识。","ans":"电磁炉与白炽灯是电能利用的代表工具。电磁炉利用交变磁场在**铁质锅底产生涡流发热**，必须使用铁磁性器皿；白炽灯则基于**电流热效应**使**高温耐热钨丝发光**，由**爱迪生于1879年改进为实用商品**并广泛普及。","pts":["电磁炉靠交变磁场在铁锅底产生涡流发热","白炽灯利用电流热效应使钨丝炽热发光","爱迪生1879年改进出商用耐用白炽灯"],"mem":"口诀：“电磁铁锅生涡流，爱迪生点亮钨丝灯”。电磁炉非铁不发热，白炽灯发光效率低易发热。","mix":"爱迪生并非“从零发明”白炽灯的第一人，而是1879年通过改良耐用灯丝（碳化竹丝等）和真空灯泡使其具备商业实用价值；现代白炽灯灯丝通用熔点极高的金属钨。","mcq":[{"q":"关于电磁炉与白炽灯的工作原理，下列说法正确的是","o":["电磁炉使用陶瓷锅和玻璃锅均能正常快速发热","电磁炉利用交变磁场在铁质锅底产生感应涡流发热","白炽灯是利用电磁波共振激发气体发光","白炽灯灯丝通常采用熔点极低的铜丝制成"],"a":1,"w":"电磁炉利用涡流热效应，须用铁磁性锅具；白炽灯利用电流热效应使熔点极高的钨丝发光。"}],"rel":[{"t":"微波炉","n":"同属厨房电磁加热器具"},{"t":"电饭煲温控","n":"厨房电器控温原理"},{"t":"避雷针与富兰克林","n":"电学发展史"}],"exam":[]},{"id":"a15-114","t":"灭火原理","cid":"15g","p":3,"kind":"常识","alias":["灭火基本方法","灭火四法"],"one":"破坏燃烧条件以隔离可燃物、隔绝助燃物与降温的消防安全常识。","ans":"灭火原理是通过破坏燃烧条件扑灭火灾的安全常识。灭火三大基本途径是：**隔绝氧气（窒息法）**、**降低温度到着火点以下（冷却法）**和**清除移走可燃物（隔离法）**。生活常识中**油锅起火严禁浇水**，应盖上锅盖隔绝空气灭火。","pts":["灭火三法：隔绝氧气、降温与清除可燃物","油锅起火严禁用冷水浇，应盖锅盖窒息","电器起火须先断电，禁用导电灭火剂"],"mem":"口诀：“降温、绝氧、搬柴薪，油锅起火盖锅盖”。灭火就是拆散可燃物、氧气和着火点这三兄弟。","mix":"油锅起火切忌用水泼浇，水比油重且会汽化剧烈爆沸，引发飞溅造成更大火灾；干粉灭火器主要靠化学抑制和窒息作用灭火。","mcq":[{"q":"在家庭日常生活中遇到油锅起火，最科学安全的应急处置方法是","o":["迅速倒入冷水降低油温","端起油锅冲到室外空旷处","立即关火并用锅盖盖住油锅","用嘴或风扇用力向锅内吹风"],"a":2,"w":"油锅起火浇水会引起油滴飞溅助长火势，盖锅盖可隔绝氧气实现窒息灭火。"}],"rel":[{"t":"紧急求助电话","n":"火灾应急防范常识"},{"t":"不粘锅","n":"厨房炊具安全使用"},{"t":"干冰与人工降雨","n":"二氧化碳灭火应用"}],"exam":[]},{"id":"a15-115","t":"酸雨","cid":"15g","p":2,"kind":"常识","alias":["酸性降水"],"one":"pH值小于5.6的降水，主要由二氧化硫和氮氧化物排放形成。","ans":"酸雨指**pH值小于5.6的大气降水**，是全球主要大气环境问题之一。正常雨水因溶解空气中二氧化碳呈弱酸性，pH约**5.6**，故以5.6为界线。酸雨主要由燃煤和尾气排放的**二氧化硫（SO₂）**与**氮氧化物（NOx）**在大气中转化为硫酸和硝酸所致。它会酸化土壤水体、损害森林农作物并腐蚀建筑，治理核心在于**脱硫脱硝**与能源清洁化。","pts":["判定标准：pH值小于5.6的降水","主要成因：二氧化硫和氮氧化物排放","危害土壤水体与建筑，需脱硫脱硝治理"],"mem":"数字锚点：中性水pH=7，正常雨水溶了CO₂降到5.6，低于5.6才算酸雨！两大元凶记“硫氮兄弟”（二氧化硫、氮氧化物）。","mix":"最常见干扰项是“pH值小于7的雨水就是酸雨”和“酸雨主要由二氧化碳引起”；二氧化碳只使正常雨水呈弱酸性（约5.6），真正致酸雨的是二氧化硫和氮氧化物。","mcq":[{"q":"环境科学中，判定降水为“酸雨”的pH值标准是","o":["小于7.0","小于5.6","小于4.5","小于6.5"],"a":1,"w":"正常雨水溶解二氧化碳后pH约5.6，故pH小于5.6的降水才称为酸雨。"}],"rel":[{"t":"温室效应","n":"同簇大气环境问题"},{"t":"PM2.5","n":"同属大气污染指标"},{"t":"《环境保护法》","n":"大气污染治理法治保障"}],"exam":[]},{"id":"a15-116","t":"温室效应","cid":"15g","p":2,"kind":"常识","alias":["温室气体","全球变暖"],"one":"二氧化碳、甲烷等温室气体吸收地面长波辐射，使近地面大气增温。","ans":"温室效应又称**花房效应**，是**大气中温室气体吸收地面红外长波辐射、使近地面气温升高的保温现象**，属环境科学核心常识。主要温室气体包括**二氧化碳（CO₂）**、**甲烷（CH₄）**、氧化亚氮及水蒸气。人类大量燃烧化石燃料致其浓度骤增，加剧**全球气候变暖**，引发冰川融化、海平面上升与极端天气，成为《巴黎协定》与**“双碳”目标**的治理焦点。","pts":["温室气体吸收地面长波辐射使近地面增温","主要气体：二氧化碳、甲烷、氧化亚氮等","加剧全球变暖，关联《巴黎协定》与双碳"],"mem":"画面记忆：温室气体像盖在地球上的“玻璃大棚”，太阳短波光线轻松晒进来，地面散出的长波热量却被挡在棚内，越积越热。","mix":"常见混淆：氧气和氮气占大气99%，但均属于非温室气体；温室效应由二氧化碳、甲烷等引起，切勿与造成酸雨的二氧化硫或破坏臭氧层的氟利昂混为一谈。","mcq":[{"q":"下列气体中，属于导致全球气候变暖的主要温室气体的是","o":["氮气","氧气","氩气","二氧化碳与甲烷"],"a":3,"w":"二氧化碳、甲烷等温室气体能吸收地面长波辐射；氮气、氧气、氩气均不属于温室气体。"}],"rel":[{"t":"碳达峰碳中和","n":"中国应对气候变化目标"},{"t":"《巴黎协定》","n":"全球控温核心国际条约"},{"t":"臭氧层与《蒙特利尔议定书》","n":"易混的另一大气议题"},{"t":"生态环境法典","n":"2026年生态立法新成果"}],"exam":[]},{"id":"a15-117","t":"臭氧层与《蒙特利尔议定书》","cid":"15g","p":2,"kind":"常识","alias":["臭氧层","蒙特利尔议定书","臭氧洞"],"one":"平流层臭氧吸收紫外线；1987年《蒙特利尔议定书》限制氟利昂等消耗物质。","ans":"臭氧层位于大气**平流层**，能吸收太阳大部分有害**紫外线**，护佑地球生命。制冷剂中的**氟利昂（氯氟烃）**会破坏臭氧，**1985年**科学家发现**南极臭氧洞**。国际社会遂于**1987年**签署**《蒙特利尔议定书》**，分阶段淘汰消耗臭氧层物质。该公约获全球普遍批准，使臭氧层逐步修复，被公认为最成功的国际环境条约之一。","pts":["平流层臭氧吸收太阳紫外线，保护生物","氟利昂破坏臭氧层，1985年发现南极臭氧洞","1987年签署《蒙特利尔议定书》限排修复"],"mem":"因果时间链：1985年发现南极“漏了洞”（臭氧洞）→1987年签《蒙特利尔议定书》“补洞”限氟利昂→9月16日定为国际保护臭氧层日。","mix":"易混两大环保公约：《蒙特利尔议定书》（1987）管氟利昂与臭氧层保护；《京都议定书》（1997）和《巴黎协定》（2015）管二氧化碳等温室气体减排。此外，近地面臭氧反而属于光化学污染物。","mcq":[{"q":"1987年签订、旨在限制氟利昂等消耗臭氧层物质的国际环境公约是","o":["《蒙特利尔议定书》","《京都议定书》","《巴黎协定》","《生物多样性公约》"],"a":0,"w":"1987年签署的《蒙特利尔议定书》专门限制消耗臭氧层物质，其余分别针对温室气体或生物多样性。"}],"rel":[{"t":"温室效应","n":"常与臭氧层破坏对举"},{"t":"《巴黎协定》","n":"两大国际环保条约对照"},{"t":"冰箱制冷","n":"传统制冷剂曾含氟利昂"}],"more":"联合国将《蒙特利尔议定书》签署日9月16日定为“国际保护臭氧层日”。","exam":[]},{"id":"a15-118","t":"厄尔尼诺与拉尼娜","cid":"15g","p":2,"kind":"常识","alias":["厄尔尼诺","拉尼娜","圣婴现象","ENSO"],"one":"厄尔尼诺指赤道中东太平洋海水异常增温，拉尼娜指异常降温，均致气候异常。","ans":"厄尔尼诺与拉尼娜是**赤道中东太平洋海气相互作用异常现象**，与南方涛动合称**ENSO**，属气候学高频常识。**厄尔尼诺**意为西班牙语“圣婴”，指**赤道中东太平洋海水异常持续偏暖**；**拉尼娜**意为“圣女”，指该海域**海水异常持续偏冷**。二者扰动大气环流，诱发全球极端暴雨、洪涝与干旱，深刻影响农业生产和全球防灾减灾。","pts":["发生海区：赤道中东太平洋","厄尔尼诺（圣婴）异常增温，拉尼娜（圣女）异常降温","扰动大气环流，引发全球洪涝干旱等异常"],"mem":"词义+温度记忆：厄尔尼诺=“圣婴（男孩）”，调皮发热→海水异常增温；拉尼娜=“圣女（女孩）”，安静偏冷→海水异常降温。两词均来自西班牙语。","mix":"选择题常把发生海域改成“大西洋”或“赤道西太平洋”，正确海域是“赤道中东太平洋”；也常互换增温与降温的对应关系。","mcq":[{"q":"气象学中，“拉尼娜”现象是指赤道中东太平洋海表温度出现","o":["异常持续偏暖","异常持续偏冷","盐度急剧升高","潮汐完全停止"],"a":1,"w":"厄尔尼诺是赤道中东太平洋海水异常偏暖，拉尼娜则是异常偏冷。"}],"rel":[{"t":"温室效应","n":"同簇全球气候变化常识"},{"t":"联合国气候变化大会第三十一次缔约方大会（COP31）","n":"全球气候治理机制"},{"t":"七大洲四大洋","n":"太平洋海气相互作用"}],"exam":[]},{"id":"a15-119","t":"PM2.5","cid":"15g","p":3,"kind":"常识","alias":["细颗粒物","可入肺颗粒物"],"one":"空气动力学当量直径小于或等于2.5微米、可直达肺泡的细颗粒物。","ans":"PM2.5指空气中**空气动力学当量直径小于或等于2.5微米**的**细颗粒物**。它悬浮时间长、活性强，易附带有毒有害物质。因其粒径微小，可穿透鼻腔直接**沉积于人体肺泡**甚至渗入血液，是诱发呼吸道疾病及构成**雾霾天气**的主因。","pts":["空气动力学当量直径≤2.5微米的细颗粒物","能穿透呼吸道屏障直接深入肺泡与血液","雾霾天气和空气质量指数（AQI）主要监测指标"],"mem":"口诀：“二点五微米直入肺，细小有毒化作霾”。比头发丝细二十分之一，入肺伤心血管。","mix":"PM10称为“可吸入颗粒物”（直径≤10微米），能进入呼吸道；PM2.5称为“细颗粒物”，专指直径≤2.5微米并能直接进入肺泡的颗粒物。","mcq":[{"q":"环境监测中常提及的“PM2.5”，其科学定义是指","o":["空气中粒径在2.5至10微米之间的可吸入颗粒物","工业废气中排放的重金属微尘总量","空气动力学当量直径在2.5微米以上的粗颗粒物","空气动力学当量直径小于或等于2.5微米的细颗粒物"],"a":3,"w":"PM2.5指空气动力学当量直径小于或等于2.5微米的细颗粒物，可深入肺泡危害健康。"}],"rel":[{"t":"酸雨","n":"大气环境污染常识"},{"t":"天空为什么是蓝色","n":"气溶胶与大气散射"},{"t":"人体之最","n":"肺泡与人体生理结构"}],"exam":[]},{"id":"a15-120","t":"紧急求助电话","cid":"15g","p":3,"kind":"常识","alias":["报警电话","应急求助电话","特种服务电话"],"one":"中国设立的110报警、119火警、120急救与122交警等法定特服热线。","ans":"紧急求助电话是中国面向公众设立的公益免费应急热线。核心四号为：**110公安报警**、**119火警救援**、**120医疗急救**和**122交通事故报警**。市民在遭遇危急险情时可直接拨打，通话应**准确报出具体地点与事由**。","pts":["110公安报警、119火警救援","120医疗急救、122交通事故报警","全天候免费直拨，如实报清地点与事由"],"mem":"口诀：“110抓小偷，119灭火灾，120送医院，122撞车来”。四个核心号码功能严密分工。","mix":"122是交通事故报警电话，而12315是消费者申诉举报热线，12345是政务服务便民热线；遇火灾切勿误拨110耽搁扑救。","mcq":[{"q":"在我国，发生道路交通事故需要交警现场处置时，应拨打的紧急专线电话是","o":["122","110","120","119"],"a":0,"w":"我国122是道路交通事故报警电话，110是公安报警，119是火警，120是医疗急救。"}],"rel":[{"t":"灭火原理","n":"火警119应急处置"},{"t":"人体之最","n":"急救医学生活常识"},{"t":"法定节假日","n":"社会公共生活管理"}],"exam":[]},{"id":"a15-121","t":"太阳系八大行星","cid":"15h","p":2,"kind":"合称","alias":["八大行星","太阳系行星"],"one":"距日由近及远：水金地火木土天海；木星最大；2006年冥王星降为矮行星。","ans":"太阳系八大行星指**绕太阳公转且符合国际天文学联合会（IAU）标准的八颗大行星**，属天文学核心合称。按距太阳**由近及远**依次为**水星、金星、地球、火星、木星、土星、天王星、海王星**。前四颗为类地岩石行星，后四颗为巨行星；**木星最大**，水星最小。**2006年**IAU将**冥王星**归为**矮行星**，九大行星遂改称八大行星。","pts":["由近及远：水、金、地、火、木、土、天、海","木星最大、水星最小；分岩石、气态、冰巨星","2006年IAU将冥王星归为矮行星"],"members":[["水星","距太阳最近、体积和质量最小的类地行星"],["金星","中国古称太白星（启明/长庚），自转方向自东向西"],["地球","目前已知唯一存在生命的行星，有一颗天然卫星月球"],["火星","表面富含氧化铁呈红色，中国古称荧惑"],["木星","太阳系体积和质量最大的气态巨行星"],["土星","拥有最显著的行星环，气态巨行星"],["天王星","冰巨星，自转轴几乎平躺于公转轨道面"],["海王星","距太阳最远的冰巨星，通过数学计算预测后发现"]],"mem":"通行首字口诀：“水金地火，木土天海”。记两组四字：前面“水金地火”是硬石头（类地行星），后面“木土天海”是大块头（巨行星）。2006年冥王星出局，2026年满20周年。","mix":"易错点：2006年冥王星被归为“矮行星”，并非“小行星”或“卫星”；距太阳最近的是水星，但因金星大气温室效应极强，表面平均温度最高的其实是金星。","mcq":[{"q":"2006年国际天文学联合会通过决议，将冥王星重新归类为","o":["小行星","卫星","彗星","矮行星"],"a":3,"w":"冥王星因未能清空公转轨道邻近区域，2006年被IAU归类为矮行星，太阳系遂定为八大行星。"}],"rel":[{"t":"哥白尼日心说","n":"太阳系中心认识起点"},{"t":"哈雷彗星","n":"太阳系另一著名天体"},{"t":"日食与月食","n":"日地月运行天文现象"},{"t":"《流浪地球》","n":"科幻中的太阳系题材"}],"more":"2006年8月24日IAU第26届大会确立行星三条标准，2026年正值冥王星降级20周年。","exam":[]},{"id":"a15-122","t":"光年","cid":"15h","p":2,"kind":"常识","alias":["light-year","ly"],"one":"天文学长度单位，指光在真空中一年传播的距离，约9.46万亿千米。","ans":"光年是**天文学计量天体间距离的长度单位**，指**光在真空中行进一个儒略年（365.25天）所走的距离**。真空光速约每秒30万千米，换算得**1光年约9.46万亿千米**。它常用于标注恒星与星系尺度，如距太阳最近的比邻星约4.24光年。辨清光年属于**距离单位**而非时间单位，是宇宙测距基础，也是百科易错考点。","pts":["本质是长度（距离）单位，非时间单位","定义：光在真空中一年传播的距离","数值：1光年约等于9.46万亿千米"],"mem":"拆字防错：光年 = 光速 × 1年 = 速度 × 时间 = 路程（距离）。看到“年”字别上当，心里默念“光跑一年的路程”。数字记“酒思留（9.46）万亿千米”。","mix":"最高频干扰项是把光年当成“时间单位”；太阳系内测距常用“天文单位（AU，日地平均距离约1.5亿千米）”，更远星系测距还常用“秒差距（约3.26光年）”。","mcq":[{"q":"天文学中常用的“光年”属于哪一种物理量的单位","o":["长度（距离）","时间","速度","亮度"],"a":0,"w":"光年指光在真空中一年传播的距离，约9.46万亿千米，属于长度单位。"}],"rel":[{"t":"太阳系八大行星","n":"同簇天文学基础常识"},{"t":"先见闪电后闻雷声","n":"同涉光速基本概念"},{"t":"爱因斯坦与相对论","n":"真空光速不变原理"}],"exam":[]},{"id":"a15-123","t":"四季成因","cid":"15h","p":2,"kind":"常识","alias":["四季更替","黄赤交角"],"one":"地球公转时地轴倾斜且方向不变，导致太阳直射点移动形成四季。","ans":"四季成因指**地球表面春夏秋冬周期更替的天文机制**，属天文地理基础常识。地球绕太阳**公转**时，**地轴倾斜**且空间指向基本不变（存在约23°26′的**黄赤交角**）。由此导致**太阳直射点在南北回归线间往返移动**，引起各地**正午太阳高度**和**昼夜长短**变化，造成地表受热不均。南北半球季节相反，该规律亦是二十四节气的科学依据。","pts":["地球公转且地轴倾斜、空间指向不变","太阳直射点在南北回归线间周期移动","引起正午太阳高度和昼夜长短变化"],"mem":"排错逻辑线：为什么有四季？因为“公转+地轴歪着走”→直射点南北摆动→太阳高矮、白天长短变了→冷热成四季。若与距离有关，南北半球就不会季节相反了！","mix":"经典错误选项是“四季是地球公转时距太阳远近变化造成的”：事实上地球1月初过近日点时北半球正值寒冬，7月初过远日点时北半球正值盛夏。","mcq":[{"q":"地球上产生春夏秋冬四季更替的根本原因是","o":["地球公转轨道呈椭圆导致日地距离变化","地球公转时地轴倾斜且空间指向基本不变","地球自转速度在一年中周期性改变","太阳黑子活动周期影响太阳辐射强度"],"a":1,"w":"四季成因是地球公转与地轴倾斜（黄赤交角存在）共同引起太阳直射点移动，与日地距离远近无关。"}],"rel":[{"t":"南北回归线与极圈","n":"黄赤交角决定其纬度"},{"t":"二十四节气中的“四立二分二至”","n":"公转与直射点节气节点"},{"t":"公历闰年","n":"与地球公转周期相关"}],"exam":[]},{"id":"a15-124","t":"南北回归线与极圈","cid":"15h","p":2,"kind":"地理","alias":["回归线","极圈","五带划分"],"one":"回归线约南北纬23°26′为太阳直射界线；极圈约66°34′以内有极昼极夜。","ans":"南北回归线与极圈是**由黄赤交角决定的四条特殊纬线**，也是划分**地球五带**的界线。**南北回归线**约在**南北纬23°26′**，是太阳直射的最北和最南界线，其间为热带。**南北极圈**约在**南北纬66°34′**，其内有**极昼极夜**现象，构成南北寒带；回归线与极圈之间为温带。中国北回归线穿过云南、广西、广东、台湾四省区，标示地球热量带分布。","pts":["回归线约23°26′，为太阳直射南北界线","极圈约66°34′，其内出现极昼极夜现象","四条纬线将地球划分为热、温、寒五带"],"mem":"互补数字记法：23°26′ + 66°34′ = 90°！只要背住黄赤交角23°26′，用90°一减就得极圈66°34′。北回归线穿中国四省口诀：“云广广台”（云南、广西、广东、台湾）。","mix":"常见混淆：回归线和极圈都是“纬线”（东西走向、标示南北纬），别与经线混淆；温带地区既无太阳直射，也无极昼极夜现象。","mcq":[{"q":"地球表面出现极昼和极夜现象的最低纬度界线约是","o":["南北纬23°26′","南北纬45°","南北纬66°34′","南北纬75°"],"a":2,"w":"南北极圈位于约南北纬66°34′，其以内地区会出现极昼和极夜现象。"}],"rel":[{"t":"四季成因","n":"同由黄赤交角决定"},{"t":"经度与纬度","n":"纬线体系核心特殊线"},{"t":"二十四节气中的“四立二分二至”","n":"二至日直射南北回归线"}],"exam":[]},{"id":"a15-125","t":"本初子午线","cid":"15h","p":2,"kind":"地理","alias":["0度经线","格林尼治子午线","首子午线"],"one":"0度经线，经英国伦敦格林尼治天文台原址，1884年国际会议确立。","ans":"本初子午线即**0度经线**，是**全球经度计量的起始基准线**，属天文地理基础概念。**1884年**华盛顿国际子午线会议确定，以通过英国伦敦**格林尼治天文台原址**的经线为本初子午线。由此向东、向西各分180°为**东经与西经**，该线亦是**零时区**中央经线与格林尼治标准时间基准。它的确立统一了全球航海定位与国际时区换算。","pts":["0度经线，东西经划分的起始基准线","1884年会议确立，经伦敦格林尼治天文台原址","零时区中央经线，统一全球定位与时区"],"mem":"三锚点：“0度、1884、格林尼治”。子午即南北方向（子为北、午为南），“本初子午线”字面就是“最开始那条南北线”。","mix":"高频陷阱：本初子午线和180°经线是“东西经”分界线，而“东西半球”分界线是西经20°和东经160°（为避免把欧洲、非洲大陆切开）。北京时间用东八区（东经120°），比格林尼治快8小时。","mcq":[{"q":"1884年国际子午线会议确定本初子午线（0°经线）通过的地点是","o":["法国巴黎天文台","美国华盛顿天文台","瑞士日内瓦天文台","英国伦敦格林尼治天文台原址"],"a":3,"w":"1884年国际子午线会议确定通过英国伦敦格林尼治天文台原址的经线为本初子午线。"}],"rel":[{"t":"经度与纬度","n":"经度体系的零点基准"},{"t":"国际日期变更线","n":"相对的180度经线"},{"t":"北京时间","n":"东八区与零时区相差8小时"}],"exam":[]},{"id":"a15-126","t":"日食与月食","cid":"15h","p":3,"kind":"常识","alias":["日食","月食","日月食"],"one":"月球挡光致日食（初一朔日）、地球挡光致月食（十五望日）的天象。","ans":"日食与月食是天体相互遮蔽形成的天文现象。**日食发生在农历初一（朔日）**，月球运行至日地之间**挡住射向地球的阳光**；**月食发生在农历十五（望日）**前后，地球运行至日月之间**挡住照向月球的阳光**。两者由光沿直线传播所致。","pts":["日食发生于农历初一（朔），月球遮挡太阳","月食发生于农历十五（望），地球遮挡阳光","天体遮掩基于光的直线传播，月食无环食"],"mem":"口诀：“初一日食月挡日，十五月食地遮月”。初一日月地，十五日地月。","mix":"日食有日全食、日环食和日偏食三种；月食只有月全食和月偏食，绝不可能发生“月环食”（地球本影远大于月球）。","mcq":[{"q":"关于日食与月食的成因与发生时间，下列说法正确的是","o":["日食发生于农历初一前后，月食发生于农历十五前后","月食发生于农历初一前后，日食发生于农历十五前后","日食与月食都可能出现罕见的“环食”天象","日食成因是地球运行到太阳与月球之间遮挡阳光"],"a":0,"w":"日食发生在初一（月球挡住阳光），月食发生在十五（地球挡住阳光）；月球体积小于地球本影，故无月环食。"}],"rel":[{"t":"太阳系八大行星","n":"天体物理与运行轨道"},{"t":"潮汐","n":"地月中引潮力天象"},{"t":"农历","n":"朔望月与阴阳合历"}],"exam":[]},{"id":"a15-127","t":"潮汐","cid":"15h","p":3,"kind":"常识","alias":["海潮","潮汐现象","潮与汐"],"one":"海水受月球和太阳引潮力作用产生的周期性涨落现象（早潮晚汐）。","ans":"潮汐是海水在**月球和太阳引潮力**作用下产生的周期性涨落现象。白天海涨称**潮**，夜晚海涨称**汐**。朔望（初一与十五）时日月引潮力叠加形成大潮。我国**钱塘江大潮**受杭州湾喇叭口地形聚涌，以**农历八月十八**前后最为壮阔。","pts":["由月球和太阳对地球海水的引潮力引起","白天涨水为“潮”，夜晚涨水为“汐”","钱塘江大潮以农历八月十八前后最为壮观"],"mem":"口诀：“早潮晚汐日月引，八月十八看钱塘”。月球距离近，其引潮力约为太阳的2.17倍。","mix":"虽然太阳质量远大于月球，但由于月球离地球距离极近，月球对地球的引潮力约为太阳引潮力的2倍多，是引发潮汐的主导力量。","mcq":[{"q":"引发海洋潮汐现象的最主要天体引潮力来源是","o":["太阳的万有引力","月球的引潮力","木星与土星的引力叠加","地球内部地幔岩浆运动"],"a":1,"w":"引潮力与距离的三次方成反比，月球距地球极近，其引潮力约为太阳的2.17倍，是潮汐主因。"}],"rel":[{"t":"日食与月食","n":"同受日月地三者天体运动影响"},{"t":"牛顿与经典力学","n":"万有引力定律与引潮力解释"},{"t":"农历","n":"月相朔望周期常识"}],"exam":[]},{"id":"a15-128","t":"哈雷彗星","cid":"15h","p":3,"kind":"常识","alias":["Halley's Comet","1P/Halley"],"one":"英国天文学家哈雷预言并命名的著名短周期彗星，公转周期约76年。","ans":"哈雷彗星是首颗被预言回归的著名周期彗星，由英国天文学家**哈雷测定其轨道**。其围绕太阳运行的**公转周期约为76年**。《春秋》保存了世界上最早的确切记录。它**最近一次回归是1986年**，预计**2061年将再次光临地球**。","pts":["英国天文学家哈雷计算轨道并预言其回归","围绕太阳运行周期约为76年","1986年最近一次回归，预计2061年再临"],"mem":"口诀：“哈雷彗星七十六，八六回归六一见”。《春秋》记载“星孛入于北斗”为全球最早确切记录。","mix":"彗星发光并非自身核反应发光，而是反射太阳光以及彗核冰物质挥发被阳光电离激发出的彗尾荧光。","mcq":[{"q":"著名的哈雷彗星围绕太阳公转的平均回归周期大约是","o":["12年","36年","76年","120年"],"a":2,"w":"哈雷彗星平均周期约76年，上一次过近日点在1986年，下一次预计在2061年回归。"}],"rel":[{"t":"太阳系八大行星","n":"太阳系天体与轨道运行"},{"t":"牛顿与经典力学","n":"引力定律在彗星轨道中的应用"},{"t":"日食与月食","n":"中国古代天象记录"}],"exam":[]},{"id":"a15-129","t":"法定节假日","cid":"15h","p":3,"kind":"常识","alias":["全体公民放假节日","国家法定节假日","全国年节及纪念日"],"one":"国家法律规定全体公民依法带薪休假的节日，2025年起增至13天。","ans":"法定节假日指国家规定全体公民享受的法定休假日。依据修订的《全国年节及纪念日放假办法》，**自2025年起法定节假日增至13天**。主要调整为：**春节增加除夕放假4天**，**劳动节增加5月2日放假2天**，保障公民带薪休息权益。","pts":["自2025年1月1日起全体公民法定节假日增至13天","春节增加1天（除夕），放假4天","劳动节增加1天（5月2日），放假2天"],"mem":"口诀：“二五新规增两天，除夕五二凑十三”。2025年起总天数从11天变为13天。","mix":"注意修改年份与施行时间：国务院于2024年11月公布修改决定，正式施行于2025年1月1日；新增天数是除夕和5月2日。","mcq":[{"q":"根据2024年修订的《全国年节及纪念日放假办法》，自2025年1月1日起，我国全体公民放假的法定节假日总天数调整为","o":["10天","11天","12天","13天"],"a":3,"w":"2025年起法定节假日由11天增至13天，春节增加除夕（共4天），劳动节增加5月2日（共2天）。"}],"rel":[{"t":"二十四节气","n":"传统农历节气与岁时民俗"},{"t":"农历","n":"中国传统节庆日期编排"},{"t":"北京时间","n":"现代时间体制与公共管理"}],"exam":[]},{"id":"a15-130","t":"中国地理之最","cid":"15i","p":1,"kind":"合称","alias":["中国之最","地理之最"],"one":"最长河长江，最大淡水湖鄱阳湖，最大盆地塔里木盆地，最大高原青藏高原。","ans":"中国地理之最指**我国各类地理事物中规模、长度或高度居首位者**。**最长的河流是长江，最长的内流河是塔里木河**；**最大的淡水湖是鄱阳湖，最大的咸水湖是青海湖**；**最大的盆地是塔里木盆地，最大的沙漠是塔克拉玛干沙漠**；**最大的平原是东北平原，最大最高的高原是青藏高原**；**最大的岛屿是台湾岛**；**最低的洼地是吐鲁番盆地的艾丁湖**。这些“之最”是选择题的高频考点，题干常用“最大”“最长”设问。","pts":["长江最长，塔里木河最长内流河","鄱阳湖最大淡水湖，青海湖最大咸水湖","塔里木盆地、塔克拉玛干沙漠、东北平原、青藏高原、台湾岛、艾丁湖"],"members":[["最长的河流","长江"],["最长的内流河","塔里木河"],["最大的淡水湖","鄱阳湖"],["最大的咸水湖","青海湖"],["最大的盆地","塔里木盆地"],["最大的沙漠","塔克拉玛干沙漠"],["最大的平原","东北平原"],["最大最高的高原","青藏高原"],["最大的岛屿","台湾岛"],["最低的洼地","吐鲁番盆地的艾丁湖"]],"mem":"“塔”字三连：塔里木河、塔里木盆地、塔克拉玛干沙漠都在新疆，都是“最”。湖用“淡鄱咸青”：淡水鄱阳，咸水青海。岛用“台”，洼地用“艾”：台湾岛最大，艾丁湖最低。","mix":"最大的淡水湖是鄱阳湖，不是洞庭湖（洞庭湖居第二，且面积随季节变化）；最大的岛屿是台湾岛，海南岛是第二；最大的平原是东北平原，不是华北平原；最大的盆地塔里木，不是四川盆地；青海湖是咸水湖，不是淡水湖。","mcq":[{"q":"我国最大的淡水湖是","o":["洞庭湖","太湖","鄱阳湖","青海湖"],"a":2,"w":"鄱阳湖是我国最大的淡水湖，青海湖是最大的咸水湖。"},{"q":"我国最大的盆地是","o":["四川盆地","塔里木盆地","准噶尔盆地","柴达木盆地"],"a":1,"w":"塔里木盆地是我国最大的盆地。"}],"rel":[{"t":"长江","n":"最长河流"},{"t":"鄱阳湖与青海湖","n":"最大淡水湖与咸水湖"},{"t":"塔里木盆地","n":"最大盆地"},{"t":"塔克拉玛干沙漠","n":"最大沙漠"},{"t":"世界山地、高原、平原、盆地之最","n":"世界之最对照"}],"more":"另有：最高的山峰珠穆朗玛峰；最大的岛屿台湾岛，第二是海南岛。","exam":[]},{"id":"a15-131","t":"三大平原、四大高原、四大盆地","cid":"15i","p":1,"kind":"合称","alias":["三大平原","四大高原","四大盆地"],"one":"三大平原东北、华北、长江中下游；四大高原青内黄云；四大盆地塔准柴川。","ans":"三大平原、四大高原、四大盆地是**我国主要地形区的通行分类**。**三大平原**是**东北平原、华北平原、长江中下游平原**；**四大高原**是**青藏高原、内蒙古高原、黄土高原、云贵高原**；**四大盆地**是**塔里木盆地、准噶尔盆地、柴达木盆地、四川盆地**。其中东北平原最大，青藏高原最大最高，被称为“世界屋脊”，塔里木盆地最大，柴达木盆地海拔最高，四川盆地有“天府之国”之称。这些地形区构成我国地势西高东低、呈三级阶梯的基本格局。","pts":["三大平原：东北、华北、长江中下游","四大高原：青藏、内蒙古、黄土、云贵","四大盆地：塔里木、准噶尔、柴达木、四川"],"members":[["东北平原","三大平原中最大"],["华北平原","黄淮海平原"],["长江中下游平原","长江沿岸"],["青藏高原","最大最高，“世界屋脊”"],["内蒙古高原","草原广布"],["黄土高原","黄土覆盖，沟壑纵横"],["云贵高原","喀斯特地貌"],["塔里木盆地","最大的盆地"],["准噶尔盆地","新疆北部"],["柴达木盆地","海拔最高的盆地"],["四川盆地","“天府之国”"]],"mem":"三串首字：平原“东华长”，高原“青内黄云”，盆地“塔准柴川”。前一个字对应：东北华北长江中下游；青藏内蒙古黄土云贵；塔里木准噶尔柴达木四川。","mix":"四大盆地里柴达木盆地海拔最高，塔里木盆地最大，准噶尔盆地与塔里木盆地都在新疆；黄土高原不在四川盆地附近；平原里没有四川成都平原（属四川盆地内）。","mcq":[{"q":"下列属于我国四大高原的是","o":["伊朗高原","黄土高原","德干高原","帕米尔高原"],"a":1,"w":"四大高原为青藏、内蒙古、黄土、云贵高原。"},{"q":"下列属于我国四大盆地的是","o":["塔里木盆地","吐鲁番盆地","刚果盆地","亚马孙盆地"],"a":0,"w":"四大盆地是塔里木、准噶尔、柴达木、四川盆地。"}],"rel":[{"t":"中国地理之最","n":"之最的补充"},{"t":"东北平原","n":"最大平原"},{"t":"塔里木盆地","n":"最大盆地"},{"t":"世界山地、高原、平原、盆地之最","n":"世界之最对照"},{"t":"帕米尔高原","n":"高原常识"}],"exam":[]},{"id":"a15-132","t":"地势三级阶梯","cid":"15i","p":2,"kind":"概念","alias":["中国地势三级阶梯","三级阶梯"],"one":"中国地势西高东低呈三级阶梯：青藏高原第一级，昆祁横、兴太巫雪为两条界线。","ans":"地势三级阶梯指**中国地势西高东低、逐级下降的三级格局**，属自然地理核心骨架。**第一级阶梯**为**青藏高原**，海拔4000米以上；一、二级界线为**昆仑山、阿尔金山、祁连山、横断山**。**第二级阶梯**以高原盆地为主；二、三级界线为**大兴安岭、太行山、巫山、雪峰山**。**第三级阶梯**以平原丘陵为主。此地势利于海风深入，也使大江东流并富集水能。","pts":["西高东低三级阶梯：青藏高原→高原盆地→平原丘陵","一二级界线：昆仑山、阿尔金山、祁连山、横断山","二三级界线：大兴安岭、太行山、巫山、雪峰山"],"mem":"界线首字口诀：一二级“昆阿祁横”（或“昆祁横”）；二三级“兴太巫雪”（谐音“兴太无雪”或“大太巫雪”）。地形由西向东：屋脊→高盆→平丘。","mix":"常见干扰项是把“秦岭”“天山”“武夷山”混入阶梯分界线，或把一二级、二三级山脉互换；四大盆地中，柴达木盆地位于第一级阶梯，其余三大盆地在第二级阶梯。","mcq":[{"q":"下列山脉中，属于中国地势第二级与第三级阶梯分界线的是","o":["昆仑山脉","祁连山脉","横断山脉","太行山脉"],"a":3,"w":"二、三级阶梯界线为大兴安岭、太行山、巫山、雪峰山；昆仑山、祁连山、横断山是一、二级界线。"}],"rel":[{"t":"三大平原、四大高原、四大盆地","n":"三级阶梯内的主要地形区"},{"t":"珠穆朗玛峰","n":"第一级阶梯最高点"},{"t":"长江","n":"自西向东跨越三级阶梯"},{"t":"秦岭淮河一线","n":"另一重要自然地理界线"}],"exam":[]},{"id":"a15-133","t":"秦岭淮河一线","cid":"15i","p":1,"kind":"概念","alias":["秦岭—淮河","秦岭淮河线","南北分界线"],"one":"中国南方与北方的分界线，1月0℃等温线和800毫米等降水量线经过之处。","ans":"秦岭淮河一线是**中国地理上南方与北方的分界线**，东起淮河，西至秦岭，大致与**1月0℃等温线、800毫米年等降水量线**一致。线以南属**亚热带季风气候**，湿润区，农业以水田、水稻为主；线以北属**暖温带季风气候**，半湿润区，以旱地、小麦为主。它是**亚热带与暖温带、湿润区与半湿润区、水田与旱地**的分界，也是南方河流冬季不结冰、北方河流有结冰期的分界。秦岭同时是黄河和长江流域的分水岭。","pts":["南北方分界线，秦岭至淮河","1月0℃等温线和800毫米等降水量线","亚热带/暖温带，湿润/半湿润"],"mem":"两个数字“0 与 800”：1 月 0℃，年降水 800 毫米。分界对照“南水北旱”：线南水田、水稻，线北旱地、小麦；“南船北马”也是这条线的生活写照。","mix":"秦岭淮河一线是南北分界，不是中国地势阶梯的分界，也不是干湿区的“400毫米等降水量线”（那是半湿润与半干旱区的分界）；秦岭同时是黄河与长江流域的分水岭之一，长江干流并非这条南北分界线。","mcq":[{"q":"我国亚热带与暖温带的分界线大致是","o":["长江一线","秦岭淮河一线","黄河一线","南岭一线"],"a":1,"w":"秦岭淮河一线是亚热带与暖温带、南方与北方的分界。"},{"q":"秦岭淮河一线大致与下列哪条等降水量线一致","o":["200毫米","400毫米","800毫米","1600毫米"],"a":2,"w":"秦岭淮河一线大致与800毫米年等降水量线一致，400毫米线是半湿润与半干旱区的界线。"}],"rel":[{"t":"三大平原、四大高原、四大盆地","n":"地形区常识"},{"t":"长江","n":"线以南的大河"},{"t":"中国地理之最","n":"地理常识"},{"t":"东北平原","n":"位于线以北"}],"more":"秦岭是黄河与长江流域的分水岭之一。","exam":[]},{"id":"a15-134","t":"胡焕庸线","cid":"15i","p":2,"kind":"概念","alias":["黑河—腾冲线","瑷珲—腾冲线","黑河腾冲线"],"one":"1935年胡焕庸提出黑河至腾冲一线，揭示中国人口东南密、西北疏的格局。","ans":"胡焕庸线又称**黑河至腾冲线**（原称瑷珲至腾冲线），是**地理学家胡焕庸于1935年提出的人口地理分界线**。该线北起黑龙江**黑河**，南至云南**腾冲**，将中国分为东南与西北两半壁。按1935年测算，**东南侧以约36%国土聚居约96%人口**，西北侧占约64%国土仅居约4%人口。该线与400毫米等降水量线贴近，近百年格局稳定，是区域规划基准。","pts":["1935年地理学家胡焕庸提出，起止黑河至腾冲","1935年数据：东南约36%国土聚居约96%人口","与400毫米等降水量线贴近，格局高度稳定"],"mem":"起止与数字口诀：“黑河到腾冲，三六九六分西东”（1935年东南36%土地、96%人口）。黑河在最东北（黑龙江），腾冲在最西南（云南），斜切中国45度。","mix":"易混点：秦岭淮河一线是南北气候与800毫米等降水量线，胡焕庸线是人口分界线且贴近400毫米等降水量线；按现今国土版图口径，东南侧约占43%国土、约94%人口，但考试常考1935年原数据“36%与96%”。","mcq":[{"q":"1935年地理学家胡焕庸提出揭示中国人口分布格局的“胡焕庸线”，其南北两端分别是","o":["黑龙江黑河与云南腾冲","黑龙江漠河与云南瑞丽","吉林长春与广西北海","陕西秦岭与安徽淮河"],"a":0,"w":"胡焕庸线北起黑龙江黑河（原瑷珲），南至云南腾冲，揭示东南密、西北疏的人口格局。"}],"rel":[{"t":"秦岭淮河一线","n":"中国两大核心地理界线"},{"t":"地势三级阶梯","n":"自然地形制约人口分布"},{"t":"中国疆域与行政区划","n":"国土空间分布格局"}],"exam":[]},{"id":"a15-135","t":"黄河","cid":"15i","p":2,"kind":"地理","alias":["母亲河"],"one":"中国第二长河，全长5464千米，发源巴颜喀拉山、入渤海，称“母亲河”。","ans":"黄河是**中国第二长河**，全长**5464千米**，被誉为**“中华民族的母亲河”**。它发源于青海**巴颜喀拉山脉**北麓，干流呈“几”字形流经青海、四川、甘肃、宁夏、内蒙古、山西、陕西、河南、山东共**9个省级行政区**，注入**渤海**。中游流经**黄土高原**致含沙量大，下游淤积成**“地上悬河”**。黄河流域孕育了仰韶、龙山等早期文化，是中华文明核心发祥地。","pts":["中国第二长河，全长5464千米，称“母亲河”","发源青海巴颜喀拉山脉，流经9省区注入渤海","中游含沙量大，下游形成“地上悬河”"],"mem":"数字+路线记忆：5464记成“五四六四”；“巴颜喀拉写‘几’字，九省奔流进渤海；中游黄土带泥沙，下游变成地上河”。","mix":"易混点：黄河注入渤海（内海），而非黄海；黄河发源于巴颜喀拉山脉，长江发源于唐古拉山脉；流经省区黄河为9个、长江为11个，共同流经的是青海和四川两省。","mcq":[{"q":"关于黄河的地理特征，下列说法错误的是","o":["全长约5464千米，为中国第二长河","干流最终在江苏省注入黄海","发源于青海省巴颜喀拉山脉北麓","下游因泥沙淤积形成“地上悬河”"],"a":1,"w":"黄河干流在山东省东营市注入渤海，并非注入黄海。"}],"rel":[{"t":"长江","n":"中国第一、第二长河并举"},{"t":"《黄河大合唱》","n":"以黄河为象征的经典乐章"},{"t":"《水经注》","n":"古代详记黄河水系的地理名著"}],"exam":[]},{"id":"a15-136","t":"京杭大运河","cid":"15i","p":2,"kind":"地理","alias":["大运河","京杭运河"],"one":"北起北京、南至杭州，世界里程最长古代运河，2014年中国大运河申遗成功。","ans":"京杭大运河是**北起北京、南至杭州的古代人工运河**，全长约**1794千米**，为**世界里程最长的古代运河**。其始凿于春秋吴王夫差开**邗沟**，经**隋炀帝**贯通、**元代**裁弯取直定型，自北向南沟通**海河、黄河、淮河、长江、钱塘江**五大水系。**2014年**，中国大运河列入《世界遗产名录》，至今仍承担内河航运与南水北调东线输水功能。","pts":["北起北京、南至杭州，世界里程最长古代运河","始于春秋邗沟，经隋贯通、元定型，连五大水系","2014年中国大运河列入《世界遗产名录》"],"mem":"五大水系由北到南口诀：“海黄淮长钱”（海河、黄河、淮河、长江、钱塘江）。历史三节点：“春秋开邗沟、隋朝大贯通、元朝直通京”。","mix":"易混点：隋唐大运河以洛阳为中心、呈“人”字形，元代才绕开洛阳裁弯取直形成今京杭大运河；2014年申遗成功的官方名称是“中国大运河”，包含京杭、隋唐、浙东三部分。","mcq":[{"q":"京杭大运河自北向南沟通了中国五大水系，下列水系中不在其列的是","o":["海河水系","淮河水系","珠江水系","钱塘江水系"],"a":2,"w":"京杭大运河沟通海河、黄河、淮河、长江、钱塘江五大水系，不经过华南珠江水系。"}],"rel":[{"t":"隋炀帝与大运河","n":"大运河历史贯通阶段"},{"t":"大运河","n":"古代水利工程同题"},{"t":"巴拿马运河","n":"中外著名运河对照"},{"t":"苏伊士运河","n":"中外著名运河对照"}],"exam":[]},{"id":"a15-137","t":"中国五大淡水湖","cid":"15i","p":2,"kind":"合称","alias":["五大淡水湖"],"one":"按面积传统排序：鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖，均在长江与淮河流域。","ans":"中国五大淡水湖指**中国传统认定的五座面积最大淡水湖**，属中国地理高频合称。按面积由大到小依次为**鄱阳湖（江西）**、**洞庭湖（湖南）**、**太湖（苏浙）**、**洪泽湖（江苏）**和**巢湖（安徽）**，集中分布于**长江中下游及淮河流域**。五湖承担调蓄洪水、灌溉供水、维系湿地生态和支撑内河航运的功能，是江南鱼米之乡的重要生态屏障。","pts":["顺序：鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖","省区：江西、湖南、苏浙、江苏、安徽","集中于长江中下游及淮河流域"],"members":[["鄱阳湖","位于江西省北部，中国第一大淡水湖"],["洞庭湖","位于湖南省北部，中国第二大淡水湖"],["太湖","跨江苏、浙江两省（主体在江苏），第三大淡水湖"],["洪泽湖","位于江苏省西部，淮河中下游大型淡水湖"],["巢湖","位于安徽省中部，五大淡水湖中面积最小"]],"mem":"首字谐音口诀：“鄱洞太洪巢”→记成“破洞太红吵（一破洞、太红、太吵）”，配省份“赣湘苏浙苏皖”，全部在长江与淮河一带，没有青海湖！","mix":"最高频干扰项是“青海湖”（咸水湖，不在淡水湖之列）与“西湖”（面积远小于五大湖）。另按现代部分湖泊监测数据，内蒙古呼伦湖面积曾超过洪泽湖，但地理考试仍以传统五大淡水湖为准。","mcq":[{"q":"下列湖泊中，不属于“中国传统五大淡水湖”的是","o":["鄱阳湖","洪泽湖","巢湖","青海湖"],"a":3,"w":"中国五大淡水湖是鄱阳湖、洞庭湖、太湖、洪泽湖、巢湖；青海湖是咸水湖。"}],"rel":[{"t":"鄱阳湖与青海湖","n":"淡水湖与咸水湖之最"},{"t":"长江","n":"多湖属长江水系调蓄湖"},{"t":"中国地理之最","n":"同属中国地理常识"}],"exam":[]},{"id":"a15-138","t":"中国疆域与行政区划","cid":"15i","p":2,"kind":"常识","alias":["中国行政区划","34个省级行政区","14个陆上邻国"],"one":"陆地约960万平方千米；34省级行政区（23省5区4市2特区）；陆邻14国。","ans":"中国疆域与行政区划是**中国国情地理的基础数字常识**。中国陆地面积约**960万平方千米**，居世界第三位（仅次于俄、加），东临渤、黄、东、南四海。全国设**34个省级行政区**：**23个省、5个自治区、4个直辖市、2个特别行政区**。中国拥有**14个陆上邻国**和**6个隔海相望国家**。掌握这些核心数字，是理解中国边疆地理与国家治理的基础。","pts":["陆地面积约960万平方千米，居世界第三","34个省级区：23省、5自治区、4直辖市、2特区","14个陆上邻国、6个隔海相望国家"],"mem":"数字分解口诀：“960万三老大，34省分四家：23省、5自治、4直辖、2特区；陆邻14海望6”。5自治区记“内新广宁藏”，4直辖市记“京津沪渝”。","mix":"易错点：省级行政区总数是34个，其中“省”是23个（含台湾省），别把34和23混用；14个陆上邻国中，朝鲜、越南既陆上相邻又隔海相望，而隔海相望的6国指韩、日、菲、马、文莱、印尼。","mcq":[{"q":"中国现行34个省级行政区的组成结构为","o":["23个省、5个自治区、4个直辖市、2个特别行政区","22个省、5个自治区、5个直辖市、2个特别行政区","23个省、4个自治区、5个直辖市、2个特别行政区","24个省、5个自治区、3个直辖市、2个特别行政区"],"a":0,"w":"中国34个省级行政区由23个省、5个自治区、4个直辖市和2个特别行政区构成。"}],"rel":[{"t":"特别行政区基本法","n":"2个特别行政区宪制基础"},{"t":"“一国两制”","n":"港澳特别行政区制度"},{"t":"胡焕庸线","n":"国土人口空间格局"}],"more":"四至点：最东黑龙江与乌苏里江主航道中心线汇合处；最西新疆帕米尔高原；最北漠河以北黑龙江主航道中心线；最南南沙群岛曾母暗沙。","exam":[]},{"id":"a15-139","t":"帕米尔高原","cid":"15i","p":3,"kind":"地理","alias":["葱岭","波密罗","Pamir Mountains"],"one":"中亚东南部与新疆西南部、古称葱岭、连接中亚多国的高原与山结。","ans":"帕米尔高原**古称葱岭**，位于新疆西南部，与**塔吉克斯坦、阿富汗等国相接**。它是天山、昆仑山与喀喇昆仑山等交会的**巨大“山结”**，平均海拔超4000米，被称为“亚洲屋脊”。它是古代**丝绸之路翻越南亚与中亚的咽喉要道**。","pts":["古称葱岭，地跨中国新疆与塔吉克斯坦、阿富汗","多条大山脉交汇的巨大山结，号称亚洲屋脊","古丝绸之路通往中亚、南亚的重要枢纽"],"mem":"口诀：“帕米尔古称葱岭，塔吉阿富汗紧接引”。交大2010选择考过葱岭接壤邻国。","mix":"帕米尔高原在中国古籍中称为“葱岭”；中国四大高原是青藏高原、内蒙古高原、黄土高原和云贵高原，帕米尔高原不属于中国“四大高原”统计范畴。","mcq":[{"q":"中国古籍中称为“葱岭”，地跨中国新疆西南部并与塔吉克斯坦、阿富汗相接的高原是","o":["青藏高原","云贵高原","蒙古高原","帕米尔高原"],"a":3,"w":"帕米尔高原古称葱岭，跨中国新疆及塔吉克斯坦、阿富汗等国，是古丝绸之路要道。"}],"rel":[{"t":"帕米尔高原（葱岭）","n":"古籍称谓与同义概念"},{"t":"丝绸之路：长安-天山廊道路网","n":"古代丝路关键地理节点"},{"t":"塔里木盆地","n":"邻近大型盆地地理骨架"}],"exam":[]},{"id":"a15-140","t":"世界地理之最","cid":"15i","p":2,"kind":"合称","alias":["世界之最地理","全球地理之最"],"one":"尼罗河最长、亚马孙河流域最大、珠峰最高、马里亚纳最深、里海最大湖、贝加尔最深。","ans":"世界地理之最指**全球陆海在长度、面积、海拔或深度上居首的代表性地标**，属百科高频合称。水文方面，**尼罗河**最长，**亚马孙河**流域面积与流量最大，太平洋最大，**里海**是最大咸水湖，**贝加尔湖**是最深淡水湖，**马里亚纳海沟**最深。陆地方面，**珠穆朗玛峰**最高，**格陵兰岛**是最大岛屿，撒哈拉为最大热带沙漠。集中辨析口径可防混淆。","pts":["河海：尼罗河最长、亚马孙流域最大、马里亚纳最深","湖泊：里海面积最大（咸水）、贝加尔湖最深（淡水）","陆地：珠峰最高、格陵兰岛最大、撒哈拉热带沙漠最大"],"members":[["尼罗河","世界传统最长河流，流经非洲东北部，约6650千米"],["亚马孙河","世界流域面积最大、流量最大的河流，位于南美洲"],["珠穆朗玛峰","世界海拔最高峰，2020年公布雪面高程8848.86米"],["马里亚纳海沟","世界最深海沟，位于西太平洋，最深约11000米"],["太平洋","世界面积最大、平均水深最深的大洋"],["格陵兰岛","世界面积最大的岛屿，约216万平方千米，属丹麦"],["里海","世界面积最大的湖泊（咸水湖），位于亚欧交界"],["贝加尔湖","世界最深（1642米）、蓄水量最大的淡水湖，位于俄罗斯"],["撒哈拉沙漠","世界面积最大的热带沙漠，位于非洲北部，约920万平方千米"]],"mem":"分组对比记：“两河”尼长亚大（尼罗河长、亚马孙流域流量大）；“两湖”里大贝深（里海面积最大咸水、贝加尔湖最深淡水）；“陆海极值”珠峰高、马沟深、格岛大、撒沙广。","mix":"高频易混：世界面积最大的“淡水湖”是北美苏必利尔湖，而非里海（最大咸水湖）或贝加尔湖（最深淡水湖）；格陵兰岛是最大岛屿，澳大利亚大陆属于最小大陆而非岛屿；部分新测算认为亚马孙河长度超尼罗河，但考试仍以尼罗河最长为通行口径。","mcq":[{"q":"下列关于“世界地理之最”的对应关系中，完全正确的一项是","o":["世界最深的湖泊：里海","世界流域面积最大的河流：亚马孙河","世界面积最大的淡水湖：贝加尔湖","世界面积最大的岛屿：澳大利亚"],"a":1,"w":"亚马孙河流域面积和流量居世界第一；最深湖是贝加尔湖，最大淡水湖是苏必利尔湖，最大岛屿是格陵兰岛。"}],"rel":[{"t":"珠穆朗玛峰","n":"世界最高峰专题"},{"t":"七大洲四大洋","n":"太平洋等大洋大洲格局"},{"t":"尼罗河","n":"世界传统最长河流"},{"t":"世界湖泊之最","n":"里海与贝加尔湖细化"},{"t":"世界河流之最","n":"尼罗河与亚马孙河细化"}],"exam":[]},{"id":"d15-001","t":"八一南昌起义","cid":"15e","p":1,"kind":"事件","alias":["南昌起义","八一起义"],"one":"1927年8月1日周恩来等领导的武装起义，打响武装反抗第一枪，八一建军节由来。","ans":"八一南昌起义是**1927年8月1日**中国共产党在**江西南昌**发动的武装起义，属大革命失败后的重大革命转折事件。起义由**周恩来**任中共前敌委员会书记，**贺龙、叶挺、朱德、刘伯承**等率部举行，占领南昌城后南下广东，部分部队后转战井冈山。起义**打响了武装反抗国民党反动派的第一枪**，标志党独立领导革命战争、创建**人民军队**的开端。**1933年**8月1日被定为**建军节**，2027年将迎建军百年。","pts":["1927年8月1日南昌起义，周恩来等领导","打响武装反抗第一枪，创建人民军队开端","1933年定为建军节，2027年建军百年"],"mem":"五位主要领导人口诀：**“周贺叶朱刘”**（周恩来前委书记、贺龙总指挥、叶挺前敌总指挥、朱德、刘伯承参谋长）。时间双节点：1927年起义、1933年正式定节，与同年秋收起义、广州起义合称1927年三大起义。","mix":"南昌起义确立“八一建军节”，但首次公开打出“工农革命军”旗帜的是同年9月毛泽东领导的秋收起义；建军节获中华苏维埃共和国正式批准是在1933年7月11日，并非1927年当年。","mcq":[{"q":"1927年8月1日领导八一南昌起义的中共前敌委员会书记是","o":["朱德","周恩来","贺龙","叶挺"],"a":1,"w":"八一南昌起义由周恩来任中共前敌委员会书记，贺龙任总指挥，叶挺任前敌总指挥，刘伯承任参谋长。"},{"q":"下列关于八一南昌起义的表述，错误的是","o":["打响了武装反抗国民党反动派的第一枪","标志着中国共产党独立创建人民军队的开始","是每年8月1日中国人民解放军建军节的由来","起义部队首次公开打出“工农革命军”旗帜"],"a":3,"w":"首次公开打出“工农革命军”旗帜的是1927年9月秋收起义；南昌起义当时仍沿用国民革命军番号。"}],"rel":[{"t":"八一建军节","n":"起义确立的军队节日"},{"t":"建军100周年","n":"2027年百年纪念起点"},{"t":"中国武装力量的构成","n":"人民军队创建源头"},{"t":"红军长征","n":"后续革命战争历程"}],"more":"1927年三大起义：8月1日南昌起义、9月9日秋收起义、12月11日广州起义。\n1933年7月11日中华苏维埃共和国临时中央政府批准8月1日为中国工农红军成立纪念日。","exam":[]},{"id":"d15-002","t":"审级制度","cid":"15d","p":3,"kind":"制度","alias":["四级两审终审制","审级"],"one":"我国实行四级法院两审终审制，最高法一审及小额诉讼等为例外。","ans":"审级制度指案件审理的层级结构。我国设**基层、中级、高级和最高人民法院**四级法院，普遍实行**两审终审制**，经两级法院审判裁判即生效。例外包括**最高法一审**与民事**小额诉讼**一审终审，死刑案件另须**死刑复核**。","pts":["基层、中级、高级、最高四级法院","普遍实行两审终审制，二审即终审","最高法一审与小额诉讼实行一审终审"],"mem":"核心八字口诀：**“四级两审，两头例外”**。最高头（最高法一审）和最小头（基层民事小额诉讼）都是一审终审，其余常规案件两审终审。","mix":"西方多国实行“三审终审制”，我国实行“两审终审制”；死刑复核程序属于特别核准监督程序，不计作第三审。","mcq":[{"q":"下列案件中，依据我国法律实行“一审终审”的是","o":["最高人民法院审理的第一审案件","中级人民法院审理的普通刑事案件","高级人民法院审理的普通民事案件","基层人民法院审理的重大行政案件"],"a":0,"w":"最高人民法院作为国家最高审判机关，其一审裁判即为终审裁判，当事人不得上诉。"}],"rel":[{"t":"两审终审制","n":"我国审级制度核心原则"},{"t":"最高人民法院与最高人民检察院","n":"四级法院最高层级"},{"t":"三大诉讼","n":"共同适用审级规则"}],"exam":[]},{"id":"d15-003","t":"《中华人民共和国检察公益诉讼法》","cid":"15c","p":2,"kind":"制度","alias":["检察公益诉讼法","公益诉讼法"],"one":"2026年11月6日通过的公益诉讼专门法，2027年1月1日起施行。","ans":"《中华人民共和国检察公益诉讼法》由**十四届全国人大常委会第二十五次会议于2026年11月6日通过**，**2027年1月1日起施行**，共6章53条，是公益司法保护的**专门法律**。它规定检察机关办理公益诉讼的管辖、立案调查、起诉、审判和执行：**行政公益诉讼**覆盖生态环境和资源保护、食品药品安全、安全生产、反电信网络诈骗、文化遗产保护等领域，先向行政机关提出**公益诉讼检察建议**；**民事公益诉讼新纳入垄断行为和侵害众多劳动者合法权益的行为**。工作原则是客观公正、依法公开、保护优先、协同治理。","pts":["2026年11月6日通过，2027年1月1日施行，6章53条","行政公益诉讼：生态、食药、安全生产等，先发检察建议","民事公益诉讼新增垄断、侵害众多劳动者权益"],"mem":"日期“**11·6 通过，元旦施行**”；同一天通过的还有《南极活动与环境保护法》《反跨境腐败法》。行政公益诉讼领域串成一句：**生（生态）食（食药）安（安全生产）电（电信诈骗）文（文化遗产）**。","mix":"同日通过的三部法律施行日期不同：本法和《南极活动与环境保护法》2027年1月1日施行，《反跨境腐败法》自公布之日起施行；《生态环境法典》2026年8月15日施行，其中也有环境公益诉讼的衔接规定。","mcq":[{"q":"《中华人民共和国检察公益诉讼法》的施行日期是","o":["2026年11月6日","2026年8月15日","2027年1月1日","2026年1月1日"],"a":2,"w":"2026年11月6日通过，2027年1月1日起施行；2026年8月15日是《生态环境法典》施行日。"}],"rel":[{"t":"生态环境法典","n":"环境公益诉讼衔接"},{"t":"《中华人民共和国南极活动与环境保护法》","n":"同日通过"},{"t":"《中华人民共和国反跨境腐败法》","n":"同日通过"}],"more":"2026年11月6日：十四届全国人大常委会第二十五次会议通过，主席令第八十六号公布\n2027年1月1日：施行\n结构：6章53条","exam":[]},{"id":"d15-004","t":"《中华人民共和国南极活动与环境保护法》","cid":"15c","p":2,"kind":"制度","alias":["南极活动与环境保护法","南极法"],"one":"2026年11月6日通过的极地专门立法，2027年1月1日起施行。","ans":"《中华人民共和国南极活动与环境保护法》由**十四届全国人大常委会第二十五次会议于2026年11月6日通过**，**2027年1月1日起施行**，用于规范南极活动、保护南极环境、履行我国参加的**南极相关条约**。主要规定：开展南极活动须取得**行政许可**（仅过境不靠岸的航运除外）；禁止引入外来动植物、采集陨石；**禁止军事性质的措施**和**与矿产资源有关的活动**（科学研究除外）。我国**1983年加入《南极条约》**，1985年建成第一座南极考察站长城站，2024年建成第五座秦岭站。","pts":["2026年11月6日通过，2027年1月1日施行","南极活动须行政许可；禁军事、禁采矿","衔接南极条约体系；中国1983年加入，五座考察站"],"mem":"“**一许可，两禁止**”：活动要许可，军事和采矿都禁止。五座南极站按建成先后记“**长中昆泰秦**”：长城站1985、中山站1989、昆仑站2009、泰山站2014、秦岭站2024。","mix":"本法是国内法，《南极条约》是1959年签署的国际条约；禁止采矿的国际规则来自1991年《关于环境保护的南极条约议定书》。长城站是第一座站，昆仑站是第一座内陆站，秦岭站是第五座。","mcq":[{"q":"我国第五座南极考察站是","o":["昆仑站","泰山站","秦岭站","长城站"],"a":2,"w":"秦岭站2024年2月建成；长城站1985年、中山站1989年、昆仑站2009年、泰山站2014年。"}],"rel":[{"t":"《南极条约》","n":"对应的国际条约"},{"t":"《中华人民共和国检察公益诉讼法》","n":"同日通过"},{"t":"七大洲四大洋","n":"南极洲地理"}],"more":"2026年11月6日：通过\n2027年1月1日：施行\n中国南极考察站：长城站（1985）、中山站（1989）、昆仑站（2009，首个内陆站）、泰山站（2014）、秦岭站（2024年2月7日）","exam":[]},{"id":"d15-005","t":"《中华人民共和国反跨境腐败法》","cid":"15c","p":3,"kind":"制度","alias":["反跨境腐败法"],"one":"2026年11月6日通过，共六章47条，自公布之日起施行。","ans":"《中华人民共和国反跨境腐败法》于**2026年11月6日由十四届全国人大常委会第二十五次会议通过**，共六章47条，**自公布之日起施行**。它界定的跨境腐败包括向外国公职人员行贿、境外人员向境内公职人员行贿、境内主体在境外的职务违法犯罪，以及腐败人员外逃和转移腐败资产；由**国家监察委员会牵头**建立国家反跨境腐败工作机制，并要求跨境经营企业建立**廉洁合规管理制度**。","pts":["2026年11月6日通过，六章47条，公布即施行","国家监委牵头反跨境腐败工作机制","追逃追赃；跨境企业廉洁合规"],"mem":"抓“**一机制一合规**”：国家监委牵头的工作机制，跨境企业的廉洁合规制度。施行日期是同日三部法律里唯一“公布即施行”的。","mix":"同日通过的《检察公益诉讼法》《南极活动与环境保护法》都是2027年1月1日施行，本法自公布之日起施行。","mcq":[{"q":"根据《反跨境腐败法》，牵头建立国家反跨境腐败工作机制的是","o":["最高人民检察院","公安部","国家监察委员会","外交部"],"a":2,"w":"由国家监察委员会牵头。"}],"rel":[{"t":"国家监察委员会","n":"牵头机关"},{"t":"《监察法》","n":"监察法律体系"},{"t":"《中华人民共和国检察公益诉讼法》","n":"同日通过"}],"more":"2026年11月6日：通过，自公布之日起施行\n结构：六章47条","exam":[]},{"id":"d15-006","t":"达喀尔青年奥运会","cid":"15f","p":2,"kind":"时事","alias":["达喀尔青奥会","2026年青年奥运会","第四届夏季青年奥运会"],"one":"2026年在塞内加尔举行，首个在非洲举办的奥林匹克体育赛事。","ans":"达喀尔青年奥运会于**2026年10月31日开幕、11月13日闭幕**，在**塞内加尔达喀尔**举行，闭幕式在迪亚姆尼亚久青年奥运村举行。国际奥委会称它是**首个在非洲举办的奥林匹克体育赛事**。夏季青年奥运会面向青少年运动员，**2010年新加坡举办首届，2014年南京举办第二届**，2018年布宜诺斯艾利斯为第三届，达喀尔原定2022年举办，后推迟到2026年，是第四届。","pts":["2026年10月31日至11月13日，塞内加尔达喀尔","首个在非洲举办的奥林匹克体育赛事","青奥会：2010新加坡首届，2014南京第二届"],"mem":"夏季青奥会四站：“**新（新加坡2010）南（南京2014）布（布宜诺斯艾利斯2018）达（达喀尔2026）**”。“非洲第一次”是这届的考点。","mix":"达喀尔办的是青年奥运会，非洲至今没有举办过夏季或冬季奥运会；南京2014年办的是第二届夏季青奥会，不是首届。","mcq":[{"q":"首个在非洲举办的奥林匹克体育赛事是","o":["2010年南非世界杯","达喀尔青年奥运会","开罗奥运会","内罗毕亚运会"],"a":1,"w":"国际奥委会称2026年达喀尔青奥会是首个在非洲举办的奥林匹克体育赛事；世界杯是国际足联赛事。"}],"rel":[{"t":"第一届现代奥运会","n":"奥运史起点"},{"t":"中国首次参加奥运会","n":"奥运常识"}],"more":"2026年10月31日：开幕\n2026年11月13日：闭幕\n夏季青奥会：2010新加坡，2014南京，2018布宜诺斯艾利斯，2026达喀尔","exam":[]}],"tables":[{"name":"宪法规定的国家机构与职权","note":"每日练错题（●）：解释宪法的是全国人大常委会，修改宪法的是全国人大；特赦由全国人大常委会决定、国家主席发布特赦令。","rows":[["机构","性质","典型职权"],["全国人民代表大会","最高国家权力机关","修改宪法；监督宪法实施；制定和修改刑事、民事、国家机构的和其他基本法律；选举国家主席、副主席；根据主席提名决定国务院总理人选"],["全国人大常委会","全国人大的常设机关","解释宪法、监督宪法实施；制定和修改基本法律以外的其他法律；在全国人大闭会期间对基本法律作部分补充和修改；解释法律；决定特赦"],["国家主席","国家元首","根据全国人大及其常委会的决定公布法律、任免国务院组成人员、授予国家勋章和荣誉称号、发布特赦令、宣布进入紧急状态和战争状态、发布动员令"],["国务院","最高国家行政机关（中央人民政府）","根据宪法和法律规定行政措施、制定行政法规、发布决定和命令；编制和执行国民经济和社会发展计划及国家预算"],["中央军事委员会","领导全国武装力量","实行主席负责制"],["国家监察委员会","最高监察机关","2018年设立，领导地方各级监察委员会"],["最高人民法院","最高审判机关","监督地方各级人民法院和专门人民法院的审判工作"],["最高人民检察院","最高检察机关（国家的法律监督机关）","领导地方各级人民检察院和专门人民检察院"]]}]});